(window.GIM_TS=window.GIM_TS||{})["Chagigah.1"]={"from":24,"a":[["\u0003קודם שנברא העולם,\u0004 שהתורה צריכה היתה להינתן אחרי אלף דור מבריאת העולם (\"דבר צוה לאלף דור\" תהלים קה, ח), אלא שהקדימה הקדוש ברוך הוא ונתנה לעשרים ושישה דורות, ונמצא כי תשע מאות שבעים וארבעה דורות היו צריכים להיברא \u0003ולא נבראו, עמד הקדוש ברוך הוא ושתלן\u0004 מעט מעט \u0003בכל דור ודור, והן הן עזי פנים שבדור,\u0004 השייכים לדורות שלא היו צריכים להיברא כלל.","\u0003ורב נחמן בר יצחק אמר: \"אשר קמטו\"\u0004 (איוב כב, טז) — \u0003לברכה הוא דכתיב\u0004 \u0005[שנאמר],\u0006 שפסוק זה אינו מדבר בפחותים ובמקוללים, אלא במבורכים. ועניינו — \u0003אלו תלמידי חכמים שמקמטין\u0004 (מכווצים ומקטינים) \u0003עצמן על דברי תורה בעולם הזה,\u0004 ו\u0003הקדוש ברוך הוא מגלה להם סוד לעולם הבא, שנאמר: \"נהר יוצק יסודם\"\u0004 (איוב כב, טז), שיזרום להם רוב שפע (\"נהר יוצק\") של דברי סוד (\"יסודם\").","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לחייא בר רב: בר אריא\u0004 \u0005[בן גדולים]!\u0006 \u0003תא אימא לך מילתא, מהני מילי מעליותא דהוה אמר אבוך\u0004 \u0005[בוא אומר לך דבר, מאותם הדברים הטובים שהיה אומר אביך].\u0006 וכך היה אומר: \u0003כל יומא ויומא\u0004 \u0005[יום ויום]\u0006 \u0003נבראין מלאכי השרת מנהר דינור, ואמרי\u0004 \u0005[ואומרים]\u0006 \u0003שירה\u0004 לה' \u0003ובטלי\u0004 \u0005[ובטלים,\u0006 וכלים\u0005]\u0006 מיד, \u0003שנאמר: \"חדשים לבקרים רבה אמונתך\"\u0004 (איכה ג, כג), שמלאכים חדשים מהללים את ה' בכל בוקר. ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דברי \u0003ר' שמואל בר נחמני.\u0004 ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: כל דיבור ודיבור שיוצא מפי הקדוש ברוך הוא — נברא ממנו מלאך אחד, שנאמר: \"בדבר ה' שמים נעשו וברוח פיו כל צבאם\"\u0004 (תהלים לג, ו), וצבא השמים הם המלאכים, ולדבריו אינם נבראים מנהר דינור אלא מדיבור ה'.","ועוד ביישוב סתירות, \u0003כתוב אחד אומר: \"לבושה כתלג חור ושער ראשה כעמר נקא\"\u0004 (דניאל ז, ט) \u0005[לבושו כשלג לבן ושיער ראשו כצמר\u0006 לבן \u0005נקי].\u0006 \u0003וכתיב\u0004 \u0005[ונאמר\u0006 גם כן\u0005]:\u0006 \u0003\"קוצותיו תלתלים שחרת כעורב\"\u0004 (שיר השירים ה, יא)! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 הדימוי הראשון שמדמים את ה' כבעל שיער לבן הוא כאשר הוא \u0003בישיבה\u0004 של מעלה, \u0003כאן\u0004 (\"שחורות כעורב\") — כאשר הוא \u0003במלחמה.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין לך נאה בישיבה\u0004 ללמד תורה \u0003אלא זקן, ואין לך נאה במלחמה אלא בחור,\u0004 ולכן מתואר הקדוש ברוך הוא בכל פעם בדימוי אחר.","ועוד, \u0003כתוב אחד אומר: \"כרסיה שביבין די נור\"\u0004 (דניאל ז, ט) \u0005[כסאו שביבי אש],\u0006 \u0003וכתוב אחד אומר: \"עד די כרסון רמיו ועתיק יומין יתב\"\u0004 (דניאל ז, ט), \u0005[עד אשר הובאו הכסאות ועתיק ימים ישב],\u0006 משמע ששני כסאות הם! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 כסא \u0003אחד לו ואחד לדוד. כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 בנושא זה: כסא \u0003אחד לו ואחד לדוד,\u0004 אלו \u0003דברי ר' עקיבא. אמר לו ר' יוסי הגלילי: עקיבא, עד מתי אתה עושה שכינה חול,\u0004 שאדם כביכול יושב על ידה?! \u0003אלא,\u0004 שני כסאות אלה הם \u0003אחד לדין ואחד לצדקה.\u0004","ושואלים: \u0003קיבלה מיניה\u0004 \u0005[ממנו]\u0006 ר' עקיבא את הדעה הזו, \u0003או לא קיבלה מיניה\u0004 \u0005[ממנו]?\u0006 ומביאים ראייה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא אחרת: שני כסאות אלה \u0003אחד לדין ואחד לצדקה,\u0004 אלו \u0003דברי ר' עקיבא. אמר לו ר' אלעזר בן עזריה: עקיבא, מה לך אצל הגדה!\u0004 אין זה תחום שבו כוחך גדול, \u0003כלך מדברותיך\u0004 (הולך את דבריך) \u0003אצל נגעים ואהלות,\u0004 כלומר, מוטב שתדבר ותלמד הלכות טומאת צרעת וטומאת המת שבהם כוחך גדול. \u0003אלא\u0004 שנים אלה הם \u0003אחד לכסא ואחד לשרפרף; כסא — לישב עליו, שרפרף — להדום רגליו, שנאמר: \"השמים כסאי והארץ הדם רגלי\"\u0004 (ישעיהו סו, א).","הוזכר שהלומד רזי תורה צריך שיהא שר בדרגת חמישים ונשוא פנים, ולא נתבארו הדברים, ומעתה דנים במקרא זה בפרטות. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: שמונה עשרה קללות קילל ישעיה את ישראל, ולא נתקררה דעתו,\u0004 לא נרגע, לא נתפייס, \u0003עד שאמר להם המקרא הזה\u0004 שקיללתו מרובה: \u0003\"ירהבו הנער בזקן והנקלה בנכבד\"\u0004 (ישעיהו ג, ד).","ושואלים: \u0003שמונה עשרה קללות מאי נינהו\u0004 \u0005[מה הן]?\u0006 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי הנה האדון ה' צבאות מסיר מירושלים ומיהודה משען ומשענה כל משען לחם וכל משען מים גבור ואיש מלחמה שופט ונביא וקסם וזקן. שר חמשים ונשוא פנים ויועץ וחכם חרשים ונבון לחש. ונתתי נערים שריהם ותעלולים ימשלו בם\"\u0004 (ישעיהו ג, א), ששמונה עשר הדברים המנויים שם יסורו מישראל.","ומסבירים: \u0003\"משען\" — אלו בעלי מקרא. \"משענה\" — אלו בעלי משנה, כגון ר' יהודה בן תימא וחביריו.\u0004 ומעירים: \u0003פליגו בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב פפא ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: שש מאות סדרי משנה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: שבע מאות סדרי משנה\u0004 שהיו בימיהם (שמהם נשארו רק שישה סדרים), והם היו בקיאים בהם.","\u0003\"כל משען לחם\" — אלו בעלי תלמוד, שנאמר\u0004 לגבי התורה: \u0003\"לכו לחמו בלחמי ושתו ביין מסכתי\"\u0004 (משלי ט, ה). \u0003\"וכל משען מים\" — אלו בעלי אגדה, שמושכין לבו של אדם כמים באגדה. \"גבור\" — זה בעל שמועות,\u0004 מי שיש בידו הלכות שקיבל מרבותיו. \u0003\"ואיש מלחמה\" — זה שיודע לישא וליתן במלחמתה של תורה\u0004 ולחדש בה דברים. \u0003\"שופט\" — זה דיין שדן דין אמת לאמיתו. \"נביא\" — כמשמעו. \"קוסם\" — זה מלך.\u0004 ומדוע מכנים אותו \"קוסם\" — \u0003שנאמר: \"קסם על שפתי מלך\"\u0004 (משלי טז, י). \u0003\"זקן\" — זה שראוי לישיבה\u0004 להיות בה ראש ומורה.","\u0003\"שר חמשים\" — אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שר חמשים\" אלא \"שר חומשין\" — זה שיודע לישא וליתן בחמשה חומשי תורה. דבר אחר: \"שר חמשים\"\u0004 יש להבינו \u0003כ\u0004פי שאמר \u0003ר' אבהו,\u0004 ש\u0003אמר ר' אבהו: מכאן שאין מעמידין מתורגמן על הצבור\u0004 (שיתרגם להם דברי תורה או דברי החכמים) מי שהוא \u0003פחות מחמשים שנה. \"ונשוא פנים\" — זה שנושאין פנים לדורו בעבורו.\u0004 ויש בכך אופנים שונים: יש שנושאים לו פנים \u0003למעלה\u0004 בעולם עליון, \u0003כגון ר' חנינא בן דוסא\u0004 שהתפלל על הדור ונענה בתפילותיו, ויש \u0003למטה, כגון ר' אבהו\u0004 שהיו נושאים פנים לישראל בגללו \u0003בי\u0004 \u0005[בבית]\u0006 ה\u0003קיסר.\u0004","\u0003\"יועץ\"\u0004 — הוא זה \u0003שיודע לעבר שנים ולקבוע חדשים,\u0004 שבקי במהלך הכוכבים ובחשבון העיבור. \u0003\"וחכם\" — זה תלמיד המחכים את רבותיו\u0004 בשאלותיו. \u0003\"חרשים\"\u0004 — כוונתו \u0003בשעה שפותח בדברי תורה הכל נעשין כחרשין,\u0004 שאינם מבינים דבריו לאשורם מפני עמקותם. \u0003\"ונבון\" — זה המבין דבר\u0004 חדש \u0003מתוך דבר\u0004 שלמד. \u0003\"לחש\" — זה שראוי למסור לו דברי תורה שניתנה בלחש,\u0004 כלומר סתרי תורה.","נאמר שם \u0003\"ונתתי נערים שריהם\"\u0004 (ישעיהו ג, ד), ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 עניינו\u0005]\u0006 של \u0003\"ונתתי נערים שריהם\"? אמר ר' אלעזר: אלו בני אדם שמנוערין מן המצות\u0004 שהם יעשו מנהיגי העם.","\u0003\"ותעלולים ימשלו בם\"\u0004 (ישעיהו ג, ד) — \u0003אמר רב פפא בר יעקב:\u0004 \"תעלולים\" משמעו — \u0003תעלי\u0004 \u0005[שועלים]\u0006 \u0003בני תעלי\u0004 \u0005[שועלים],\u0006 כלומר, אנשים פחותים מצד עצמם ומצד יחוסם. \u0003ולא נתקררה דעתו\u0004 של ישעיה הנביא \u0003עד שאמר להם \"ירהבו הנער בזקן והנקלה בנכבד\"\u0004 (ישעיהו ג, ה). \"הנער\" — \u0003אלו בני אדם שמנוערין מן המצות, ירהבו\u0004 ויתגאו \u0003ב\u0004פני \u0003מי שממולא במצות כרמון, \"והנקלה בנכבד\"\u0004 כוונתו — ש\u0003יבא מי ש\u0004עבירות \u0003חמורות דומות עליו\u0004 (נחשבות בדעתו) \u0003כקלות\u0004 (\"נקלה\") \u0003וירהבו במי ש\u0004אפילו עבירות \u0003קלות דומות עליו כחמורות\u0004 (\"נכבד\").","ועוד בביאורו של פרק זה, \u0003אמר רב קטינא: אפילו בשעת כשלונה של ירושלים — לא פסקו מהם בעלי אמנה,\u0004 אנשים הנאמנים בדבריהם, ואינם משקרים. \u0003שנאמר: \"כי יתפש איש באחיו בית אביו\u0004 (לאמר) \u0003שמלה לך קצין תהיה לנו\"\u0004 (ישעיהו ג, ו), ומפרש, שבאים לאדם ואומרים לו: \u0003דברים שבני אדם\u0004 דואגים שיהיו \u0003מתכסין כשמלה,\u0004 דברי תורה שהם דברים מכוסים ונסתרים, \u0003ישנן תחת ידך\u0004 שאתה בקי בהם.","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"והמכשלה הזאת\"\u0004 (ישעיהו ג, ו) — \u0003דברים שאין בני אדם עומדין עליהן אלא אם כן נכשל בהן\u0004 שאינם נקנים אלא על ידי נסיון רב — \u0003ישנן תחת ידך.\u0004 ואף שבאים לאדם ואומרים לו כל אלה, הרי הוא \u0003\"ישא ביום ההוא לאמר לא אהיה חבש ובביתי אין לחם ואין שמלה לא תשימני קצין עם\"\u0004 (ישעיהו ג, ז), ומה שאומר \u0003\"ישא\"\u0004 — \u0003אין \"ישא\" אלא לשון שבועה, שנאמר: \"לא תשא את שם ה' אלהיך\"\u0004 (שמות כ, ז), שהאיש הזה נשבע ואומר: \u0003\"לא אהיה חבש\",\u0004 פירושו: \u0003לא הייתי מחובשי\u0004 (מיושבי) \u0003בית המדרש\u0004 מעולם, \u0003\"ובביתי אין לחם ואין שמלה\" — שאין בידי לא מקרא ולא משנה ולא גמרא.\u0004 הרי שאפילו בזמן ירידתה של ירושלים אנשיה היו מודים על האמת, ומודיעים שלא למדו כלל.","ומקשים: \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם],\u0006 \u0003דאי אמר להו גמירנא\u0004 \u0005[שאם יאמר להם למדתי]\u0006 \u0003אמרי ליה\u0004 \u0005[יאמרו לו]:\u0006 \u0003אימא לן\u0004 \u0005[אמור לנו]\u0006 וכיון שהדבר ניתן להיבדק בקלות, אין אדם משקר בו. ודוחים: אם היה שקרן, הרי \u0003הוה ליה למימר\u0004 \u0005[היה לו לומר]\u0006 כי \u0003גמר\u0004 \u0005[למד]\u0006 \u0003ושכח,\u0004 שלא לבייש עצמו. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא אהיה חבש\"\u0004 משמע שעד עכשיו למד — פירושו: \u0003לא אהיה חובש כלל,\u0004 שמעולם לא למדתי. הרי שבכל זאת היו בעלי אמנה.","ומקשים: \u0003איני\u0004 \u0005[האם כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: לא חרבה ירושלים עד שפסקו ממנה בעלי אמנה, שנאמר: \"שוטטו בחוצות ירושלים וראו נא ודעו ובקשו ברחובותיה אם תמצאו איש אם יש עשה משפט מבקש אמונה ואסלח לה\"\u0004 (ירמיהו ה, א), משמע שבזמן ההוא לא היו בעלי אמנה כלל! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006"],["\u0003הא\u0004 \u0005[זה]\u0006 \u0003בדברי תורה, הא\u0004 \u0005[זה]\u0006 \u0003במשא ומתן,\u0004 ש\u0003בדברי תורה הוו\u0004 \u0005[היו]\u0006 נאמנים, \u0003במשא ומתן — לא הוו\u0004 \u0005[היו]\u0006 נאמנים.","ומכאן שוב לענין מעשה מרכבה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה ברבן יוחנן בן זכאי שהיה רוכב על החמור, והיה מהלך בדרך, ור' אלעזר בן ערך\u0004 תלמידו \u0003מחמר אחריו. אמר לו\u0004 ר' אלעזר: \u0003רבי, שנה לי פרק אחד במעשה מרכבה. אמר לו:\u0004 וכי \u0003לא כך שניתי לכם: ולא\u0004 דורשים \u0003במרכבה ביחיד אלא אם כן היה חכם מבין מדעתו? אמר לו\u0004 ר' אלעזר: \u0003רבי, תרשיני לומר לפניך דבר אחד שלמדתני.\u0004 כלומר, בלשון ענוה, ביקש לומר לפניו מה שהוא מבין מדעתו בענין זה. \u0003אמר לו: אמור.\u0004","\u0003מיד ירד רבן יוחנן בן זכאי מעל החמור, ונתעטף\u0004 בטליתו על ראשו בדרך כבוד ויראה, \u0003וישב על האבן תחת\u0004 עץ \u0003הזית. אמר לו\u0004 ר' אלעזר: \u0003רבי, מפני מה ירדת מעל החמור? אמר: אפשר אתה דורש במעשה מרכבה, ושכינה עמנו, ומלאכי השרת מלוין אותנו, ואני ארכב על החמור?! מיד פתח ר' אלעזר בן ערך במעשה המרכבה ודרש. וירדה אש מן השמים, וסיבבה\u0004 את \u0003כל האילנות שבשדה, פתחו\u0004 כל האילנות \u0003כולן ואמרו שירה.\u0004","ו\u0003מה שירה אמרו — \"הללו את ה' מן הארץ תנינים וכל תהמות... עץ פרי וכל ארזים... הללויה\"\u0004 (תהלים קמח, ז. ט. יד), \u0003נענה מלאך מן האש, ואמר: הן הן מעשה המרכבה,\u0004 שכמו שדרש, כך הוא באמת. \u0003עמד רבן יוחנן בן זכאי, ונשקו על ראשו, ואמר: ברוך ה' אלהי ישראל שנתן בן לאברהם אבינו\u0004 כמוך, \u0003שיודע להבין ולחקור ולדרוש במעשה מרכבה. יש נאה דורש ואין נאה מקיים,\u0004 יש \u0003נאה מקיים ואין נאה דורש,\u0004 ואילו \u0003אתה נאה דורש ונאה מקיים. אשריך אברהם אבינו שאלעזר בן ערך יצא מחלציך.\u0004","ומסופר: \u0003וכשנאמרו הדברים לפני ר' יהושע\u0004 מעשה זה שאירע לר' אלעזר בן ערך חבירו, \u0003היה הוא ור' יוסי הכהן מהלכים בדרך. אמרו: אף אנו נדרוש במעשה מרכבה. פתח ר' יהושע ודרש. ואותו היום תקופת תמוז היה\u0004 שאין עננים בשמים, \u0003נתקשרו שמים בעבים\u0004 (עננים) \u0003ונראה כמין קשת בענן, והיו מלאכי השרת מתקבצין ובאין לשמוע, כבני אדם שמתקבצין ובאין לראות במזמוטי\u0004 (בשמחת) \u0003חתן וכלה.\u0004","\u0003הלך ר' יוסי הכהן וסיפר\u0004 את ה\u0003דברים לפני רבן יוחנן בן זכאי\u0004 מה שאירע להם. \u0003ואמר\u0004 לו רבן יוחנן: \u0003אשריכם ואשרי יולדתכם, אשרי עיני שכך ראו\u0004 תלמידים כאלה. \u0003ואף אני ואתם,\u0004 ראיתי \u0003בחלומי,\u0004 ש\u0003מסובין היינו על הר סיני, ונתנה עלינו בת קול מן השמים: עלו לכאן, עלו לכאן!\u0004 כי \u0003טרקלין\u0004 (אולמות) \u0003גדולים ומצעות נאות מוצעות לכם, אתם ותלמידיכם ותלמידי תלמידיכם מזומנין לכת שלישית,\u0004 מאלה שזוכות לקבל פני השכינה.","ושואלים: \u0003איני\u0004 \u0005[האם כן היה]?!\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: שלשה הרצאות הן,\u0004 כלומר, שלושה חכמים הם שנאמרו עליהם שהרצו הרצאות בתורת הסוד, \u0003ר' יהושע הרצה דברים לפני רבן יוחנן בן זכאי, ר' עקיבא הרצה לפני ר' יהושע, חנניא בן חכינאי הרצה לפני ר' עקיבא. ואילו\u0004 את \u0003ר' אלעזר בן ערך לא קא חשיב\u0004 \u0005[אינו מונה]\u0006 ביניהם, והרי מסופר שהרצה דברים לפני רבן יוחנן! ומשיבים: \u0003דארצי וארצו קמיה\u0004 \u0005[\u0006את מי \u0005שהרצה\u0006 דברים \u0005ו\u0006גם \u0005הרצו לפניו]\u0006 \u0003— קחשיב\u0004 \u0005[מונה],\u0006 ואולם \u0003דארצי ולא ארצו קמיה\u0004 \u0005[\u0006את מי \u0005שהרצה\u0006 דברים \u0005ולא הרצו לפניו]\u0006 — \u0003לא קא חשיב\u0004 \u0005[אינו מונה].\u0006 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חנניא בן חכינאי דלא ארצו קמיה\u0004 \u0005[שלא הרצו לפניו],\u0006 \u0003וקא חשיב\u0004 \u0005[והוא מונה\u0006 אותו\u0005]!\u0006 ומשיבים: \u0003דארצי מיהא קמיה מאן דארצי\u0004 \u0005[שהרצה על כל פנים\u0006 דברים \u0005לפני מי שהרצה\u0006 בפני רבו\u0005]\u0006 ולכן הכניסוהו לרשימה זו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבעה נכנסו בפרדס,\u0004 כלומר, עסקו בסתרי תורה עליונים, \u0003ואלו הן: בן עזאי, ובן זומא, אחר\u0004 (הוא אלישע בן אבויה), \u0003ור' עקיבא. אמר להם\u0004 והדריכם \u0003ר' עקיבא\u0004 שהיה הגדול שבהם: \u0003כשאתם מגיעין\u0004 בעלותכם לעולמות עליונים \u0003אצל אבני שיש טהור, אל תאמרו \"מים מים\",\u0004 אף על פי שנראים כמים, \u0003משום שנאמר: \"דובר שקרים לא יכון לנגד עיני\"\u0004 (תהלים קא, ז).","ומסופר מה אירע להם: \u0003בן עזאי הציץ\u0004 לצד השכינה — \u0003ומת, עליו הכתוב אומר: \"יקר בעיני ה' המותה לחסידיו\"\u0004 (תהלים קטז, טו). \u0003בן זומא הציץ\u0004 לצד השכינה \u0003ונפגע,\u0004 כלומר, יצא מדעתו, \u0003ועליו הכתוב אומר: \"דבש מצאת אכל דיך פן תשבענו והקאתו\"\u0004 (משלי כה, טז). \u0003אחר קיצץ בנטיעות,\u0004 כלומר, יצא לתרבות רעה. \u0003ר' עקיבא יצא בשלום.\u0004","ומספרים על גדולתו של בן זומא, כמה גדול היה כמפרש התורה, שהיה מוצא ראיות לדברים סתומים; \u0003שאלו את בן זומא: מהו\u0004 הדין, האם מותר \u0003לסרוסי כלבא\u0004 \u0005[לסרס כלב]?\u0006 שהרי לכאורה איסור סירוס כתוב בין המומים שבקרבנות, והאם מותר לסרס בעל חיים שאינו כשר לקרבן? \u0003אמר להם:\u0004 כתוב \u0003\"\u0004ומעוך וכתות ונתוק וכרות לא תקריבו לה' \u0003ובארצכם לא תעשו\"\u0004 (ויקרא כב, כד), ללמד: \u0003כל\u0004 בעל חיים \u0003שבארצכם לא תעשו\u0004 בו מעשה זה. ועוד \u0003שאלו את בן זומא:\u0004 אשה שמוחזק לנו בה שהיא \u0003בתולה, שעיברה\u0004 (שהיא בהריון), \u0003מהו\u0004 הדין, האם היא מותרת להינשא \u0003לכהן גדול\u0004 שמותר לו לשאת רק בתולה? והשאלה היא: \u0003מי חיישינן\u0004 \u0005[האם חוששים אנו]\u0006 \u0003ל\u0004מה שאמר \u0003שמואל,\u0004 ש\u0003אמר שמואל:\u0004"],["\u0003יכול אני לבעול כמה בעילות בלא דם,\u0004 כלומר, לבעול אשה בלא שהבתולים ייפגעו. ואם כן, יש לחשוש שמא אותה בתולה נבעלה בדרך זו, והריהי אסורה לכהן. \u0003או דלמא\u0004 \u0005[שמא]\u0006 מי שמסוגל לעשות כ\u0003שמואל לא שכיחא\u0004 \u0005[מצוי]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 מי שמסוגל לעשות כ\u0003שמואל לא שכיח\u0004 \u0005[מצוי],\u0006 \u0003וחיישינן\u0004 \u0005[ואנחנו חוששים]\u0006 לדבר אחר — \u0003שמא באמבטי עיברה,\u0004 שמא היתה באמבטיה, והיתה שם שכבת זרע של גבר ועל ידה התעברה, אף על פי שהיא בתולה.","ושואלים: איך יתכן שתתעבר באופן כזה? \u0003והאמר\u0004 \u0005[והרי אמר],\u0006 \u0003שמואל: כל שכבת זרע שאינו יורה כחץ — אינו מזרעת!\u0004 ומשיבים: אין הכוונה שצריך להיות בשעת ההפריה יורה כחץ, אלא \u0003מעיקרא נמי\u0004 \u0005[מתחילה\u0006 כשיצא מהאיש \u0005גם כן]\u0006 \u0003יורה כחץ הוה\u0004 \u0005[היה]\u0006 ולכן יכול היה להפרות אשה אף לאחר מכן.","ובענין מה שאירע לבן זומא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' יהושע בן חנניה שהיה עומד על גב\u0004 (גבי) \u0003מעלה\u0004 (מדרגה) \u0003בהר הבית, וראהו בן זומא ולא עמד מלפניו.\u0004 מפני שהיה שקוע במחשבה. \u0003אמר לו\u0004 ר' יהושע: \u0003מאין ולאין בן זומא?\u0004 כלומר, במה אתה מהרהר כעת? \u0003אמר לו: צופה הייתי\u0004 במחשבתי במעשה בראשית, במרחק ש\u0003בין מים העליונים למים התחתונים, ואין בין זה לזה אלא שלש אצבעות בלבד, שנאמר: \"ורוח אלהים מרחפת על פני המים\"\u0004 (בראשית א, ב) — \u0003כיונה שמרחפת על בניה ואינה נוגעת. אמר להן ר' יהושע לתלמידיו\u0004 ששמעו שיחה זו: \u0003עדיין בן זומא מבחוץ,\u0004 כלומר, עדיין לא הגיע להבנת הדברים בפנימיותם.","ומסבירים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003\"ורוח אלהים מרחפת על פני המים\" אימת הוי\u0004 \u0005[מתי היה\u0006 זה\u0005] —\u0006 \u0003ביום הראשון,\u0004 ואילו \u0003הבדלה\u0004 בין מים למים — \u0003ביום שני הוא דהואי\u0004 \u0005[שהיתה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי מבדיל בין מים למים\"\u0004 (בראשית א, ו), ואיך יכול בן זומא להביא משם ראיה? ושואלים: \u0003וכמה\u0004 היה ההבדל ביניהם באמת? \u0003אמר רב אחא בר יעקב: כמלא נימא\u0004 (חוט)? \u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים]:\u0006 \u0003כי גודא דגמלא\u0004 \u0005[כמו\u0006 הרווחים בין \u0005הלוחות של גשר].\u0006 \u0003מר זוטרא, ואי תימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב אסי\u0004 הוא ש\u0003אמר\u0004 זאת: \u0003כתרי גלימי דפריסי אהדדי\u0004 \u0005[כשתי גלימות שפרוסות זו על זו].\u0006 ויש משהו רווח ביניהן, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003כתרי כסי דסחיפי אהדדי\u0004 \u0005[כשתי כוסות המונחות זו על זו].\u0006","על \u0003אחר\u0004 אמרו ש\u0003קיצץ בנטיעות,\u0004 כלומר, הגיע לידי כפירה, ו\u0003עליו הכתוב אומר: \"אל תתן את פיך לחטיא את בשרך\"\u0004 (קהלת ה, ה). ושואלים: \u0003מאי היא\u0004 \u0005[מה היה\u0006 הענין\u0005]\u0006 הדבר שגרם לו לבוא לידי כפירה? \u0003חזא\u0004 \u0005[ראה]\u0006 את המלאך \u0003מיטטרון דאתיהבא ליה רשותא למיתב למיכתב זכוותא\u0004 \u0005[שניתנה לו רשות לשבת לכתוב\u0006 את \u0005זכויותיהם]\u0006 של \u0003ישראל, אמר: גמירא\u0004 \u0005[למודים\u0006 אנו\u0005]\u0006 ש\u0003למעלה,\u0004 בעולם העליון, \u0003לא הוי\u0004 \u0005[אין]\u0006 \u0003לא ישיבה, ולא תחרות, ולא עורף\u0004 (שהכל פונים כלפי שכינה), \u0003ולא עיפוי\u0004 (עייפות), וכיון שראה שיש מי שיושב, ואיננו הקדוש ברוך הוא, אלא מלאך עליון, אמר: \u0003שמא\u0004 (ואנחנו מוסיפים: \u0003חס ושלום), שתי רשויות הן,\u0004 שמלבד הקדוש ברוך הוא יש גם כוח ושלטון אחר, הממונה על העולם. ומכאן הגיע לידי כפירה.","ומספרים: \u0003אפקוהו\u0004 \u0005[הוציאוהו]\u0006 את \u0003מיטטרון\u0004 ממקומו בשמים \u0003ומחיוהו שיתין פולסי דנורא\u0004 \u0005[והיכוהו\u0006 ב\u0005שישים שבטים של אש]\u0006 שלא יבואו אחרים לטעות כמו אחר. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 למלאך: \u0003מאי טעמא כי חזיתיה לא קמת מקמיה\u0004 \u0005[מה הטעם כאשר ראית אותו,\u0006 את אלישע בן אבויה, \u0005לא עמדת מפניו]?\u0006 ועם זאת, כיון שהוא היה הנוגע בדבר \u0003איתיהיבא ליה רשותא למימחק זכוותא\u0004 \u0005[ניתנה לו\u0006 למיטטרון \u0005רשות למחוק את זכויותיו]\u0006 של \u0003אחר\u0004 ולהכשילו בכל דבר. \u0003יצתה בת קול ואמרה: \"שובו בנים שובבים\"\u0004 (ירמיהו ג, כב) — \u0003חוץ מאחר.\u0004","כיון ששמע זאת, \u0003אמר\u0004 אלישע בן אבויה: \u0003הואיל ואיטריד ההוא גברא מההוא עלמא\u0004 \u0005[ונטרד,\u0006 גורש, \u0005אותו אדם,\u0006 אני, \u0005מהעולם ההוא],\u0006 \u0003ליפוק ליתהני בהאי עלמא\u0004 \u0005[שיצא ויהנה בעולם הזה],\u0006 \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003אחר לתרבות רעה, נפק\u0004 \u0005[יצא],\u0006 \u0003אשכח\u0004 \u0005[מצא]\u0006 \u0003זונה\u0004 ו\u0003תבעה\u0004 לתשמיש, \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003ולאו\u0004 \u0005[ו\u0006האם \u0005לא]\u0006 \u0003אלישע בן אבויה אתה?\u0004 וכי אדם גדול כמוך עושה כזאת? \u0003עקר פוגלא ממישרא\u0004 \u0005[עקר צנון מן הערוגה]\u0006 \u0003בשבת ויהב\u0004 \u0005[ונתן]\u0006 \u0003לה,\u0004 להראות שאיננו שומר יותר את התורה, \u0003אמרה\u0004 הזונה: \u0003אחר הוא,\u0004 שודאי אין זה אלישע בן אבויה, ומשום כך קראהו \"אחר\".","מסופר: \u0003שאל אחר את ר' מאיר, לאחר שיצא\u0004 אחר \u0003לתרבות רעה, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"גם את זה לעמת זה עשה האלהים\"\u0004 (קהלת ז, יד)? \u0003אמר לו\u0004 ר' מאיר: \u0003כל מה שברא הקדוש ברוך הוא, ברא כנגדו\u0004 מעין זה, \u0003ברא הרים — ברא גבעות, ברא ימים — ברא נהרות.\u0004","\u0003אמר לו\u0004 אחר: \u0003ר' עקיבא רבך לא אמר כך, אלא\u0004 כך פירש: לכל דבר יש דבר כנגדו, \u0003ברא צדיקים — ברא רשעים, ברא גן עדן — ברא גיהנם, כל אחד ואחד\u0004 מבני אדם \u0003יש לו שני חלקים, אחד בגן עדן ואחד בגיהנם, זכה\u0004 ונעשה \u0003צדיק — נטל חלקו וחלק חברו\u0004 הרשע \u0003בגן עדן, נתחייב\u0004 ונהיה \u0003רשע — נטל חלקו וחלק חברו בגיהנם.\u0004","\u0003אמר רב משרשיא: מאי קראה\u0004 \u0005[מהו הפסוק]\u0006 המלמד על זה — \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003צדיקים כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"לכן בארצם משנה יירשו\"\u0004 (ישעיה סא, ז), \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003רשעים כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ומשנה שברון שברם\"\u0004 (ירמיהו יז, יח), שאצל כל אחד נאמר לשון \"משנה\", כלומר, חלק כפול.","ועוד \u0003שאל אחר את ר' מאיר לאחר שיצא לתרבות רעה: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"לא יערכנה זהב וזכוכית ותמורתה כלי פז\"\u0004 (איוב כח, יז), שאם בשבח התורה ובכבודה מדובר, היה לו להשוותה לזהב בלבד, אבל לא לזכוכית! \u0003אמר לו: אלו דברי תורה, שקשין לקנותם ככלי זהב וכלי פז, ונוחין לאבדן ככלי זכוכית. אמר לו\u0004 אחר: \u0003ר' עקיבא רבך לא אמר כך, אלא\u0004 כך אמר: \u0003מה כלי זהב וכלי זכוכית, אף על פי שנשברו — יש להם תקנה\u0004 שאפשר להתיך אותם ולעשות מהם כלים חדשים, \u0003אף תלמיד חכם, אף על פי שסרח — יש לו תקנה. אמר לו\u0004 ר' מאיר: אם כן, \u0003אף אתה חזור בך! אמר לו: כבר שמעתי מאחורי הפרגוד\u0004 (המסך המבדיל), המסתיר את הקדוש ברוך הוא מהעולם: \u0003\"שובו בנים שובבים\" — חוץ מאחר.\u0004","ועוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה באחר שהיה רוכב על הסוס בשבת, והיה ר' מאיר מהלך אחריו ללמוד תורה מפיו,\u0004 לאחר זמן \u0003אמר לו\u0004 אחר: \u0003מאיר, חזור לאחריך, שכבר שיערתי\u0004 וחישבתי \u0003בעקבי\u0004 (לפי עקבות, פסיעות) \u0003סוסי\u0004 ש\u0003עד כאן תחום שבת,\u0004 ומכאן והלאה אסור לך ללכת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' מאיר: \u0003אף אתה חזור בך,\u0004 כלומר, שיחזור למוטב. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ו\u0004האם \u0003לא כבר אמרתי לך\u0004 כי \u0003כבר שמעתי מאחורי הפרגוד — שובו בנים שובבים חוץ מאחר.\u0004","בכל זאת \u0003תקפיה עייליה לבי מדרשא\u0004 \u0005[החזיק בו\u0006 ר' מאיר ו\u0005הכניסו לבית המדרש],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחר \u0003לינוקא\u0004 \u0005[לתינוק]\u0006 כדרך ניחוש וסימן: \u0003פסוק לי פסוקך\u0004 (אמור לי את הפסוק שלמדת היום). \u0003אמר לו\u0004 את הפסוק: \u0003\"אין שלום אמר ה' לרשעים\"\u0004 (ישעיהו מח, כב). \u0003עייליה לבי כנישתא אחריתי\u0004 \u0005[הכניסו לבית מדרש אחר],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחר \u0003לינוקא\u0004 \u0005[לתינוק]:\u0006 \u0003פסוק לי פסוקך! אמר לו: \"כי אם תכבסי בנתר ותרבי לך ברית נכתם עונך לפני\"\u0004 (ירמיהו ב, כב). \u0003עייליה לבי כנישתא אחריתי\u0004 \u0005[הכניסו לבית מדרש אחר],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006"],["\u0003לינוקא\u0004 \u0005[לתינוק]:\u0006 \u0003פסוק לי פסוקך. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"ואת שדוד מה תעשי כי תלבשי שני כי תעדי עדי זהב כי תקרעי בפוך עיניך לשוא תתיפי\"\u0004 (ירמיהו ד, ל).","\u0003עייליה לבי כנישתא אחריתי, עד דעייליה לתליסר בי כנישתא, כולהו פסקו ליה כי האי גוונא\u0004 \u0005[הכניסו לבית כנסת אחר, עד שהכניסו לשלושה עשר בתי כנסת\u0006 וכל התינוקות \u0005כולם פסקו לו, כעין זה]\u0006 פסוקים האומרים שאין לו לרשע תקנה. \u0003לבתרא\u0004 \u0005[לאחרון]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פסוק לי פסוקך. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"ולרשע אמר אלהים מה לך לספר חקי\"\u0004 (תהלים נ, טז). ומספרים: \u0003ההוא ינוקא הוה\u0004 \u0005[אותו תינוק היה]\u0006 \u0003מגמגם בלישניה\u0004 \u0005[בלשונו],\u0006 \u0003אשתמע כמה דאמר ליה\u0004 \u0005[נשמע כאילו אומר לו]:\u0006 \u0003ולאלישע אמר אלהים,\u0004 ונראה לאלישע בן אבויה כאילו תינוק זה מתכוון להעליבו, \u0003איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 \u0003סכינא הוה בהדיה וקרעיה ושדריה לתליסר בי כנישתי\u0004 \u0005[סכין היתה עמו,\u0006 עם אחר, \u0005וקרע אותו,\u0006 את התינוק \u0005ושלח אותו לשלושה עשר בתי הכנסת].\u0006 \u0003ואיכא דאמרי\u0004 \u0005[יש אומרים]\u0006 ש\u0003אמר: אי הואי בידי סכינא, הוה קרענא ליה\u0004 \u0005[אם היתה בידי סכין, הייתי קורע אותו].\u0006","מסופר: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 מת\u0005]\u0006 \u0003אחר, אמרי\u0004 \u0005[אמרו]\u0006 בבית דין של מעלה: ש\u0003לא מידן לידייניה\u0004 \u0005[ידונו אותו]\u0006 \u0003ולא לעלמא דאתי ליתי\u0004 \u0005[יבוא לעולם הבא].\u0006 ש\u0003לא מידן לידייניה\u0004 \u0005[ידונו אותו]\u0006 כראוי לו — \u0003משום\u0004 ש\u0003עסק באורייתא\u0004 \u0005[בתורה],\u0006 וזכות התורה מגינה עליו, \u0003ו\u0004ש\u0003לא לעלמא דאתי ליתי\u0004 \u0005[יבוא לעולם הבא],\u0006 \u0003משום\u0004 ש\u0003חטא. אמר ר' מאיר: מוטב דלידייניה וליתי לעלמא דאתי\u0004 \u0005[שידונו אותו\u0006 כראוי \u0005ושיבוא לעולם הבא],\u0006 \u0003מתי אמות\u0004 ואז אבקש דבר זה בשמים, \u0003ואעלה עשן מקברו\u0004 שידעו שהוא נידון בגיהנם. ומספרים: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' מאיר סליק קוטרא מקבריה\u0004 \u0005[עלה עשן מקברו]\u0006 של \u0003אחר,\u0004 משמע, שנתקבלה בקשתו.","\u0003אמר ר' יוחנן:\u0004 וכי \u0003גבורתא\u0004 \u0005[גבורה]\u0006 היא \u0003למיקלא רביה\u0004 \u0005[לשרוף\u0006 את \u0005רבו]?!\u0006 ורק זו בלבד אפשר היה לעשות לתקנתו? \u0003חד הוה ביננא ולא מצינן לאצוליה\u0004 \u0005[אחד היה בינינו\u0006 בין החכמים שהתקלקל \u0005ואין אנחנו יכולים להצילו]?\u0006 \u0003אי נקטיה\u0004 \u0005[אם נחזיק אותו]\u0006 \u0003ביד, מאן מרמי ליה מאן\u0004 \u0005[מי יוציא אותו\u0006 מידינו, \u0005מי]?\u0006 \u0003אמר\u0004 ר' יוחנן: \u0003מתי אמות ואכבה עשן מקברו\u0004 להודיע שהוציאוהו מדין גיהנם והביאוהו לחיי עולם הבא. ואכן, \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' יוחנן פסק קוטרא מקבריה\u0004 \u0005[עשן מקברו]\u0006 של \u0003אחר, פתח עליה\u0004 \u0005[עליו]\u0006 \u0003ההוא ספדנא\u0004 \u0005[ספדן אחד]\u0006 בהספידו את ר' יוחנן, וכך אמר: \u0003אפילו שומר הפתח לא עמד לפניך, רבינו.\u0004 שהרי שומר הפתח של גיהנם לא יכול היה לעמוד בפני ר' יוחנן שהוציא את אחר משם.","מסופר: \u0003בתו של אחר אתיא לקמיה\u0004 \u0005[באה לפניו],\u0006 לפני \u0003רבי, אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003רבי, פרנסני,\u0004 שהיתה זקוקה למזונות. \u0003אמר לה: בת מי את? אמרה לו: בתו של אחר אני. אמר לה\u0004 בכעס: \u0003עדיין יש מזרעו בעולם?! והא כתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"לא נין לו ולא נכד בעמו ואין שריד במגוריו\"\u0004 (איוב יח, יט)! \u0003אמרה לו\u0004 לרבי: \u0003זכור לתורתו, ואל תזכור מעשיו. מיד ירדה אש וסכסכה\u0004 (לחכה) \u0003ספסלו של רבי. בכה ואמר רבי: ומה למתגנין בה\u0004 לאחר, שהתורה היתה מגונה בעיניו ופרש ממנה — \u0003כך,\u0004 הקדוש ברוך הוא מקפיד על כבודו, \u0003למשתבחין בה, על אחת כמה וכמה!\u0004","ושואלים: \u0003ור' מאיר היכי גמר\u0004 \u0005[כיצד למד]\u0006 \u0003תורה מפומיה\u0004 \u0005[מפיו]\u0006 של \u0003אחר? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כי שפתי כהן ישמרו דעת ותורה יבקשו מפיהו כי מלאך ה' צבאות הוא\"\u0004 (מלאכי ב, ז), ללמד: \u0003אם דומה הרב למלאך ה' צבאות\u0004 שהוא שלם במעשיו — \u0003יבקשו תורה מפיהו, ואם לאו — אל יבקשו תורה מפיהו!\u0004","\u0003אמר ריש לקיש: ר' מאיר קרא אשכח\u0004 \u0005[פסק מצא]\u0006 \u0003ודרש,\u0004 ועל פיו עשה כן, שנאמר: \u0003\"הט אזנך ושמע דברי חכמים ולבך תשית לדעתי\"\u0004 (משלי כב, יז), \u0003\"לדעתם\" — לא נאמר, אלא לדעתי.\u0004 כלומר: צריך לשמוע דברי חכמים, גם אם חכמים אלה פגומים הם, אבל אין לקבל דעתם אלא יש לשים לב לדעת המקום.","\u0003רב חנינא אמר\u0004 סמך לזה \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"שמעי בת וראי והטי אזנך ושכחי עמך ובית אביך\"\u0004 (תהלים מה, יא), שצריך לשמוע דברי החכם, אבל יש לשכוח צדדים פגומים שבתורתו.","ושואלים: אם כן, \u0003קשו קראי אהדדי\u0004 \u0005[קשים הכתובים זה על זה]?\u0006 שממקור אחד למדים שמותר ללמוד רק מחכם שמעשיו מושלמים, ובמקום אחר למדים שאפשר ללמוד גם ממי שהוא פגום במעשיו! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שמותר הרי זה \u0003ב\u0004אדם \u0003גדול, הא\u0004 \u0005[זה]\u0006 שאמרנו שאסור, הרי זה \u0003ב\u0004אדם \u0003קטן\u0004 שראוי לו ללמוד רק מאיש צדיק כדי שלא יתקלקל על ידי רבו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר, אמרי במערבא\u0004 \u0005[אומרים\u0006 אנשים \u0005בארץ ישראל]:\u0006 \u0003ר' מאיר אכל תחלא\u0004 \u0005[שחליים],\u0006 \u0003ושדא שיחלא לברא\u0004 \u0005[וזרק\u0006 את \u0005הקליפה לחוץ],\u0006 שיודע היה כיצד להוציא את התוכן החשוב מן הקליפה הרעה. \u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אל גנת אגוז ירדתי לראות באבי הנחל וגו'\"\u0004 (שיר השירים ו, יא), \u0003למה נמשלו תלמידי חכמים לאגוז — לומר לך: מה אגוז זה, אף על פי שמלוכלך בטיט ובצואה אין מה שבתוכו נמאס,\u0004 שרק הקליפה מתלכלכת ולא תוכו, \u0003אף תלמיד חכם, אף על פי שסרח\u0004 (חטא) — \u0003אין תורתו נמאסת.\u0004","מסופר: \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003רבה בר\u0004 \u0005[בנו]\u0006 של \u0003שילא לאליהו\u0004 הנביא, שהתגלה לו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 לאליהו: \u0003מאי קא עביד\u0004 \u0005[מה עושה]\u0006 \u0003הקדוש ברוך הוא? אמר ליה\u0004 \u0005[לו]\u0006 אליהו: \u0003קאמר שמעתא מפומייהו דכולהו רבנן\u0004 \u0005[אומר הוא הלכות מפיהם,\u0006 משמם \u0005של כל החכמים],\u0006 \u0003ומפומיה\u0004 \u0005[ומפיו,\u0006 משמו\u0005]\u0006 של \u0003ר' מאיר לא קאמר\u0004 \u0005[אינו אומר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי\u0004 \u0005[מדוע]?\u0006 אמר לו: \u0003משום דקא גמר שמעתא מפומיה\u0004 \u0005[שלמד הלכה מפיו]\u0006 של \u0003אחר. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 ידונו אותו לחובה על כך? הלא \u0003ר' מאיר רמון מצא, תוכו אכל, קליפתו זרק. אמר ליה\u0004 \u0005[לו]:\u0006 אכן, נשמעו דברי הסנגוריה שלך במרום, \u0003השתא קאמר\u0004 \u0005[עכשיו אומר]\u0006 הקדוש ברוך הוא, \u0003מאיר בני אומר: בזמן שאדם מצטער\u0004 וסובל, כגון שמלקים אותו, או ממיתים אותו בבית דין, \u0003שכינה, מה לשון אומרת: קלני\u0004 \u0005[אוי לי]\u0006 \u0003מראשי, קלני\u0004 \u0005[אוי לי]\u0006 \u0003מזרועי,\u0004 שאני משתתף בכאבו של אותו אדם. ו\u0003אם כך הקדוש ברוך הוא מצטער על דמן של רשעים — קל וחומר על דמן של צדיקים שנשפך.\u0004","מסופר: \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003שמואל\u0004 את \u0003רב יהודה דתלי בעיברא דדשא וקא בכי\u0004 \u0005[ש\u0006הוא \u0005תלוי,\u0006 נשען, \u0005על בריח הדלת ובוכה]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שיננא\u0004 \u0005[גדול השינים]!\u0006 \u0003מאי קא בכית\u0004 \u0005[\u0006על \u0005מה אתה בוכה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי זוטרא מאי דכתיב בהו ברבנן\u0004 \u0005[האם קטן\u0006 הוא \u0005מה שנאמר בהם ב\u0006אותם \u0005חכמים]\u0006 שחטאו: \u0003\"איה ספר איה שקל איה ספר את המגדלים\"\u0004 (ישעיהו לג, יח), ומפרשים: \u0003\"איה סופר\" — שהיו סופרים כל אותיות שבתורה. \"איה שוקל\" — שהיו שוקלים\u0004 ומשווים \u0003קלין וחמורין שבתורה. \"איה סופר את המגדלים\" — שהיו שונין שלש מאות הלכות\u0004 בפרטי דיני טומאת אוהל המת \u0003במגדל\u0004 (ארון עץ) \u0003הפורח באויר.\u0004 ואם בנושא כזה, שהיה רחוק מן המציאות, העמיקו כל כך, כל שכן בנושאים אחרים.","\u0003ואמר ר' אמי: תלת מאה בעיי בעו\u0004 \u0005[שלוש מאות שאלות שאלו]\u0006 \u0003דואג ואחיתופל במגדל הפורח באויר,\u0004 שהיו גדולים מאוד בתורה. \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשה מלכים וארבעה הדיוטות אין להם חלק לעולם הבא,\u0004 ודואג ואחיתופל ביניהם. והרי שגם חכמים גדולים אלה חטאו והפסידו חלקם בעולם הבא, אם כן, \u0003אנן מה תהוי עלן\u0004 \u0005[אנחנו,\u0006 הקטנים בחכמה, \u0005מה יהיה עלינו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שיננא\u0004 \u0005[גדול השינים]!\u0006 \u0003טינא\u0004 (פגימה) \u0003היתה בלבם\u0004 מתחילה, שהיו פגומים מתוכם מתחילה ולכן לא נחשבה להם תורתם ולא הגנה עליהם.","ומסבירים: \u0003אחר מאי\u0004 \u0005[מה]\u0006 היה בו — \u0003זמר יווני לא פסק מפומיה\u0004 \u0005[מפיו],\u0006 שהיה מזמר תמיד שירים יווניים אף בהיותו בין החכמים. משמע שעוד בתחילתו היה כרוך אחרי תרבות הגויים ואמונתם. כן \u0003אמרו עליו על אחר: בשעה שהיה עומד\u0004 (מפסיק מלימודו) \u0003מבית המדרש, הרבה ספרי מינין\u0004 היו \u0003נושרין מחיקו,\u0004 שהיה מחזיק וקורא בהם. הרי שאפילו בהיותו בבית המדרש כבר היה בו פגם מסויים, ולכן חטא.","\u0003שאל\u0004 הפילוסוף הגוי \u0003נימוס הגרדי את ר' מאיר:\u0004 האם \u0003כל עמר דנחית\u0004 \u0005[צמר שנכנס]\u0006 \u0003ליורה\u0004 להיצבע \u0003סליק\u0004 \u0005[עולה\u0006 לו הצבע\u0005]?\u0006 כלומר, האם כל הבאים ללמוד תורה כולם יוצאים אנשים הגונים וראויים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל מאן דהוה\u0004 \u0005[מי שהיה]\u0006 \u0003נקי אגב אימיה\u0004 \u0005[אימו],\u0006 מתחילתו — \u0003סליק\u0004 \u0005[עולה]\u0006 ו\u0003כל\u0004 מי ש\u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003נקי אגב אימיה\u0004 \u0005[אימו] —\u0006 \u0003לא סליק\u0004 \u0005[אינו עולה],\u0006 שמי שלא היה נקי והיה לו פגם מעיקרו אין התורה משפיעה עליו כראוי.","וחוזרים להשלים ענין ארבעה שנכנסו לפרדס. נאמר ש\u0003ר' עקיבא עלה בשלום וירד בשלום, ועליו הכתוב אומר: \"משכני אחריך נרוצה\u0004 הביאני המלך חדריו\u0003\"\u0004 (שיר השירים א, ד). מספרים: \u0003ואף ר' עקיבא בקשו מלאכי השרת לדוחפו\u0004 על שנכנס לפרדס, \u0003אמר להם הקדוש ברוך הוא: הניחו לזקן זה, שראוי להשתמש בכבודי.\u0004"],["\u0003מאי\u0004 \u0005[מה],\u0006 איזה פסוק \u0003דרש,\u0004 שידע להבחין, ולא טעה כאחר? \u0003אמר רבה בר בר חנה אמר ר' יוחנן,\u0004 נאמר: \u0003\"ואתה מרבבת קדש\"\u0004 (דברים לג, ב), ופירושו: \u0003אות הוא\u0004 (מיוחד הוא) \u0003ברבבה\u0004 (במלאכים) \u0003שלו,\u0004 ולפי זה הבחין שלא ראה אלא מלאך.","\u0003ור' אבהו אמר:\u0004 ר' עקיבא דרש מן הכתוב \u0003\"דגול מרבבה\"\u0004 (שיר השירים ה, י) — \u0003דוגמא\u0004 (כלומר, דבר הניכר במיוחד) \u0003הוא ברבבה שלו.\u0004","\u0003וריש לקיש אמר: \"ה' צבאות שמו\"\u0004 (ישעיהו מח, ב) — \u0003אדון הוא בצבא שלו.\u0004","\u0003ור' חייא בר אבא אמר\u0004 בשם \u0003ר' יוחנן: \"לא ברוח ה' ואחר הרוח רעש לא ברעש ה', ואחר הרעש אש לא באש ה' ואחר האש קול דממה דקה\",\u0004 ונאמר שם: \u0003\"והנה ה' עובר\"\u0004 (מלכים א' יט, יא-יב), והיה לו זה לסימן מהו מקום שכינתו.","ועוד בעניינים של מעלה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ששה דברים נאמרו בשדים: שלשה\u0004 דברים יש בהם \u0003כמלאכי השרת, ושלשה כבני אדם.\u0004 ומפרטים: \u0003שלשה כמלאכי השרת\u0004 — \u0003יש להם כנפים כמלאכי השרת, וטסין מסוף העולם ועד סופו כמלאכי השרת, ויודעין מה שעתיד להיות כמלאכי השרת.\u0004","ותוהים: \u0003יודעין סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 כיצד יכולים הם לדעת? והרי אף המלאכים אינם יודעים! \u0003אלא, שומעין מאחורי הפרגוד\u0004 מה שמגלה הקדוש ברוך הוא עתידות, \u0003כמלאכי השרת.\u0004","\u0003ושלשה כבני אדם — אוכלין ושותין כבני אדם, פרין ורבין כבני אדם, ומתים כבני אדם.\u0004","\u0003ששה דברים נאמרו בבני אדם, שלשה\u0004 מהם \u0003כמלאכי השרת, שלשה כבהמה.\u0004 ומפרטים: \u0003שלשה כמלאכי השרת — יש להם דעת כמלאכי השרת, ומהלכין בקומה זקופה כמלאכי השרת, ומספרים\u0004 (מדברים) \u0003בלשון הקדש כמלאכי השרת. שלשה\u0004 יש בהם \u0003כבהמה — אוכלין ושותין כבהמה, ופרין ורבין כבהמה, ומוציאין רעי\u0004 (זבל, צואה) \u0003כבהמה.\u0004","שנינו במשנה: \u0003כל המסתכל בארבעה דברים רתוי\u0004 (ראוי) \u0003לו שלא בא לעולם.\u0004 ואלו הם: מה למעלה, מה למטה, מה לפנים מה לאחור. ושואלים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן\u0005]\u0006 שלהתבונן \u0003מה למעלה מה למטה מה לאחור — לחיי\u0004 (בסדר), שכן הוא מתבונן בדברים שאינם בתוך מציאות העולם אלא מעבר לו. \u0003אלא לפנים — הלא מאי דהוה הוה\u0004 \u0005[מה שהיה היה]\u0006 ומדוע אין להתבונן בכך?","ומסבירים, \u0003ר' יוחנן ור' אלעזר דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003משל למלך בשר ודם שאמר לעבדיו: בנו לי פלטירין\u0004 (ארמונות) \u0003גדולים על האשפה, הלכו ובנו לו,\u0004 ומובן כי \u0003אין רצונו של מלך להזכיר שם אשפה.\u0004 ואף כך, אין הקדוש ברוך הוא רוצה שיעסקו בני אדם בתוהו ובוהו שלפני היות העולם.","שנינו במשנה: \u0003כל שלא חס על כבוד קונו, רתוי\u0004 \u0005[ראוי]\u0006 \u0003לו שלא בא לעולם.\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 דבר זה שאינו חס על כבוד קונו? \u0003ר' אבא אמר: זה המסתכל בקשת. רב יוסף אמר: זה העובר עבירה בסתר.\u0004 ומסבירים את דבריהם: \u0003מסתכל בקשת\u0004 יש בו זלזול כבוד השכינה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כמראה הקשת אשר יהיה בענן ביום הגשם כן מראה הנגה סביב הוא מראה דמות כבוד ה'\"\u0004 (יחזקאל א, כח), ואין זה כבוד להסתכל בדמות ה'.","\u0003רב יוסף אמר: זה העובר עבירה בסתר,\u0004 וטעמו \u0003כ\u0004דברי \u0003ר' יצחק.\u0004 ש\u0003אמר ר' יצחק: כל העובר עבירה בסתר כאילו דוחק\u0004 (דוחף, מרחיק) \u0003רגלי שכינה, שנאמר: \"כה אמר ה' השמים כסאי והארץ הדם רגלי\"\u0004 (ישעיהו סו, א), שאם סבור הוא שבסתר אין רואים אותו, הרי זה כאילו אמר שבמקום זה בארץ אין הקדוש ברוך הוא נמצא, וכאילו מוציא את הקדוש ברוך הוא מהדום רגליו.","ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעא הזקן: אם רואה אדם שיצרו מתגבר עליו ילך למקום שאין מכירין אותו, וילבש שחורין ויתעטף שחורין\u0004 כדרך אבלים, על שהוא נזקק לכך, \u0003ויעשה\u0004 שם \u0003מה שלבו חפץ, ואל יחלל שם שמים בפרהסיא,\u0004 הרי משמע שפעמים העובר עבירה בסתר עדיף מאשר העובר בגלוי! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שכשעובר עבירה בסתר אינו חס על כבוד קונו — הרי זה \u0003דמצי כייף ליה ליצריה\u0004 \u0005[כשיכול לכפות את יצרו]\u0006 ואינו כופהו אלא עובר עבירה בסתר, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שעדיף שיעבור עבירה בסתר — הרי זה באופן \u0003דלא מצי כייף ליצריה\u0004 \u0005[שאיננו יכול לכפות את יצרו]\u0006 ובלבד שלא יגרום לחילול השם ברבים.","\u0003דרש ר' יהודה בר' נחמני\u0004 שהיה \u0003מתורגמניה\u0004 \u0005[מתורגמנו]\u0006 של \u0003ריש לקיש: כל המסתכל בשלשה דברים\u0004 אלה \u0003עיניו כהות:\u0004 המסתכל \u0003בקשת, בנשיא, ובכהנים.\u0004 ומסבירים: \u0003בקשת — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כמראה הקשת אשר יהיה בענן ביום הגשם\u0004 כן מראה הנגה סביב \u0003הוא מראה דמות כבוד ה'\"\u0004 (יחזקאל א, כח). \u0003בנשיא — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונתת מהודך עליו\"\u0004 (במדבר כז, ב), משמע שיש עליו הוד שכינה. והדבר השלישי, בכהנים — הוא \u0003המסתכל בכהנים בזמן שבית המקדש קיים, שהיו עומדין על דוכנן ומברכין את ישראל בשם המפורש\u0004 שהיתה שכינה שורה על קשרי אצבעותיהם.","וכיון שהוזכר מה שאמר חכם זה, מביאים עוד מדבריו, \u0003דרש ר' יהודה בר' נחמני מתורגמניה\u0004 \u0005[מתורגמנו]\u0006 של \u0003ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אל תאמינו ברע אל תבטחו באלוף\"\u0004 (מיכה ז, ה) — \u0003אם יאמר לך יצר הרע: חטוא והקדוש ברוך הוא מוחל — אל תאמן, שנאמר: \"אל תאמן ברע\", ואין \"רע\" אלא יצר הרע, שנאמר: \"כי יצר לב האדם רע\"\u0004 (בראשית ח, כא),","\u0003ואין \"אלוף\" אלא הקדוש ברוך הוא, שנאמר: \"אלוף נערי אתה\"\u0004 (ירמיהו ג, ד). \u0003שמא תאמר\u0004 כיון שאני עושה בסתר \u0003מי מעיד בי? אבני ביתו וקורות ביתו של אדם הם מעידין בו, שנאמר: \"כי אבן מקיר תזעק וכפיס מעץ יעננה\"\u0004 (חבקוק ב, יא)","\u0003וחכמים אומרים: נשמתו של אדם\u0004 היא עצמה \u0003מעידה בו, שנאמר: \"משכבת חיקך שמר פתחי פיך\"\u0004 (מיכה ז, ה) — \u0003אי זו היא דבר ששוכבת בחיקו של אדם — הוי אומר זו נשמה. ר' זריקא אמר: שני מלאכי השרת המלוין אותו\u0004 את האדם \u0003הן\u0004 ש\u0003מעידין בו, שנאמר: \"כי מלאכיו יצוה לך לשמרך בכל דרכיך\"\u0004 (תהלים צא, יא). \u0003וחכמים אומרים: אבריו של אדם\u0004 הם ש\u0003מעידין בו, שנאמר: \"ואתם עדי נאם ה' ואני אל\"\u0004 (ישעיהו מג, יב), כלומר, האדם עצמו הוא נעשה עד ומעיד כנגד עצמו ביום הדין.","\u0003יוסי בן יועזר אומר שלא לסמוך\u0004 ביום טוב את ידיו על הקרבנות לפני שחיטתם, משום שיש בכך כעין עבודה בבהמה ביום טוב, וחבירו בן זוגו \u0003יוסף בן יוחנן אומר לסמוך, יהושע בן פרחיה אומר שלא לסמוך. ניתאי הארבלי אומר לסמוך, יהודה בן טבאי אומר שלא לסמוך, שמעון בן שטח אומר לסמוך, שמעיה אומר לסמוך, אבטליון אומר שלא לסמוך. הלל ומנחם לא נחלקו\u0004 בכך. \u0003יצא מנחם\u0004 מתפקידו ו\u0003נכנס\u0004 במקומו \u0003שמאי,\u0004 ו\u0003שמאי אומר שלא לסמוך, הלל אומר לסמוך.\u0004"],["\u0003הראשונים\u0004 שנימנו בכל זוג \u0003היו נשיאים, ושניים להם\u0004 היו \u0003אבות בית דין.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה מזוגות הראשונים שאמרו שלא לסמוך, ושנים מזוגות האחרונים שאמרו לסמוך, הראשונים היו נשיאים, ושניים להם אבות בית דין,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים\u0004 בחילוף: \u0003יהודה בן טבאי — אב בית דין\u0004 היה, \u0003ושמעון בן שטח נשיא.\u0004","ושואלים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי\u0006 הוא התנא ש\u0005שנה את זו ששנו חכמים]\u0006 בברייתא: \u0003אמר ר' יהודה בן טבאי: אראה בנחמה,\u0004 כלומר, אני נשבע, הלואי וכך אראה בנחמת ישראל \u0003אם לא הרגתי עד זומם,\u0004 כדי \u0003להוציא מלבן\u0004 (לעשות במכוון ובפומבי כנגד דעתם) \u0003של צדוקין. שהיו\u0004 הצדוקים \u0003אומרים: אין עדים זוממין נהרגין עד שיהרג הנידון,\u0004 ואילו לפי המסורת רק אם לא נהרג הנידון הורגים את העד הזומם.","\u0003אמר לו שמעון בן שטח: אראה בנחמה אם לא שפכת דם נקי, שהרי אמרו חכמים: אין עדים זוממין נהרגין עד שיזומו שניהם,\u0004 ולא אחד מהם בלבד. \u0003ואין לוקין\u0004 אם היו חייבים מלקות — \u0003עד שיזומו שניהם, ואין משלמין ממון\u0004 אם העלילו על אדם שהוא חייב כסף \u0003עד שיזומו שניהם.\u0004","כיון ששמע זאת, \u0003מיד קבל עליו יהודה בן טבאי שאינו מורה הלכה אלא בפני שמעון בן שטח,\u0004 שראה שאינו יכול לסמוך על דעת עצמו.","ומספרים עוד: \u0003כל ימיו של יהודה בן טבאי היה משתטח על קברו של אותו הרוג\u0004 לבקש מחילה, \u0003והיה קולו נשמע\u0004 בבכי. \u0003כסבורין העם לומר שקולו של הרוג הוא\u0004 שעולה מקברו. \u0003אמר להם\u0004 יהודה בן טבאי: \u0003קולי הוא,\u0004 ו\u0003תדעו\u0004 שכן הוא, \u0003שלמחר,\u0004 לעתיד, \u0003הוא,\u0004 כלומר, אני (וכינה בלשון זו כיון שלא רצה לומר דבר רע) \u0003מת, ואין קולו נשמע\u0004 עוד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 מכאן בעצם אין הוכחה, שאפשר היה עוד לומר \u0003ודלמא פיוסי פייסיה\u0004 \u0005[ושמא פייס אותו]\u0006 את הנהרג בעולם הבא, \u0003או\u0004 להיפך \u0003בדינא תבעיה\u0004 \u0005[\u0006ש\u0005בדין\u0006 שמים \u0005תבע אותו\u0006 הנהרג\u0005]\u0006 ולכן אין הקול נשמע עוד.","ולענייננו, \u0003מני הא\u0004 \u0005[\u0006כדעת \u0005מי\u0006 ברייתא \u0005זו]?\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שהיא שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר\u0004 כי \u0003שמעון בן שטח אב בית דין, ר' יהודה בן טבאי נשיא — היינו דקא מורי\u0004 \u0005[זה\u0006 הטעם \u0005שהיה מורה]\u0006 קודם לכן \u0003הלכה בפני שמעון בן שטח,\u0004 ורק לאחר מעשה זה קיבל עליו שלא יורה אלא בפניו. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שזו כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003יהודה בן טבאי אב בית דין\u0004 היה, \u0003שמעון בן שטח נשיא\u0004 היה, אם כן למה היה צריך לקבל עליו? הלא \u0003אב בית דין בפני נשיא מי\u0004 \u0005[האם]\u0006 \u0003מורה הלכה?\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קבל עליו\" דקאמר\u0004 \u0005[שאמר]\u0006 הוא לענין \u0003לאצטרופי\u0004 \u0005[להצטרף],\u0006 ש\u0003אפילו אצטרופי\u0004 \u0005[להצטרף]\u0006 בדין עם אחרים \u0003נמי לא מצטריפנא\u0004 \u0005[גם כן אינני מצטרף]\u0006 עד שאשמע את דעתו של שמעון בן שטח.","שנינו במשנה: \u0003יצא מנחם ונכנס שמאי.\u0004 ושואלים: \u0003להיכן יצא\u0004 מנחם? \u0003אביי אמר: יצא לתרבות רעה,\u0004 וכדי שלא לפרט בנושא אמרו בקיצור שיצא. \u0003רבא אמר: יצא לעבודת המלך,\u0004 שקיבל תפקיד בעבודת המלך ולא נשאר יותר בסנהדרין. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003יצא מנחם לעבודת המלך, ויצאו עמו\u0004 עוד \u0003שמונים זוגות תלמידים לבושין סיריקון\u0004 \u0005[בגדי משי],\u0006 שנכנסו לעבודת השלטונות, ולא עסקו עוד בתורה.","\u0003אמר רב שמן בר אבא אמר ר' יוחנן: לעולם אל תהא שבות\u0004 (מלאכה האסורה בשבת מדברי סופרים בלבד) \u0003קלה בעיניך, שהרי סמיכה\u0004 ביום טוב \u0003אינה\u0004 אסורה \u0003אלא משום שבות\u0004 (שהיא, כמו רכיבה, שימוש בבעלי חיים), שהרי אינה מלאכה ממש, לפי שאין בה אלא דמיון למלאכה, בכל זאת \u0003נחלקו בה גדולי הדור\u0004 במשך דורות רבים.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 כיון שתקנת חכמים מקובלת היא, מדוע תהיה קלה בעיני כל אדם? ומשיבים: \u0003שבות מצוה אצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 לומר. שהרי שבות זו של סמיכה איננה לצרכי האדם, אלא לצורך מצוה, ובכל זאת חמורה היתה בעיניהם.","ותוהים: \u0003הא נמי פשיטא\u0004 \u0005[גם זו פשוטה],\u0006 שהרי אף בזה אסרו חכמים! ומשיבים: דברי ר' יוחנן כאן \u0003לאפוקי ממאן דאמר\u0004 \u0005[להוציא מ\u0006דעת \u0005מי שאומר]\u0006 ש\u0003בסמיכה גופה פליגי\u0004 \u0005[עצמה נחלקו]\u0006 ועיקר המחלוקת היתה האם יש צורך לסמוך על שלמי חובה, או לא, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003בשבות הוא\u0004 הנושא \u0003דפליגי\u0004 \u0005[ש\u0006הם \u0005חלוקים\u0006 בו\u0005]\u0006 ולא בעצם הסמיכה.","\u0003אמר רמי בר חמא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 ממחלוקת זו, כי מצוות \u0003סמיכה\u0004 היא לא רק בזה שמניחים ידים על ראש הבהמה אלא יש להשען \u0003בכל כחו בעינן\u0004 \u0005[צריכים אנו].\u0006 \u0003דאי סלקא דעתך לא בעינן\u0004 \u0005[שאם עולה על דעתך\u0006 ש\u0005אין אנו צריכים]\u0006 \u0003בכל כחו, מאי קא עביד\u0004 \u0005[מה\u0006 איסור \u0005הוא עושה]\u0006 בהנחת היד? \u0003ליסמוך\u0004 \u0005[שיסמוך]\u0006 אף ביום טוב, שהרי אין זו מלאכה כלל!","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך, ממה שנאמר: \u0003\"דבר אל בני ישראל\"\u0004 (ויקרא א, ב), וסמוך אליו \u0003\"וסמך\u0004 ידו על ראש העולה\" (ויקרא א, ד), ומסמיכות הדברים למדים כי \u0003בני ישראל סומכין, ואין בנות ישראל סומכות. ר' יוסי ור' ישמעאל אומרים: בנות ישראל סומכות רשות,\u0004 שמותר להן לסמוך, אף שאינן חייבות בכך.","\u0003אמר ר' יוסי, סח לי\u0004 החכם \u0003אבא אלעזר: פעם אחת היה לנו עגל של זבחי שלמים, והביאנוהו לעזרת נשים וסמכו עליו נשים.\u0004 ו\u0003לא מפני ש\u0004יש חובת \u0003סמיכה בנשים, אלא כדי לעשות נחת רוח לנשים\u0004 שהן מקריבות קרבן בכל פרטיו ודקדוקיו כאנשים. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003סמיכה בכל כחו בעינן\u0004 \u0005[צריכים אנו],\u0006 וכי \u0003משום נחת רוח\u0004 של ה\u0003נשים עבדינן\u0004 \u0005[עושים אנו]\u0006 \u0003עבודה בקדשים?\u0004 שהרי הסמיכה בכח, שנשען על הבהמה, כמוה כעבודה שעושה בבהמת הקדשים ואם עושה אותה למרות שאינו מחוייב בה, נמצא עושה עבודה בקדשים! \u0003אלא לאו שמע מינה לא בעינן\u0004 \u0005[האם לא תלמד מכאן\u0006 ש\u0005אין אנו צריכים]\u0006 שתהא הסמיכה \u0003בכל כחו!\u0004","ודוחים: \u0003לעולם אימא\u0004 \u0005[אמור]\u0006 \u0003לך\u0004 כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהא הסמיכה \u0003בכל כחו,\u0004 וכאן, שהרשו לנשים לסמוך — \u0003דאמר להו\u0004 \u0005[שאומר להן]:\u0006 \u0003אקפו ידייכו\u0004 \u0005[הקלו את ידיכן],\u0006 אל תלחצו בכוח, אלא תסמכו רק בקלות, ואין בכך כל עבודה. ואומרים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שכך עשו, אם כן הטעם שנתנו \u0003\"לא מפני שסמיכה בנשים\"\u0004 אינו קשור להלכה זו, כי \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 התרת מעשה זה בנשים, משום ש\u0003אינה\u0004 נחשבת \u0003לסמיכה כלל,\u0004 שהרי אם סמיכה היא בכל כוחו, והן לא עשו כך, נמצא שלא היתה זו סמיכה כלל!","\u0003אמר ר' אמי: חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 \u0003ועוד\u0004 טעם \u0003קאמר\u0004 \u0005[אמר],\u0006 \u0003חדא\u0004 \u0005[אחד] —\u0006 \u0003דליתא\u0004 \u0005[שאינה\u0006 נחשבת\u0005]\u0006 \u0003לסמיכה כלל\u0004 כיון שלא היה בכל כוחן, \u0003ועוד\u0004 — שעשו זאת \u0003כדי לעשות נחת רוח לנשים.\u0004","\u0003אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכל דבר שאסור להשען או לשבת עליו בשבת ובחג — גם \u0003צדדין אסורין, דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003צדדין מותרין,\u0004 אם כן אפשר היה לומר לנשים \u0003לסמוך לצדדין,\u0004 ולא על גבה של הבהמה אלא על ראשה. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003צדדין אסורין.\u0004"],["\u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי \u0003צדדין\u0004 בכלל \u0003מותרין,\u0004 אולם מכאן אין הוכחה, כי \u0003כל\u0004 מה \u0003דבהדי\u0004 \u0005[שסמוך]\u0006 ל\u0003גבה\u0004 של הבהמה \u0003כגבה דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ולכן יש לומר שהנשען על ראשה של הבהמה הוא כנשען על הבהמה עצמה ולא על הצדדים.","\u0003בית שמאי אומרים: מביאין שלמים\u0004 בלבד כקרבן ביום טוב, משום שגם הבעלים והכהנים אוכלים אותם, \u0003ואין סומכין עליהם,\u0004 על השלמים, לפני הקרבתם \u0003אבל לא\u0004 יביא \u0003עולות\u0004 כלל, משום שהעולות אינן נאכלות, ולא הותרה מלאכה ביום טוב אלא לצורך אדם. \u0003ובית הלל אומרים: מביאין שלמים ו\u0004גם \u0003עולות, וסומכין עליהם.\u0004","ועוד: \u0003עצרת\u0004 (חג השבועות) \u0003שחל להיות בערב שבת, בית שמאי אומרים: יום טבוח,\u0004 היום שבו ממשיכים ושוחטים את הקרבנות שהביאו לכבוד הרגל הוא \u0003אחר השבת\u0004 (ביום ראשון), שהרי לדעתם עולת ראייה איננה קריבה ביום טוב עצמו אלא למחרתו (וכל העולות הפרטיות שנודרו נדחות למחרת), וכיון שהיום שלאחר החג שבת הוא, עושים את יום הטיבוח ביום הראשון. \u0003ובית הלל אומרים: אין יום טבוח אחר השבת,\u0004 שהרי אין צורך בכך, שכן יום הטיבוח הוא בחג עצמו. \u0003ו\u0004אולם \u0003מודים\u0004 הם \u0003שאם חלה\u0004 עצרת \u0003להיות בשבת, שיום טבוח\u0004 הוא \u0003אחר השבת.\u0004","ומוסיפים: כאשר חל יום טיבוח ביום ראשון \u0003אין כהן גדול מתלבש בכליו\u0004 (בבגדי חג), אלא לובש בגדים רגילים, \u0003ומותרין\u0004 ביום זה \u0003בהספד ובתענית,\u0004 וכל זה עושים כדי \u0003שלא לקיים\u0004 ולחזק \u0003דברי\u0004 הצדוקים, \u0003האומרין: עצרת\u0004 חייבת להיות תמיד \u0003אחר השבת,\u0004 וכיון שיום הטיבוח הוא ביום ראשון, צריך להראות לכול שאין מודים להם ושאין זה יום טוב.","\u0003אמר ר' אלעזר אמר ר' אושעיא: מניין לעצרת שיש לה תשלומין,\u0004 שאת הקרבנות שהם חובת החג אפשר להשלים ולהקריב \u0003כל שבעה\u0004 ימים אחר החג — \u0003שנאמר \"\u0004שלוש פעמים בשנה יראה כל זכורך... \u0003בחג המצות ובחג השבעות ובחג הסכות\"\u0004 (דברים טז, טז) \u0003מקיש\u0004 הכתוב את \u0003חג השבועות לחג המצות,\u0004 לומר: \u0003מה חג המצות יש לה תשלומין כל שבעה,\u0004 שהרי יכול להביא את קרבנות החג לא רק ביום הראשון שאחר החג הראשון אלא בכל שבעת ימי החג, כפי ששנינו — \u0003אף חג השבועות יש לה תשלומין כל שבעה\u0004 ימים שאחריו.","ומקשים: \u0003ואימא\u0004 \u0005[ו\u0006שמא \u0005אמור]\u0006 באופן אחר: \u0003מקיש\u0004 (משווה) הכתוב את חג השבועות \u0003לחג הסוכות, מה חג הסוכות יש לה תשלומין כל שמונה\u0004 (ששמיני עצרת בכלל ימי החג), \u0003אף חג השבועות יש לה תשלומין כל שמונה!\u0004 ומשיבים: \u0003שמיני\u0004 עצרת \u0003רגל בפני עצמו הוא,\u0004 ואיננו נחשב כחלק מחג הסוכות.","ומקשים שוב: \u0003אימור דאמרי\u0004 \u0005[אמור\u0006 שזה \u0005שאמרו]\u0006 כי \u0003שמיני רגל בפני עצמו הוא — הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003לענין פז\"ר קש\"ב,\u0004 שהוא סימן לשישה דברים שבהם נבדל יום זה מחג הסוכות. שיש בו \u0003פ\u0004 ייס בפני עצמו, ואין ממשיכים לחלק את הקרבנות בין משמרות הכהנים לפי הפייס שבחג הסוכות; אומרים בו \u0003ז\u0004 מן (\"שהחיינו\") בפני עצמו, הוא נחשב ל\u0003ר\u0004 גל בפני עצמו לענין דחיית ימי אבילות; מביאים בו \u0003ק\u0004 רבנות שלא לפי סדר קרבנות חג הסוכות; יש בו \u0003ש\u0004יר ששרים על קרבן שאיננו כסדר חג הסוכות; ויש בו \u0003ב\u0004רכה מיוחדת בתפילה בפני עצמו, \u0003אבל לענין תשלומין\u0004 של קרבנות החג הלא \u0003תשלומין\u0004 של החג ה\u0003ראשון הוא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה קודמת\u0005]:\u0006 \u0003מי שלא חג\u0004 (הקריב קרבנות החג) \u0003ביום טוב הראשון של חג — חוגג\u0004 ומקריב \u0003את\u0004 הקרבנות \u0003כל הרגל, ויום טוב האחרון.\u0004 ואם כן חוזרת השאלה: מפני מה אין משווים את חג השבועות לחג הסוכות לשמונה ימים?","ומסבירים שעושים זאת לפי הכלל: \u0003תפשת מרובה — לא תפשת, תפשת מועט — תפשת,\u0004 שהמועט בכלל המרובה הוא, ולכן הוא ודאי. וכיון ששבעה בכלל שמונה, מוטב להשוות לפסח שיש בו שבעה ימים, שהיא השוואה ודאית, ולא להשוות לסוכות שיש ספק אם לכך הכוונה.","ושואלים: \u0003אלא,\u0004 אם כן, שאין משווים את חג השבועות לסוכות, \u0003למאי הלכתא כתביה רחמנא\u0004 \u0005[ל\u0006שם \u0005מה,\u0006 לצורך איזו \u0005הלכה כתבה אותו התורה]\u0006 בכלל את \u0003חג הסוכות\u0004 כאן? שהרי כבר נתפרשו דיני כל החגים קודם לכן, בפרק זה, ואם חזר הכתוב והזכירם במפורט ודאי לצורך השוואתם הוזכרו! ומשיבים: \"חג הסוכות\" \u0003לאקושי\u0004 \u0005[להקיש\u0006 להשוות\u0005]\u0006 את חג הסוכות עצמו \u0003לחג המצות,\u0004 ולומר: \u0003מה חג המצות טעון לינה,\u0004 שצריך ללון בירושלים במוצאי החג, ואין יוצאים משם בלילה עצמו, \u0003אף חג הסוכות טעון לינה\u0004 בירושלים במוצאי החג.","ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם\u0006 בחג המצות עצמו, \u0005מניין לנו]\u0006 שטעון לינה?"],["ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לאחר דיני הקרבת קרבן פסח: \u0003\"ופנית בבקר והלכת לאהליך\"\u0004 (דברים טז, ז), משמע: שמותר לצאת מירושלים רק בבוקר, לאחר שלנו בירושלים במוצאי החג.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003עצרת שחל להיות ערב שבת, בית שמאי אומרים: יום טבוח אחר השבת, ובית הלל אומרים: אין לה יום טבוח. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\u0003אין לה יום טבוח כלל,\u0004 כלומר, שאין תשלומים לחג השבועות, ואם לא הקריב בו ביום עבר זמן קרבנו. ודוחים: \u0003לא,\u0004 אין לה יום טיבוח כוונתו \u0003שאינה צריכה יום טבוח.\u0004","ושואלים: \u0003ומאי קא משמע לן\u0004 \u0005[ומה השמיע לנו\u0006 בזה\u0005] —\u0006 \u0003דמקרבינן ביומיה\u0004 \u0005[שמקריבים\u0006 את כל הקרבנות \u0005ביומם],\u0006 \u0003הא אפליגו בה חדא זימנא\u0004 \u0005[הרי\u0006 כבר \u0005נחלקו בכך פעם אחת]!\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005],\u0006 \u0003בית שמאי אומרים: מביאין שלמים\u0004 ביום טוב \u0003ואין סומכין עליהם, אבל לא\u0004 מביאים \u0003עולות\u0004 כלל, \u0003ובית הלל אומרים: מביאין שלמים ועולות וסומכין עליהם.\u0004 ומה צורך לחזור על דבר זה בצורה אחרת?","ומשיבים: \u0003צריכא\u0004 \u0005[נצרך\u0006 הדבר\u0005],\u0006 \u0003דאי אשמעינן בהא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק \u0005בזה]\u0006 שבית שמאי אוסרים להביא עולות בחג, הייתי אומר: \u0003בהא\u0004 \u0005[בזו]\u0006 ביום טוב רגיל שלמחרתו יום חול \u0003קא אמרי\u0004 \u0005[אומרים]\u0006 \u0003בית שמאי, משום\u0004 ש\u0003אפשר\u0004 להקריב עולות אלה \u0003למחר,\u0004 ביום טיבוח שלאחר החג. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בעצרת שחלה בערב שבת, שאי אפשר להקריב בשבת, \u0003אימא מודו להו\u0004 \u0005[אמור,\u0006 שמא \u0005מודים הם]\u0006 \u0003לבית הלל\u0004 שיקריבו ביום טוב, ולכן הוצרך הדבר להיאמר לבית שמאי.","ולהיפך: \u0003ואי אשמעינן בהא\u0004 \u0005[ואילו היה משמיע לנו\u0006 רק \u0005בזו]\u0006 שאין יום טיבוח אחר השבת, הייתי אומר: \u0003בהא קאמרי\u0004 \u0005[בזו אומרים]\u0006 \u0003בית הלל\u0004 שיקריבו ביום טוב עצמו, \u0003משום\u0004 ש\u0003לא אפשר\u0004 להקריבם \u0003למחר\u0004 שהרי שבת הוא, \u0003אבל בהא\u0004 \u0005[בזו]\u0006 ביום טוב רגיל שלמחרתו יום חול — \u0003אימא מודו\u0004 \u0005[אמור\u0006 שמא \u0005מודים\u0006 הם\u0005]\u0006 \u0003לבית שמאי,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרך\u0006 הדבר\u0005]\u0006 להיאמר. והשאלה אם יש תשלומים לעצרת לדעת בית הלל לא נפתרה איפוא.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר, ששנינו: \u0003מי שלא חג,\u0004 כלומר, לא הקריב את שלמי חגיגת החג \u0003שבעת ימי הפסח, ושמונת ימי החג, ויום טוב הראשון של עצרת, שוב אינו חוגג.\u0004 ונדייק \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003יום טוב של עצרת,\u0004 שאם לא הביא קרבנותיו ביום טוב עצמו שוב אין לו תקנה, ואם כן לדעתם אין תשלומים לעצרת! ודוחים: \u0003לא,\u0004 \"יום טוב\" זה שהזכרנו, כוונתו \u0003יום טבוח,\u0004 ולא יום החג עצמו. וממשיכים מיד לשאול: \u0003אי הכי, ניפשוט מינה דחד יום טבוח\u0004 \u0005[אם כן, נפתור מכאן\u0006 לפחות \u0005ש\u0006יש רק \u0005יום טיבוח אחד]\u0006 ולא שבעה ימים לתשלומים! ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 תקן בלשון: לא יום טיבוח, אלא \u0003ימי טבוח.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במקום אחר, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רבה בר שמואל\u0004 ברייתא זו: \u0003אמרה תורה מנה\u0004 שלושים \u0003ימים וקדש\u0004 בסופם את ראש \u0003חדש,\u0004 כפי שנלמד מן הביטוי \"חודש ימים\", וכן אמרה תורה \u0003מנה ימים וקדש עצרת,\u0004 שהרי סופרים חמישים יום מאחרי יום טוב ראשון של פסח וחוגגים את העצרת. ומהשוואה זו נלמד הלכה: \u0003מה חדש\u0004 — \u0003למנוייו,\u0004 שיום ראש חודש הוא יום אחד מימי החודש, \u0003אף עצרת\u0004 — \u0003למנוייה.\u0004 ונדייק מכאן: \u0003מאי לאו גמר\u0004 \u0005[האם לא\u0006 נפרש ש\u0005למד]\u0006 \u0003מחדש,\u0004 אם כן נלמד גם \u0003מה חדש,\u0004 חגו, ראש חודש, הוא \u0003יום אחד — אף עצרת\u0004 הוא \u0003יום אחד\u0004 בלבד ואין לו תשלומים!","\u0003אמר רבא: ותסברא\u0004 \u0005[וכי יכול אתה לסבור\u0006 כן\u0005]?!\u0006 \u0003אטו\u0004 \u0005[האם]\u0006 ב\u0003עצרת, יומי מנינן שבועי לא מנינן\u0004 \u0005[ימים אנו מונים\u0006 ו\u0005שבועות אין אנו מונים]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי: מצוה למימני יומי\u0004 \u0005[למנות ימים\u0006 בספירת העומר\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004עד ממחרת השבת השביעית \u0003תספרו חמשים יום\"\u0004 (ויקרא כג, טז), \u0003ומצוה\u0004 גם \u0003למימני שבועי\u0004 \u0005[למנות שבועות],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שבעה שבעת תספר לך\u0004 מהחל חרמש בקמה\u0003\"\u0004 (דברים טז, ט). \u0003ועוד:\u0004 הלוא \u0003\"חג שבעות\"\u0004 (דברים טז, י) \u0003כתיב\u0004 \u0005[נאמר],\u0006 משמע שהחג נקבע על פי השבועות, וכיון שכך, יש לעשות שבוע שלם לתשלומי עצרת, לפי שמנויה לשבועות.","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אליעזר בן יעקב תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 כך, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בשבועות: \u0003\"וקראתם\u0004 בעצם היום הזה מקרא קודש יהיה לכם כל מלאכת עבודה לא תעשו\u0003\"\u0004 (ויקרא כג, כא), ונאמר שם: \u0003\"ובקצרכם\u0004 את קציר ארצכם...\u0003\"\u0004 (ויקרא כג, כב), \u0003איזהו חג שאתה קורא\u0004 בו מקרא קודש \u0003וקוצר בו,\u0004 כלומר, שהוא בעונת הקציר — \u0003הוי אומר זה חג עצרת.\u0004","ומעתה נבדוק: \u0003אימת\u0004 \u0005[אימתי]\u0006 בדיוק מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ביום טוב\u0004 עצמו — וכי \u0003קצירה ביום טוב מי שרי\u0004 \u0005[האם\u0006 היא \u0005מותרת]?\u0006 והרי אסורה מלאכת עבודה ביום טוב! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003ל\u0004ענין \u0003תשלומין,\u0004 כלומר, בימים שהם תשלומים לחג, ימי הטיבוח, שאפשר גם לקצור בהם, מפני שהימים הללו הם ימי חול גמורים, ובכל זאת הם השלמה לחג.","ומעירים: \u0003ואף על גב דאיתמר\u0004 \u0005[שנאמר]\u0006 דבר זה של \u0003ר' אלעזר אמר ר' אושעיא,\u0004 ללמוד דין תשלומי עצרת מהשוואת חג השבועות לחג המצות, מכל מקום \u0003אצטריך\u0004 \u0005[צריך]\u0006 גם מה שאמר \u0003ר' אליעזר בן יעקב. דאי\u0004 \u0005[שאם\u0006 היינו לומדים\u0005]\u0006 רק \u0003מ\u0004הראיה שהביא \u0003ר' אלעזר אמר ר' אושעיא הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כך: \u0003מה תשלומין של חג המצות אסור\u0004 \u0005[אסורים]\u0006 \u0003בעשיית מלאכה\u0004 שאינה בכלל דבר האבד, שהרי הם בתוך הרגל, \u0003אף תשלומי עצרת נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור\u0004 אדם \u0003בעשיית מלאכה,\u0004 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 גם את הלימוד של \u0003ר' אליעזר בן יעקב\u0004 שבימים אלה קוראים וקוצרים, כי הם ימי חול, להיפך — \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004דברי \u0003ר' אליעזר בן יעקב\u0004 בלבד,"],["\u0003לא ידענא\u0004 \u0005[אין אני יודע]\u0006 \u0003כמה\u0004 ימים לתשלומים, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 מדברי \u0003ר' אלעזר אמר ר' אושעיא\u0004 שהם שבעה ימים.","\u0003וריש לקיש אמר\u0004 ראיה אחרת: מעצם שמו של היום \u0003\"וחג הקציר\"\u0004 (שמות כג, טז). וכך נלמד: \u0003איזהו חג שאתה חוגג\u0004 בו \u0003וקוצר בו — הוי אומר זה עצרת.\u0004 ונברר: \u0003אימת\u0004 \u0005[מתי]\u0006 עושים כן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ביום טוב\u0004 עצמו — \u0003קצירה ביום טוב מי שרי\u0004 \u0005[האם מותרת]?\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה ביום שהוא \u0003לתשלומין.\u0004","\u0003אמר ר' יוחנן\u0004 לריש לקיש: \u0003אלא מעתה\u0004 לפי אותה דרך־פירוש, \u0003\"חג האסיף\"\u0004 (שמות כג, טז) תאמר גם כן: \u0003אי זהו חג שיש בו אסיפה — הוי אומר זה חג הסוכות, אימת\u0004 \u0005[אימתי]\u0006 נעשה הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ביום טוב\u0004 עצמו — \u0003מלאכה ביום טוב מי שרי\u0004 \u0005[האם מותרת]?\u0006 \u0003אלא בחולו של מועד.\u0004 אולם אף \u0003חולו של מועד מי שרי\u0004 \u0005[האם מותר]?\u0006 שהרי אין עושים בו רק מלאכה של דבר שיאבד אם לא תיעשה בו ביום. \u0003אלא\u0004 על כרחך אתה מפרש ש\"חג האסיף\" תפקידו לציין את העונה בשנה — \u0003חג הבא בזמן אסיפה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לפרש \"חג הקציר\" — \u0003חג הבא בזמן קצירה.\u0004","ומעירים: \u0003מכלל\u0004 דברי ריש לקיש ור' יוחנן למדים אנו \u0003דתרוייהו סבירא להו\u0004 \u0005[ששניהם סבורים]\u0006 ש\u0003חולו של מועד אסור בעשיית מלאכה\u0004 מן התורה, שהרי אין ריש לקיש חולק על הערתו של ר' יוחנן.","ויש לשאול: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו],\u0006 מה המקור בתורה לאיסור זה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003\"את חג המצות תשמר שבעת ימים\"\u0004 (שמות כג, טו) — \u0003לימד על חולו של מועד שאסור בעשיית מלאכה\u0004 (\"תשמור\" — לשון איסור \"לא תעשה\" הוא), אלו \u0003דברי ר' יאשיה. ר' יונתן אומר: אינו צריך\u0004 לראיה זו, שאינה כפשוטו של מקרא, אלא זה נלמד מ\u0003קל וחומר,\u0004 ובאופן זה: \u0003ומה ראשון ושביעי\u0004 של פסח \u0003שאין קדושה לפניהן ולאחריהן\u0004 (לפני הראשון ואחרי השביעי) אלא ימי חול — \u0003אסור בעשיית מלאכה,\u0004 ימי \u0003חולו של מועד שיש קדושה לפניהן ולאחריהן\u0004 (של יום טוב ראשון ואחרון) — \u0003אינו דין שיהא אסור בעשיית מלאכה.\u0004","ומקשים: \u0003ששת ימי בראשית,\u0004 כלומר: ימות השבוע, \u0003יוכיחו, ש\u0004הרי \u0003יש קדושה לפניהן ולאחריהן\u0004 ביום שבת, \u0003ומותרין בעשיית מלאכה!\u0004 את הקושיה הזאת דוחים: \u0003מה לששת ימי בראשית\u0004 שהם ימי חול גמורים \u0003שאין בהן קרבן מוסף, תאמר בחולו של מועד שיש בו קרבן מוסף\u0004 ויש בו קדושה מסויימת. על דחייה זו מקשים: \u0003ראש חדש יוכיח, שיש בו קרבן מוסף, ומותר בעשיית מלאכה!\u0004 את הקושיה הזו דוחים: \u0003מה לראש חדש שאין קרוי \"מקרא קדש\" תאמר בחולו של מועד שקרוי \"מקרא קדש\",\u0004 ו\u0003הואיל וקרוי מקרא קדש — דין הוא שאסור בעשיית מלאכה.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 באותו נושא: ביום ראשון של חג הפסח (וסוכות) נאמר: \u0003\"כל מלאכת עבדה לא תעשו\"\u0004 (ויקרא כג, לה), וסמוך לו: \"והקרבתם אשה לה' שבעת ימים\" — \u0003לימד על חולו של מועד\u0004 שהוא בתוך שבעה ימים \u0003שאסור בעשיית מלאכה,\u0004 אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר: אינו צריך, הרי הוא אומר\u0004 בתחילת פרשת המועדות \u0003\"אלה מועדי ה'\u0004 מקראי קודש אשר תקראו אותם במועדם\u0003\"\u0004 (ויקרא כג, ב), \u0003במה הכתוב מדבר? אם ב\u0004יום ה\u0003ראשון\u0004 של חג — \u0003הרי כבר נאמר\u0004 בו לעצמו במפורש \u0003\"שבתון\", אם בשביעי — הרי כבר נאמר\u0004 בו \u0003\"שבתון\", הא\u0004 \u0005[הרי]\u0006 \u0003אין הכתוב מדבר אלא בחולו של מועד, ללמדך שאסור בעשיית מלאכה.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 נאמר: \u0003\"ששת ימים תאכל מצות וביום השביעי עצרת לה'\u0004 אלהיך לא תעשה מלאכה\u0003\"\u0004 (דברים טז, ח) \u0003מה שביעי עצור\u0004 בעשיית מלאכה — \u0003אף ששת ימים\u0004 של חול המועד \u0003עצורין,\u0004 שהרי נאמר \"וביום השביעי\" ב־ו' החיבור, לחבר יום זה לימים שלפניו. \u0003אי\u0004 \u0005[אם]\u0006 כך, נאמר: \u0003מה שביעי עצור בכל מלאכה אף ששת ימים\u0004 של חול המועד יהיו \u0003עצורין בכל מלאכה\u0004 (אפילו שאיננה מלאכת דבר האבד) —","\u0003תלמוד לומר: \"וביום השביעי\u0004 (בלבד) \u0003עצרת\"\u0004 ללמד: \u0003השביעי עצור בכל מלאכה, ואין ששה ימים עצורין בכל מלאכה\u0004 אלא במלאכות מסויימות. ומאחר שלא מפורש בכתוב אילו מלאכות אסורות צריך לומר \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא מסרן הכתוב אלא לחכמים, לומר לך איזה יום אסור\u0004 במלאכה \u0003ואיזה יום מותר, איזו מלאכה אסורה ואיזו מלאכה מותרת.\u0004","שנינו במשנה: \u0003ומותרין\u0004 ימי הטיבוח \u0003בהספד ותענית שלא לקיים את דברי\u0004 הצדוקים \u0003האומרין עצרת לאחר השבת.\u0004 ומקשים, \u0003והאיתמר\u0004 \u0005[והרי נאמר]:\u0006 \u0003מעשה ומת אלכסא בלוד ונכנסו כל ישראל לסופדו ולא הניחם ר' טרפון\u0004 לעשות כן, \u0003מפני שיום טוב של עצרת היה.\u0004","ומבררים: \u0003יום טוב סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ביום טוב מי קאתו\u0004 \u0005[האם הם באים]?\u0006 הרי ודאי שאין העם בא להספד ביום טוב עצמו, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 \u0003מפני שיום טבוח היה,\u0004 משמע שביום טיבוח אין מספידים! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן ביום טוב שחל להיות אחר השבת\u0004 ויום טיבוח שלו הוא לא ביום ראשון, שכיון שמקריבים בו קרבנות יש בו משום קדושת עצרת וראוי לנהוג בו מנהג חג. \u0003כאן ביום טוב שחל להיות בשבת,\u0004 כיון שיום טיבוח שלו חל ביום ראשון, אין נוהגים בו מנהג חג גמור, כדי להוציא מדעת הצדוקים."],["\u0003נוטלין לידים\u0004 (ששופכים שיעור רביעית מים על הידים) \u0003ל\u0004פני אכילת \u0003חולין, ולמעשר ולתרומה.\u0004 אבל \u0003ו\u0004אולם \u0003לקודש,\u0004 אם בא לאכול קדשים — \u0003מטבילין\u0004 את הידים במים מטהרים, כמי מקווה. \u0003ולחטאת,\u0004 אם בא לנגוע במי חטאת (מי אפר פרה אדומה) שגזרו בהם חכמים כמה גדרי קדושה נוספים, \u0003אם נטמאו ידיו\u0004 אף בטומאה שאינה אלא מדברי סופרים, ומטמאת בדרך כלל רק ידים, אבל לגבי חטאת אם נטמאו ידיו \u0003נטמא גופו\u0004 וצריך לטבול כל גופו במקוה.","ועוד הבדל בין הדרגות השונות בטהרה: אם \u0003טבל\u0004 אדם \u0003ל\u0004צורך אכילת \u0003חולין,\u0004 ו\u0003הוחזק,\u0004 כלומר, כיוון בטבילתו \u0003ל\u0004שם טהרת \u0003חולין —\u0004 עדיין \u0003אסור\u0004 הוא \u0003למעשר,\u0004 שכן לא נתכוון לטהרתו כדי לאכול מעשר. \u0003טבל למעשר\u0004 ו\u0003הוחזק למעשר — אסור לתרומה. טבל לתרומה\u0004 ו\u0003הוחזק לתרומה — אסור לקודש. טבל לקודש\u0004 ו\u0003הוחזק לקודש — אסור לחטאת.\u0004 והכלל הוא: \u0003טבל לחמור — מותר לקל.\u0004 ועוד כלל: \u0003טבל ולא הוחזק,\u0004 כלומר, ולא נתכוון להיטהר — הרי זה \u0003כאילו לא טבל\u0004 כלל.","ועוד אמרו: \u0003בגדי עם הארץ\u0004 שאינו מקפיד על טומאה וטהרה, נחשבים כאילו היו טמאים בטומאת \u0003מדרס\u0004 הזב, שהיא אב הטומאה \u0003לפרושין,\u0004 לאלה שאוכלים חולין בטהרה. ואילו \u0003בגדי פרושין,\u0004 למרות שהם נזהרים בטהרה, נחשבים כ\u0003מדרס ל\u0004כהנים \u0003אוכלי תרומה. בגדי אוכלי תרומה\u0004 נחשבים \u0003מדרס ל\u0004אוכלי \u0003קודש\u0004 (קרבנות), \u0003בגדי קודש — מדרס ל\u0004עוסקים במלאכת מי \u0003חטאת.\u0004","מספרים: \u0003יוסף בן יועזר היה חסיד שבכהונה\u0004 ונזהר הרבה מאוד בטהרה לאכילת תרומה \u0003ו\u0004בכל זאת \u0003היתה מטפחתו\u0004 נחשבת \u0003מדרס ל\u0004אוכלי \u0003קודש. יוחנן בן גודגדא היה אוכל\u0004 חולין \u0003על טהרת הקודש כל ימיו\u0004 שגם באכילת חולין היה נזהר בטהרה כאילו הוא קודש, \u0003ו\u0004בכל זאת \u0003היתה מטפחתו מדרס לחטאת.\u0004","טרם בירור פרטי הלכה, שואלים ליסודות הדברים: \u0003חולין ומעשר מי בעו\u0004 \u0005[האם צריכים]\u0006 \u0003נטילת ידים\u0004 כלל?","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ששנינו: \u0003התרומה והביכורים חייבין עליהן מיתה\u0004 אם אכל אותם זר במזיד, והזר שאכלם בשוגג חייב להחזיר מה שאכל ולהוסיף \u0003חומש, ואסור לזרים, והן נכסי כהן\u0004 שיכול לרכוש בהם מה שירצה ויכול לקדש בהם את האשה. \u0003ו\u0004אם נפלו לתוך תערובת חולין ונתערבו \u0003עולין\u0004 (מתבטלים) רק אם יש \u0003ב\u0004תערובת זו \u0003אחד ומאה\u0004 כנגדם, \u0003וטעונין נטילת ידים\u0004 לפני אכילתם, \u0003והערב שמש\u0004 שאם נטמא הכהן לא די לו שטבל בזמן הראוי לטהרתו, אלא צריך להמתין עד שתעריב השמש כדי שיהיה ראוי לאכילתם, ו\u0003הרי\u0004 דינים \u0003אלו בתרומה וביכורים, מה שאין כן במעשר.\u0004 ומוסיפים: \u0003וכל שכן\u0004 שאינם \u0003בחולין.\u0004","ואם כן, \u0003קשיא\u0004 \u0005[וקשה]\u0006 מדין \u0003מעשר\u0004 האמור כאן על דין \u0003מעשר\u0004 האמור במשנתנו, שצריך ליטול ידים לפני אכילתו, וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003חולין\u0004 על דין \u0003חולין!\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 כי מ\u0003מעשר\u0004 על \u0003מעשר — לא קשיא\u0004 \u0005[אינו קשה],\u0006 שאפשר לתרץ: \u0003הא\u0004 \u0005[זו]\u0006 המשנה בביכורים הריהי כדעת \u0003ר' מאיר, והא\u0004 \u0005[וזו]\u0006 משנתנו כדעת \u0003רבנן\u0004 \u0005[החכמים].\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הטעון ביאת מים מדברי סופרים,\u0004 כלומר, כל טומאה מדברי סופרים שצריך לטבול כדי להיטהר ממנה, הרי טומאה זו \u0003מטמא את הקודש,\u0004 שאם נגעה בדבר של קודש נטמא הוא עצמו (שני לטומאה), ומטמא קודש הנוגע בו (שלישי לטומאה), \u0003ופוסל את התרומה\u0004 שנטמאה בעצמה אף כי אינה מטמאה תרומה אחרת, \u0003ומותר לחולין ולמעשר\u0004 שהטמא בדרגה זו אף אינו פוסל את החולין, אלו \u0003דברי ר' מאיר. וחכמים אוסרים במעשר.\u0004 ואם כן הרי שלדעת חכמים מעשר שונה בדינו מן החולין, ולכן צריך נטילת ידים למעשר. \u0003אלא\u0004 מ\u0003חולין\u0004 על \u0003חולין קשיא\u0004 \u0005[קשה]!\u0006","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 במשנתנו מדובר \u0003באכילה\u0004 שצריך נטילת ידים לפניה, ו\u0003כאן\u0004 במסכת ביכורים מדובר \u0003בנגיעה\u0004 בלבד, שאין צריך לשם כך נטילת ידים קודם לכן.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שימי בר אשי: עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חולקים חכמים עליו],\u0006 על \u0003ר' מאיר אלא באכילה\u0004 של \u0003מעשר\u0004 (ולכן אמרו לשון \"אסור במעשר\"), \u0003אבל בנגיעה\u0004 ב\u0003מעשר ובאכילה\u0004 של \u0003חולין לא פליגי\u0004 \u0005[נחלקו]\u0006 עליו, וכיצד אפשר להמציא שיטה חדשה? \u0003אלא\u0004 יש לדחות הסבר זה ולומר: \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 מדובר \u0003באכילה, ולא קשיא\u0004 \u0005[ואינו קשה]\u0006 \u0003כאן — באכילה דנהמא\u0004 \u0005[של לחם]\u0006 צריך נטילת ידים לפניה, \u0003כאן באכילה דפירי\u0004 \u0005[של פירות]\u0006 של חולין — אין צריך נטילת ידים. ש\u0003אמר רב נחמן: כל הנוטל ידיו לפירות — הרי זה מגסי הרוח\u0004 מפני שהוא מראה בזה שהוא מדקדק בעצמו יותר ממה שהורו לו חכמים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנוטל ידיו,\u0004 אם \u0003נתכוון\u0004 לטהרה — \u0003ידיו טהורות, לא נתכוון\u0004 לכך — \u0003ידיו טמאות. וכן המטביל ידיו\u0004 בארבעים סאה, \u0003נתכוון\u0004 לטהרה — \u0003ידיו טהורות, לא נתכוון — ידיו טמאות.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בין נתכוון בין לא נתכוון — ידיו טהורות! אמר רב נחמן: לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן לחולין —\u0004 אין צורך בכוונה לטהרה,"],["\u0003כאן למעשר —\u0004 צריך כוונה להיטהר. \u0003ומנא תימרא\u0004 \u0005[ומניין אתה אומר],\u0006 מנין יודעים כי \u0003חולין לא בעו\u0004 \u0005[אינם צריכים]\u0006 \u0003כוונה\u0004 לטהרתם — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003גל שנתלש\u0004 מן הים ליבשה \u0003ובו ארבעים סאה, ונפל על האדם ועל הכלים — טהורין. קתני\u0004 \u0005[שנה]\u0006 \u0003אדם דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003כלים, מה כלים דלא מכווני\u0004 \u0005[שאינם מכוונים]\u0006 להיטהר, שהרי בוודאי שהכלים עצמם אינם מתכוונים להיטהר — \u0003אף אדם\u0004 מדובר אף באופן \u0003דלא מכוין\u0004 \u0005[שאיננו מכוון]\u0006 לטהרה, משמע שגם בלא כוונה נטהרים.","ודוחים: \u0003וממאי\u0004 \u0005[וממה],\u0006 מניין יודע אתה שכך פירושו? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ביושב ומצפה אימתי יתלש הגל\u0004 ויעבור על הכלים \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ונאמר להיפך: \u0003וכלים דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003אדם, מה אדם דבר\u0004 \u0005[שבן]\u0006 \u0003כוונה\u0004 הוא, כלומר, מסוגל לכוון לטהרה — \u0003אף כלים\u0004 שנזכרו שם, מדובר \u0003דמכוין להו\u0004 \u0005[שהוא מכוון להם,\u0006 עבורם\u0005]\u0006 שיטהרו.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי מדובר \u0003ביושב ומצפה,\u0004 אם כן \u0003מאי למימרא\u0004 \u0005[מה\u0006 יש \u0005לומר\u0006 בזה\u0005],\u0006 שאם כך הוא הרי אין בכך כל חידוש, ולשם מה אמרו הלכה זו?","ועונים: מכל מקום יש חידוש בדבר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[\u0006שמא \u0005יעלה על דעתך לומר]\u0006 \u0003ליגזור דלמא אתי למיטבל\u0004 \u0005[נגזור שמא יבא לטבול]\u0006 \u0003בחרדלית\u0004 (זרם מים) בן ארבעים סאה \u0003של\u0004 מי \u0003גשמים,\u0004 כלומר בשטף שיצא מן הגשם השוטף ועובר, ואנו יודעים כי מי גשמים אינם מטהרים אלא בהיותם נקווים ועומדים במקום אחד, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003נגזור\u0004 שלא תועיל הטהרה ב\u0003ראשין אטו כיפין\u0004 \u0005[\u0006ב\u0005ראשי,\u0006 קצות הגלים הנוגעים בקרקע, \u0005משום כפות,\u0006 עיגול הגלים העליונים\u0005],\u0006 ולכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דלא גזרינן\u0004 \u0005[שאין אנחנו גוזרים].\u0006","\u0003ומנא תימרא\u0004 \u0005[ומניין אתה אומר]\u0006 ש\u0003לא מטבילין בכיפין — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מטבילין בראשין\u0004 (קצות הגל), \u0003ואין מטבילין בכיפין\u0004 בעיגול הגל, \u0003לפי שאין מטבילין באויר,\u0004 והרי מקום עיגולו של הגל אויר הוא, אף שהוא מכוסה מים מכל צדדיו.","\u0003אלא\u0004 ההוכחה שלטהרת חולין אין צורך בכוונה \u0003מהא\u0004 \u0005[מזו]\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003פירות שנפלו לתוך אמת\u0004 (תעלת) \u0003המים, ופשט מי שידיו טמאות ונטלן\u0004 להוציאם משם — \u0003ידיו טהורות,\u0004 שכאשר הכניסן לאמת המים טהרו שם, \u0003ופירות\u0004 הללו \u0003אינן ב\"כי יותן\",\u0004 כי הכתוב המדבר בהכשרת פירות וזרעים לקבל טומאה (\"כי יותן מים על זרע ונפל מנבלתם עליו טמא הוא לכם\". ויקרא יא, לא) נתפרש שמדובר רק בפירות שנתנו עליהם מים בכוונה תחילה, ופירות אלה שלא נרטבו בכוונה אינם מוכשרים לקבל טומאה.","\u0003ואם\u0004 הכניס ידיו \u0003בשביל שיודחו\u0004 (יירחצו) \u0003ידיו — ידיו טהורות, והפירות הרי הן ב\"כי יותן\",\u0004 שכיון שהיתה לו כוונה להרטיב את ידיו במים, הרי מגע מים אלה מכשיר את הפירות הללו לטומאה. וכיון שנאמר במשנה שידיו טהורות בכל מקרה, משמע שאין צורך בכוונה מיוחדת לטהרה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבה לרב נחמן\u0004 ממשנתנו: \u0003הטובל לחולין והוחזק לחולין — אסור למעשר.\u0004 ונדקדק: \u0003הוחזק — אין\u0004 \u0005[כן]\u0006 \u0003לא הוחזק — לא,\u0004 משמע שאף לחולין יש צורך בחזקה — בכוונה!","ודחה רב נחמן: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 התנא במשנה, כך יש להבין: \u0003אף על פי שהוחזק לחולין — אסור למעשר.\u0004 כלומר, לא באה המשנה ללמדנו שצריך כוונה לטהרת חולין, אלא לומר שאפילו התכוון לטהרה, אין זה מועיל למעשר.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו במשנה: \u0003טבל ולא הוחזק — כאילו לא טבל. מאי לאו\u0004 \u0005[האם לא]\u0006 המובן — \u0003כאילו לא טבל כלל?\u0004","ודחה רב נחמן: \u0003לא,\u0004 המשמעות היא \u0003כאילו לא טבל למעשר, אבל טבל לחולין,\u0004 שבהם אין צורך בכוונה. ומעירים: \u0003הוא,\u0004 רבה, \u0003סבר\u0004 \u0005[חשב]\u0006 שרב נחמן \u0003דחי קא מדחי ליה\u0004 \u0005[דוחה אותו]\u0006 בלבד, שאין להוכיח הוכחה מכרעת נגדו מן הלשון, אבל כוונת הדברים אינה כן. \u0003נפק דק ואשכח\u0004 \u0005[יצא, דיקדק\u0006 ועיין במקורות \u0005ומצא]\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 מפורשת כרב נחמן: \u0003טבל ולא הוחזק — אסור למעשר ומותר לחולין.\u0004","ולענין החזקה לטהרה, \u0003אמר ר' אלעזר: טבל\u0004 סתם \u0003ועלה\u0004 מן הטבילה — \u0003מחזיק עצמו\u0004 אז \u0003לכל מה שירצה.\u0004 ואין צורך שיתכוון בשעת טבילה עצמה לצורך מסויים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך, ממה ששנינו: מי שטבל ועולה מן המים, \u0003עודהו רגלו אחת במים, הוחזק לדבר קל — מחזיק עצמו לדבר חמור,\u0004 ואם \u0003עלה לגמרי — שוב אינו מחזיק.\u0004","ונדייק: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שאם עלה — \u0003אינו מחזיק כלל,\u0004 משמע שיכול להחזיק רק אם עודנו (אף במקצתו) בתוך המים!","ודוחים: \u0003לא,\u0004 כך יש להבין: אם \u0003עודהו\u0004 במים, \u0003אף על פי שהוחזק\u0004 קודם לדבר קל — \u0003מחזיק\u0004 עצמו למה שירצה, שיכול לשנות את כוונתו בטבילה לצורך אחר, אבל אם \u0003עלה\u0004 כבר, \u0003אם לא הוחזק\u0004 כלל, שטבל סתם — \u0003מחזיק\u0004 לכל מה שירצה, \u0003ואם הוחזק\u0004 לדבר הקל — \u0003אינו מחזיק\u0004 לדבר חמור, שהרי בשעה שניתק מהמקווה הוחזק כבר לקל.","אגב כך מפרשים: \u0003מאן תנא\u0004 \u0005[מי\u0006 הוא \u0005התנא]\u0006 הסבור כי \u0003עודהו רגלו אחת במים\u0004 הריהו כטובל? \u0003אמר ר' פדת:\u0004 שיטת \u0003ר' יהודה היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקוה שנמדד ויש בו\u0004 מים בשיעור \u0003ארבעים סאה מכוונות\u0004 (בדיוק, ולא יותר) \u0003וירדו שנים וטבלו זה אחר זה, הראשון טהור\u0004 שטבל במקוה כדינו, \u0003והשני טמא,\u0004 שכיון שמעט מים דבקו בראשון, חסר כבר המקוה משיעורו, ואינו מטהר את השני. \u0003אמר ר' יהודה: אם היו רגליו של ראשון נוגעות במים,\u0004 שלא יצא מהמקוה לגמרי \u0003— אף השני טהור.\u0004 ומכאן רואים שהוא סבור שמי שרגלו אחת במים נחשב עדיין כמחובר אל המקוה.","\u0003אמר רב נחמן אמר רבה בר אבוה: מחלוקת\u0004 זו של חכמים ור' יהודה היא \u0003במעלות דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 כלומר, במקרים שחיוב הטבילה הוא רק משום תקנות חכמים, \u0003אבל\u0004 לצאת בכך \u0003מטומאה\u0004 ממש \u0003לטהרה — ל\u0004\u0003דברי הכל (אף) השני טמא. והיינו\u0004 \u0005[וזהו]\u0006 שאמר \u0003ר' פדת\u0004 ששיטה זו, שכל עוד רגלו אחת במקוה, עדיין הוא מחזיק עצמו לטהרה רק דעת ר' יהודה היא.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, \u0003אמר רב נחמן אמר רבה בר אבוה: מחלוקת\u0004 זו היא דווקא בעלייה \u0003מטומאה לטהרה, אבל במעלות דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 אם רגלי הראשון נוגעות עדיין במים — ל\u0003דברי הכל אף השני טהור. ו\u0004אם כן \u0003פליגא\u0004 \u0005[חלוקה]\u0006 שיטה זו על דברי \u0003ר' פדת,\u0004 שהרי לשיטה זו לענין החזקה הכל מודים שכשרגלו אחת במקוה הריהו כטובל.","ובהמשך לאותו ענין \u0003אמר עולא: בעי מיניה\u0004 \u0005[שאלתי אותו]\u0006 את \u0003ר' יוחנן: לר' יהודה, מהו להטביל מחטין וצינוריות\u0004 (מסרגות) שהם כלים קטנים \u0003בראשו של\u0004 הטובל \u0003ראשון?\u0004 שאם לדעת ר' יהודה מי שטבל ורגלו עדיין במים נחשב כולו כמחובר למקוה, אם כן, האם גופו ואף שערו הרטוב יכולים לשמש כמקוה טהרה, או לא?","וצדדי השאלה: האם רק ההנחה של \u0003גוד אחית\u0004 \u0005[משוך והורד]\u0006 \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003לר' יהודה\u0004 שדבר הנמצא למעלה נחשב כאילו נמשך ויורד למטה, ולכן הוא סבור שהמים שעל גופו של הטובל נחשבים כאילו נמשכים ויורדים אל תוך המקוה, ויש עדיין במקוה שיעור, אבל \u0003גוד אסיק לית ליה\u0004 \u0005[משוך והעלה אין לו],\u0006 שאינו סבור שהמים שבמקוה נחשבים כעולים עד ראשו של אותו אדם, וייחשב אף הוא כחלק מן המקוה, \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003גוד אסיק נמי אית ליה\u0004 \u0005[משוך והעלה גם כן יש לו],\u0006 שנחשב ממש כאילו עודנו במקוה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003תניתוה\u0004 \u0005[שניתם\u0006 כבר \u0005אותה],\u0006 שכך שנוי בתוספתא: היו \u0003שלש גממיות\u0004 (גומות, חורים שקעים) \u0003ב\u0004תוך אפיק \u0003נחל\u0004 שלא התייבש לגמרי, ונשארו בו עדיין מים, \u0003העליונה, התחתונה והאמצעית; העליונה והתחתונה\u0004 הם \u0003של עשרים עשרים סאה, והאמצעית של ארבעים סאה, וחרדלית\u0004 (זרימה) \u0003של גשמים עוברת ביניהן\u0004 בין הגומות הללו ומחברת אותם, \u0003ר' יהודה אומר: מאיר\u0004 (חבירו ר' מאיר) \u0003היה אומר: מטביל בעליונה.\u0004 ומכאן — שהוא סבור שמי הגומה האמצעית (שהוא מקוה גמור שיש בו שיעור) נחשבים על ידי חיבור המים כאילו היו נמשכים ועולים למעלה, גם לגומה העליונה. וכיון שהביא ר' יהודה את דברי חבירו, ולא חלק עליהם, משמע שגם הוא סבור כי יש לקבל את ההנחה של \"גוד אסיק\".","הקשה לו עולא: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004"],["\u0003מאיר היה אומר: מטביל בעליונה, ואני אומר: בתחתונה ולא בעליונה,\u0004 הרי שלדעת ר' יהודה אין אומרים \"גוד אסיק\"! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אי תניא\u0004 \u0005[אם שנויה\u0006 ברייתא\u0005] —\u0006 \u0003תניא\u0004 \u0005[שנויה],\u0006 הרי מפורש שיש מחלוקת תנאים בדבר, ור' יהודה באמת איננו מקבל את ההנחה של \"גוד אסיק\".","שנינו במשנה: \u0003הטובל לחולין והוחזק לחולין —\u0004 אסור במעשר. ומעירים: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי\u0006 היא \u0005משנתנו] —\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 שחלקו על ר' מאיר, \u0003דשני להו\u0004 \u0005[ששונה להם,\u0006 שיש הבדל אצלם\u0005]\u0006 \u0003בין חולין למעשר,\u0004 שלדעתם כל הטעון מים מדברי סופרים, אם נגע בחולין — החולין טהורים, ואם נגע במעשר — טימאהו,","\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של משנתנו, ושם נאמר כי \u0003בגדי עם הארץ\u0004 שאינו מקפיד על טומאה וטהרה, נחשבים כאילו היו טמאים בטומאת \u0003מדרס\u0004 הזב, שהיא אב הטומאה \u0003לפרושין,\u0004 לאלה שאוכלים חולין בטהרה. ואילו \u0003בגדי פרושין,\u0004 למרות שהם נזהרים בטהרה, נחשבים כ\u0003מדרס ל\u0004כהנים \u0003אוכלי תרומה.\u0004","\u0003אתאן\u0004 \u0005[באנו\u0006 הגענו\u0005]\u0006 איפוא \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר: חולין ומעשר כהדדי נינהו\u0004 \u0005[זה כמו זה הם]\u0006 שהרי איננו מחלק בין אוכלי חולין למעשר, ותמוה שבמשנה \u0003רישא רבנן\u0004 \u0005[תחילתה\u0006 כדעת \u0005חכמים]\u0006 \u0003וסיפא\u0004 \u0005[וסופה]\u0006 כדעת \u0003ר' מאיר?!\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 למרות שהדבר איננו רגיל, יש לפרש ש\u0003רישא רבנן\u0004 \u0005[תחילתה\u0006 כדעת \u0005חכמים]\u0006 \u0003וסיפא\u0004 \u0005[וסופה]\u0006 כדעת \u0003ר' מאיר.\u0004","אכן, \u0003רב אחא בר אדא מתני לה בסיפא\u0004 \u0005[היה שונה\u0006 גם \u0005בסופה]\u0006 של המשנה \u0003חמש מעלות,\u0004 שהיה מונה בה גם מעלה נוספת שבגדי אוכלי חולין בטהרה הם מדרס למעשר, \u0003ומוקי לה\u0004 \u0005[ומעמיד\u0006 איפוא \u0005אותה]\u0006 את המשנה \u0003כולה כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים].\u0006","\u0003אמר רב מרי: שמע מינה\u0004 \u0005[למד ממנה]\u0006 ממשנתנו כי \u0003חולין שנעשו על טהרת הקודש,\u0004 כלומר: באותם דקדוקים והקפדות שמקפידים בהם בטהרת קדשים — \u0003כקודש דמו\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006 ו\u0003ממאי\u0004 \u0005[וממה]\u0006 מסיקים אנו דבר זה —"],["\u0003מדלא קתני בהו\u0004 \u0005[מ\u0006פני \u0005שלא שנה בהם]\u0006 \u0003מעלה\u0004 להפריד בין אוכלי חולין על טהרת הקודש לאוכלי קודש ממש, לומר שאוכלי חולין בטהרת קודש, בגדיהם מדרס לאוכלי קודש.","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003האי\u0004 \u0005[זה]\u0006 ש\u0003לא קתני בהו\u0004 \u0005[שנה בהם]\u0006 \u0003מעלה\u0004 מיוחדת, הרי זה מפני שאין להם דרגה מיוחדת, \u0003דאי דמו\u0004 \u0005[שאם דומים\u0006 הם\u0005]\u0006 \u0003לתרומה\u0004 — \u0003הא תני\u0004 \u0005[הרי שנה]\u0006 כבר \u0003תרומה, ואי דמו\u0004 \u0005[ואם דומים\u0006 הם\u0005]\u0006 \u0003לחולין — הא תני\u0004 \u0005[הרי שנה]\u0006 \u0003לחולין.\u0004 וראיה לדבר שאין להם מעלה לעצמה — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חולין שנעשו על טהרת הקודש\u0004 — \u0003הרי הן כחולין, ר' אלעזר בר' צדוק אומר: הרי הן כתרומה\u0004 ולא כקודש. ואם כן ממה שלא נזכרה מעלה זו במפורש אין הוכחה.","\u0003אלא מסיפא\u0004 \u0005[מסופה]\u0006 של המשנה נוכיח. ששנינו: \u0003יוסי בן יועזר היה חסיד שבכהונה והיתה מטפחתו מדרס לקודש, יוחנן בן גודגדא היה אוכל על טהרת הקודש כל ימיו והיתה מטפחתו מדרס לחטאת,\u0004","ונדייק: \u0003לחטאת אין\u0004 \u0005[כן]\u0006 נחשבת היא כמדרס, אבל \u0003לקודש לא\u0004 תיחשב למדרס, וסומכים על טהרתו, \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור הוא]\u0006 כי \u0003חולין שנעשו על טהרת הקודש כקודש דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 ואין להבחין עוד ביניהם, שאם מקפיד על טהרת הקודש בחולין אפשר לסמוך על כך אף לקדשים.","ולענין ההקפדה היתירה בשמירת בגדים שלא יהא בהם חשש טומאה, \u0003אמר ר' יונתן בן אלעזר: נפלה מעפרתו\u0004 (עטיפתו, כעין סודר) של המקפיד ומחמיר בטהרה \u0003הימנו,\u0004 ו\u0003אמר לחבירו: \"תנה לי\" ונתנה לו — טמאה\u0004 המעפורת, ואף שחבירו טהור, כיון שבאותה שעה הסיח דעתו משמירה — הרי זה כאילו נטמאה. ובדומה לכך \u0003אמר ר' יונתן בן עמרם: נתחלפו לו כלים\u0004 (בגדים) \u0003של שבת בכלים של\u0004 יום \u0003חול ולבשן — נטמאו,\u0004 שחשב שבגדים אחרים הם, והרי זה היסח דעת ושוב אין שמירתו נחשבת.","\u0003אמר ר' אלעזר בר צדוק: מעשה בשתי נשים חבירות\u0004 (שהיו מקפידות על טהרה), \u0003שנתחלפו להן כליהן בבית המרחץ, ובא מעשה לפני ר' עקיבא וטימאן.\u0004 הרי שעשיית דבר שלא בכוונה נחשבת כהיסח הדעת, ומטמא, גם אם אין טעם להחזיק טומאה בו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אושעיא: אלא מעתה,\u0004 לפי הנחה זו, אם \u0003הושיט ידו לסל ליטול פת חטין ועלתה בידו\u0004 במקומה \u0003פת שעורים, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003נטמאת\u0004 הפת?","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר, כך הוא גם כן]\u0006 — \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המשמר את החבית\u0004 מלהטמא \u0003בחזקת\u0004 שהיא חבית \u0003של יין ונמצאת\u0004 שהיא \u0003של שמן — טהורה מלטמא,\u0004 משמע שהעובדה שלא ידע מה הוא שומר אינה גורמת כשלעצמה לטומאה! ודוחים: \u0003ולטעמיך אימא סיפא\u0004 \u0005[ולפי טעמך,\u0006 לשיטתך, \u0005אמור את סופה]\u0006 של אותה ברייתא, ששנינו בה: \u0003ואסורה מלאכול,\u0004 משמע שבאמת אין זו נחשבת שמירה גמורה. ושואלים: באמת \u0003אמאי\u0004 \u0005[מדוע],\u0006 מה הסיבה לחלק בין טומאה לאיסור אכילה? שאם אין הטעות פוגמת בשמירה לענין טהרה, היתה צריכה להיות גם מותרת באכילה!","\u0003אמר ר' ירמיה:\u0004 כאן מדובר \u0003באומר \"שמרתיה מדבר המטמאה ולא מדבר הפוסלה\".\u0004 כלומר, דקדקתי בשמירה לשומרה רק מדבר שהוא מטמא טומאה חמורה, הגורמת שהדבר שנטמא מטמא גם אחרים, אבל לא שמרתיה מטומאה קלה שרק פוסלת אותה (שהיא עצמה נטמאת ואינה מטמאה). ולכן כיון ששמרה מטומאה — טהורה היא מלטמא אחרים, אבל אסורה באכילה שמא נפסלה בטומאה.","ושואלים: \u0003ומי איכא נטירותא לפלגא\u0004 \u0005[והאם יש שמירה למחצה],\u0006 שאפשר להגיד שאדם נשמר רק מדרגה מסויימת של טומאה בלבד? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הושיט ידו בסל\u0004 המלא תאנים, \u0003והסל\u0004 מונח \u0003על כתיפו, והמגריפה\u0004 המיועדת לגריפת אפר מן הכירה וגם להפרדת התאנים הדבוקות זו מזו, \u0003בתוך הסל, והיה בלבו על הסל\u0004 לשומרו בטהרה \u0003ולא היה בלבו על המגריפה, הסל טהור והמגריפה טמאה.\u0004","ושואלים: ומדוע \u0003הסל טהור? תטמא המגריפה לסל\u0004 אם נחשבת היא טמאה! ומשיבים: דין הוא ש\u0003אין כלי מטמא כלי\u0004 ולכן הסל טהור. ושואלים: \u0003וליטמא\u0004 \u0005[ושיטמא]\u0006 \u0003מה שבסל\u0004 שאיננו כלי, אלא אוכל, והוא טמא מחמת כלי! \u0003אמר רבינא: באומר: שמרתיו\u0004 את המגריפה \u0003מדבר שמטמאו\u0004 ולכן אין המגריפה מטמאה אחרים \u0003ולא\u0004 שמרתיו \u0003מדבר הפוסלו,\u0004 ולכן היא עצמה נטמאת. ואם כן אין להוכיח מזה שאין החבית מותרת באכילה.","וחזרנו לבעיה הראשונה, \u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 מדוע כאשר טועה אדם במה שהוא משמר שייחשב כטמא? הלא שנינו במפורש שהמשמר את החבית בחזקת שהיא של יין ונמצאת שהיא של שמן, הריהי טהורה מלטמא!","\u0003ועוד מותיב\u0004 \u0005[מקשה]\u0006 \u0003רבה בר אבוה: מעשה באשה אחת שבאת\u0004 (באה) \u0003לפני ר' ישמעאל, ואמרה לו: רבי, בגד זה ארגתיו בטהרה, ולא היה בלבי לשומרו בטהרה.\u0004 כלומר, לא התכוונתי לשומרו לשם כך אבל אני יודעת שלא היתה כל טומאה בדבר. \u0003ומתוך בדיקות שהיה ר' ישמעאל בודקה\u0004 אם אמנם היה הכל בטהרה, \u0003אמרה לו\u0004 בתוך דבריה: \u0003רבי,\u0004 אשה אחרת שהיתה באותה שעה \u0003נדה משכה עמי בחבל\u0004 בשעת אריגה, ואם כן נטמא הבגד ממש על ידי היסט הנידה. \u0003אמר ר' ישמעאל: כמה גדולים דברי חכמים, שהיו אומרים: בלבו לשומרו — טהור, אין בלבו לשומרו — טמא.\u0004 שהרי רואים מכאן שכיון שלא היה בליבה לשמור בטהרה, באה לידי טומאה בלי שתשים לב לזה.","\u0003שוב מעשה באשה אחת שבאת\u0004 (באה) \u0003לפני ר' ישמעאל,\u0004 ו\u0003אמרה לו: רבי, מפה זו ארגתיה בטהרה, ולא היה בלבי לשומרה\u0004 מטומאה. \u0003ומתוך בדיקות שהיה ר' ישמעאל בודקה, אמרה לו: רבי, נימא\u0004 (חוט) \u0003נפסקה לי וקשרתיה בפה,\u0004 ומן הסתם נרטב החוט ברוק, וכיון שהיה חוט רטוב יש לחשוש שמא נגע בו טמא ונטמאה המפה מחמת משקים טמאים. שכן גזרו חכמים שכל טומאה הנוגעת במשקה, הריהי מטמאה אותו שני לטומאה ואף מטמאה את הכלי שנגעה בו.","\u0003אמר ר' ישמעאל: כמה גדולים דברי חכמים, שהיו אומרים: בלבו לשומרו — טהור, אין בלבו לשומרו — טמא.\u0004 ומכל מקום למדים אנו שאם מתכוון לשמירה בטהרה, אף שטעה בפרט מסויים, אין זה היסח דעת המטמא.","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' אלעזר בר צדוק\u0004 בשתי נשים חברות שנתחלפו בגדיהן, אפשר לומר: \u0003כל אחת ואחת אומרת\u0004 בליבה: \u0003חברתי אשת עם הארץ\u0004 ולא חבירה, \u0003ומסחה דעתה מינה\u0004 \u0005[ומסיחה\u0006 את \u0005הדעת ממנה\u0006 מבגדיה\u0005]\u0006 מפני שבטוחה שכבר נטמאו, והיסח הדעת פוסל לענין זה כטומאה.","ואף \u0003לר' יונתן בן עמרם\u0004 במי שנתחלפו לו כלי שבת בשל חול \u0003נמי\u0004 \u0005[גם כן]\u0006 יש לומר, \u0003כיון\u0004 ש\u0003כלים\u0004 של \u0003שבת עביד להו\u0004 \u0005[עושה להם]\u0006 \u0003שימור טפי\u0004 \u0005[יתר]\u0006 וכיון שחושב שהם של חול \u0003מסח דעתיה מינייהו\u0004 \u0005[מסיח\u0006 את \u0005דעתו מהם]\u0006 מאותה שמירה מעולה, והיסח דעת זה פוסל. \u0003אלא לר' יונתן בן אלעזר\u0004 שחבירו מרים לו את המעפורת, מדוע נחשב הדבר כהיסח דעת? \u0003נעביד להו\u0004 \u0005[שיעשה להם]\u0006 \u0003שימור בידיה דחבריה\u0004 \u0005[בידו של חבירו]\u0006 וישמור שלא יטמאו, ומדוע הם נטמאים?","\u0003אמר ר' יוחנן: חזקה, אין אדם משמר מה שביד חברו.\u0004 שכיון שהדבר ביד אחר — מסיח הוא דעתו משמירתו. ושואלים: \u0003ולא\u0004 וכי אין אדם יכול לשמור דבר שביד חבירו?"],["\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיו חמריו ופועליו\u0004 שהיו עמי הארץ \u0003טעונין\u0004 (נושאים) \u0003טהרות,\u0004 ואינם נוגעים בטהרות עצמן אלא בכלי חרס שבהם הן מונחות, \u0003אף על פי שהפליג\u0004 (שהתרחק) \u0003מהן\u0004 בתוך הליכתו \u0003יותר ממיל — טהרותיו טהורות,\u0004 שכיון שלא ידעו שהלך, הרי הוא משמר מה שבידם, ואין לחשוש שמא נגעו בטהרות. \u0003ואם אמר להם: \"לכו ואני אבוא אחריכם\", כיון שנתעלמו עיניו מהן — טהרותיו טמאות.\u0004","ושואלים: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה\u0006 ב\u0005התחלה ומה שונה\u0006 ב\u0005סוף]?\u0006 \u0003אמר ר' יצחק נפחא: רישא\u0004 \u0005[בראש]\u0006 מדובר \u0003במטהר חמריו ופועליו לכך\u0004 שדואג שיטבלו ויטהרו קודם לכן, ואז אין לחשוש לטומאה.","ושואלים: \u0003אי הכי, סיפא נמי\u0004 \u0005[אם כך,\u0006 במקרה ששנינו ב\u0005סופה גם כן]\u0006 יהיו טהורים! ומשיבים: \u0003אין עם הארץ מקפיד על מגע חבירו,\u0004 ושמא פגעו בדרכם בעם הארץ אחר, והוא נגע וטימא את הדברים.","ומקשים: \u0003אי הכי, רישא נמי\u0004 \u0005[אם כך, בתחילת\u0006 הברייתא \u0005גם כן]\u0006 נחשוש שמא פגשו בעם הארץ שנגע בהם. ואף שהזהיר פועליו להשמר בטהרה, הרי הם אינם חוששים לטומאת עם הארץ! ומשיבים: \u0003בבא להם דרך עקלתון,\u0004 כשאינו הולך ממש אחריהם, באופן שרואים אותו, אלא שיכול לבוא בדרך עקומה, וכיון שחוששים בכל רגע שיבוא — נזהרים שלא להטמא, ולכן נשמרים גם ממגע עמי הארץ אחרים אף שכשלעצמם אינם מקפידים על כך.","ומקשים: \u0003אי הכי, סיפא נמי\u0004 \u0005[אם כך, בסוף גם כן]\u0006 כיון שבא להם בדרך עקלתון שיכול לבוא בכל רגע ולראותם וודאי חוששים הם ונזהרים! ומשיבים: \u0003כיון\u0004 ש\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"לכו ואני אבוא אחריכם\" — מיסמך סמכא דעתייהו\u0004 \u0005[סומכת דעתם]\u0006 שלא יראה, ושוב אין הם מקפידים.","","\u0003חומר\u0004 (חומרה, הקפדה יתירה) יש \u0003בקדש מבתרומה,\u0004 כיצד? \u0003שמטבילין כלים\u0004 טמאים \u0003בתוך כלים\u0004 אחרים שאף הם טמאים \u0003לתרומה, אבל לא לקדש,\u0004 שלקודש צריך להטביל כל כלי לעצמו. וכן יש דין \u0003אחוריים ותוך ובית הצביטה\u0004 (מקום אחיזת הכלי) \u0003ב\u0004כלים של \u0003תרומה\u0004 שבכל אחד מאלה יש שימוש לעצמו, הרי כל אחד נחשב לכלי לעצמו, ואם נטמא — אינו מטמא את כל הכלי, \u0003אבל לא בקדש,\u0004 שבקודש אם נטמא חלק מן הכלי — כולו טמא.","וכן \u0003הנושא את המדרס\u0004 (דבר הטמא בטומאת מדרס הזב) יכול להיות \u0003נושא את התרומה\u0004 באותה שעה, אם נזהר שלא יגעו זה בזה, \u0003אבל לא את הקדש,\u0004 שאם נשא באותה שעה את הקודש, הרי הקודש נטמא. \u0003בגדי אוכלי תרומה\u0004 נחשבים כאילו היו \u0003מדרס ל\u0004אוכלי \u0003קדש.\u0004","ועוד חומרות בקודש: \u0003לא כמדת הקדש מדת התרומה; שבקדש\u0004 אם היתה לו ערימה של כלים או בגד קשור, הריהו \u0003מתיר\u0004 את הקשר \u0003ומנגב\u0004 אם היתה בו לחות, שכל אלה נחשבים כחציצה, \u0003ו\u0004אחר כך \u0003מטביל, ואחר כך\u0004 אם רוצה \u0003קושר\u0004 שוב. \u0003ובתרומה,\u0004 אם רוצה \u0003קושר\u0004 מלכתחילה \u0003ואחר כך מטביל,\u0004 ואינו צריך לחשוש לחציצה.","\u0003כלים הנגמרים בטהרה\u0004 שנזהרו בהם בגמר עשייתם שלא יבואו לידי טומאה, בכל זאת \u0003צריכין טבילה לקדש\u0004 כדי שייחשבו לטהורים, \u0003אבל לא לתרומה\u0004 שאנחנו סומכים על טהרת הכלי בשעת עשייתו. ועוד: \u0003הכלי מצרף מה שבתוכו לקדש\u0004 שכל הדברים הנמצאים בתוך הכלי, אפילו אינם נוגעים זה בזה, נחשבים כיחידה אחת, ואם נטמא אחד מהם — כולם טמאים. \u0003אבל לא לתרומה\u0004 שכל אחד נטמא לעצמו והשאר טהורים.","ועוד: \u0003הרביעי\u0004 לטומאה \u0003בקדש — פסול,\u0004 כלומר, טמא בטומאה קלה ואינו מטמא אחר במגעו, \u0003והשלישי\u0004 בלבד פסול \u0003בתרומה,\u0004 והרביעי בו טהור לחלוטין. ועוד: \u0003ובתרומה, אם נטמאת אחת מידיו\u0004 בטומאה מדברי סופרים המטמאת ידים בלבד — \u0003חבירתה טהורה, ובקדש\u0004 אם נטמאת אחת — \u0003מטביל שתיהן, שהיד מטמא את חבירתה בקדש אבל לא בתרומה.\u0004 ועוד: \u0003אוכלין אוכלים\u0004 (מאכלים) \u0003נגובין\u0004 (יבשים) שלא הוכשרו לקבל טומאה \u0003בידים מסואבות\u0004 (טמאות שני לטומאה) \u0003בתרומה\u0004 שהרי לא הוכשרו לקבל טומאה \u0003אבל לא בקדש.\u0004"],["\u0003האונן\u0004 מי שמת עליו מת (ועדיין לא נקבר) ולא נגע בו \u0003ומחוסר כפורים\u0004 מי שהיה חייב להביא קרבן לאחר טהרתו, כגון זב שספר שבעה וטבל לטהרתו, או יולדת שטבלה והעריב שמשם — אלה, גם אחרי שהביאו את קרבנם, אסורים לאכול קדשים והם \u0003צריכים טבילה\u0004 לפני כן, אבל זאת — רק כדי \u0003ל\u0004אכול \u0003קדש אבל לא לתרומה.\u0004","שנינו במשנה שבקודש אין מטבילים כלים בתוך כלים. ושואלים: \u0003בקדש מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 מטבילים, איזה חשש יש בדבר? \u0003אמר ר' אילא: מפני שכבידו\u0004 (כובדו) \u0003של כלי חוצץ,\u0004 שהרי הכלי לוחץ מעט על הכלי החיצון וגורם לחציצה כלשהי בפני המים.","ושואלים: \u0003והא מדסיפא\u0004 \u0005[והרי מ\u0006כיון \u0005שסופה\u0006 של המשנה, כלומר, בהמשכה\u0005],\u0006 מדובר על הבדל בין קודש לתרומה שהוא \u0003משום חציצה, רישא\u0004 \u0005[תחילתה]\u0006 אם כן ודאי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משום חציצה\u0004 הוא, אלא ודאי מטעם אחר! \u0003דקתני סיפא\u0004 \u0005[ששנה בסופה]:\u0006 \u0003ולא כמדת הקדש מדת התרומה, שבקדש מתיר ומנגיב ומטביל ואחר כך קושר, ובתרומה קושר ואחר כך מטביל,\u0004 משמע שחוששים לחציצה כלשהי בקודש, ומן הסתם יש למעלה ראשונה טעם אחר, ולא משום חציצה!","ומשיבים: לא, \u0003רישא וסיפא\u0004 \u0005[\u0006גם \u0005בתחילתה ו\u0006גם \u0005בסופה\u0006 של המשנה\u0005]\u0006 החשש הוא \u0003משום חציצה, ו\u0004בכל זאת \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם, \u0003דאי אשמעינן רישא\u0004 \u0005[שאילו\u0006 \u0005היה משמיע לנו\u0006 את \u0005ההתחלה\u0006 בלבד\u0005]\u0006 שלא יטבול כלי בתוך כלי, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 ש\u0003לקדש לא\u0004 עושים זאת — \u0003משום כבידו של כלי דאיכא\u0004 \u0005[שיש\u0006 כאן\u0005]\u0006 \u0003אבל סיפא\u0004 \u0005[\u0006ב\u0005סופה]\u0006 \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003כבידו של כלי — אימא\u0004 \u0005[אמור]\u0006 כי \u0003לקדש נמי לא הוי\u0004 \u0005[גם כן אינה]\u0006 \u0003חציצה. ואי אשמעינן סיפא\u0004 \u0005[ואם היה משמיע לנו\u0006 רק \u0005בסופה],\u0006 בענין הקשירה, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 ש\u0003לקדש לא, משום\u0004 שייתכן"],["\u0003דקיטרא במיא אהדוקי מיהדק\u0004 \u0005[שהקשר במים מתהדק\u0006 יותר\u0005]\u0006 ואין המים נכנסים בפנים כל צורכם, \u0003אבל רישא\u0004 \u0005[בראש\u0006 המשנה\u0005],\u0006 \u0003דמיא אקפויי מקפו ליה למנא לא הויא\u0004 \u0005[שהמים\u0006 מקילים \u0005ומציפים את הכלי\u0006 הפנימי, הייתי אומר כי \u0005אין היא]\u0006 \u0003חציצה,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 ההלכה להיאמר בשני המקרים.","ומעירים: \u0003ר' אילא\u0004 הלך בביאורו \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ולכן צירף את שני הדינים הללו כאחד, ש\u0003אמר ר' אילא אמר ר' חנינא בר פפא: עשר מעלות שנו כאן\u0004 בהבדל שבין קודש לתרומה, ולא כפי שנראה שהן אחת עשרה; \u0003חמש ראשונות\u0004 הן \u0003בין לקדש\u0004 עצמו \u0003בין לחולין שנעשו על טהרת הקדש,\u0004 ואילו חמש \u0003אחרונות\u0004 הן \u0003לקדש\u0004 בלבד \u0003אבל לא לחולין שנעשו על טהרת הקדש.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של חלוקה זו — \u0003חמש קמייתא\u0004 \u0005[ראשונות]\u0006 \u0003דאית להו דררא\u0004 \u0005[שיש בהן גרר]\u0006 של \u0003טומאה מדאורייתא\u0004 \u0005[מן התורה],\u0006 שנובעות מן החשש שמא לא היתה הטהרה כראוי, ותחילת הטומאה היתה טומאה מן התורה, לכך \u0003גזרו בהו רבנן\u0004 \u0005[בהן חכמים]\u0006 \u0003בין לקדש בין לחולין שנעשו על טהרת הקדש,\u0004 אבל חמש \u0003בתרייתא\u0004 \u0005[אחרונות]\u0006 \u0003דלית להו דררא\u0004 \u0005[שאין בהן גרר]\u0006 של \u0003טומאה מדאורייתא\u0004 \u0005[מן התורה]\u0006 אלא מבוססות מתחילתן רק על גזירות חכמים, לכך \u0003גזרו בהו רבנן\u0004 \u0005[בהן חכמים]\u0006 \u0003לקדש,\u0004 אבל \u0003לחולין שנעשו על טהרת הקדש לא גזרו בהו רבנן\u0004 \u0005[בהן חכמים].\u0006 וכדי שיימנו רק עשר מעלות הבדלים, ולא אחת עשרה כפי שמנויות במשנה, צריך לצרף שתי מעלות, שהן מחשש חציצה, לאחת.","\u0003רבא אמר\u0004 שלא כר' אילא, וסבור כי \u0003מדסיפא הוי\u0004 \u0005[מ\u0006כיון \u0005שבסופה\u0006 הטעם \u0005הוא]\u0006 \u0003משום חציצה — רישא לאו\u0004 \u0005[\u0006ב\u0005ראשיתה אינה]\u0006 \u0003משום חציצה, ורישא\u0004 \u0005[וראשיתה],\u0006 הלכה זו שאין טובלים כלי בתוך כלי, \u0003היינו טעמא\u0004 \u0005[זה הטעם]:\u0006 \u0003גזירה שלא יטביל\u0004 כלים קטנים, כמו \u0003מחטין וצינורות\u0004 (מסרגות) \u0003ב\u0004תוך \u0003כלי שאין בפיו\u0004 פתח שגודלו \u0003כשפופרת הנוד. כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003עירוב\u0004 שני \u0003מקוואות\u0004 סמוכים, כאשר באחד ארבעים סאה כהלכתו והשני חסר, ורוצים להכשירו על ידי חיבור שניהם ועירוב מימיהם ובכך להחשיבם למקוה אחד, צריך שיהא ביניהם פתח \u0003כשפופרת\u0004 המונחת בפי \u0003הנוד,\u0004 הן \u0003כעוביה\u0004 (ברוחבה), שיהא הנקב רחב לא פחות משיעור זה,"],["\u0003ו\u0004הן \u0003כחללה\u0004 (כגובהה) ושיעור זה הוא \u0003בשתי אצבעות חוזרות למקומן,\u0004 כלומר, שאפשר להכניס שם שתי אצבעות והן יכולות להסתובב מצד לצד. וכיון שפתח ששיעורו קטן מזה אינו נחשב כחיבור גזרו גם על טבילה בכלי, שמא יהא פתחו צר משיעור זה ולא ייחשבו המים שבו כמחוברים למקוה.","ומעירים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כהא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רב נחמן אמר רבה בר אבוה: אחת עשרה מעלות שנו כאן; שש ראשונות — בין לקדש בין לחולין שנעשו על טהרת הקדש, אחרונות — לקדש, אבל לא לחולין שנעשו על טהרת הקדש\u0004 ולא עשר כדברי ר' אילא.","ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 מה ההבדל הלכה למעשה \u0003בין\u0004 שיטתו של \u0003רבא\u0004 שהחשש הוא משום חציצה, \u0003ל\u0004שיטתו של \u0003ר' אילא\u0004 שהחשש הוא שמא יטביל מחטים וצינוריות בכלי שאין בפיו כשפופרת הנוד?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה אם היה זה \u0003סל וגרגותני\u0004 (סל רחב, המשמש בגת) \u0003שמילאן כלים והטבילן. למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר],\u0006 שהחשש בכלי בתוך כלי הוא \u0003משום חציצה\u0004 (שיטת ר' אילא) — אם כן \u0003איכא\u0004 \u0005[יש]\u0006 גם כאן חשש חציצה, שהרי יתכן שהכלי הפנימי ילחץ על הסל ואין הטבילה עולה יפה. אבל \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003משום גזירה שמא יטביל מחטין וצינורות בכלי שאין בפיו כשפופרת הנוד\u0004 (שיטת רבא) — \u0003סל וגרגותני שאין בפיהן כשפופרת הנוד, ליכא\u0004 \u0005[אין]\u0006 בנמצא, ולכן לא גזרו בהם.","ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: סל וגרגותני שמילאן כלים והטבילן — טהורין\u0004 לכל דבר.","\u0003ו\u0004אולם \u0003מקוה שחלקו בסל וגרגותני\u0004 אם בכל חלק מן המקוה יש פחות מכשיעור ארבעים סאה — \u0003הטובל שם לא עלתה לו טבילה.\u0004 ואף על פי שודאי המים מחלחלים דרך הסל או הגרגותני, אין זה נחשב כמחובר, \u0003דהא ארעא\u0004 \u0005[שהרי האדמה]\u0006 \u0003כולה חלחולי מחלחלא\u0004 \u0005[מחלחלת]\u0006 \u0003ו\u0004בכל זאת \u0003בעינן דאיכא\u0004 \u0005[צריכים אנו שיהיו]\u0006 \u0003ארבעים סאה במקום אחד\u0004 ואין סומכים על החילחול.","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שהמטביל מחטים וצינוריות טמאים בתוך כלי שאין בפיו כשפופרת הנוד לא עלתה להם טבילה, אמורים דווקא כאשר חילק את המקוה או הטבילם \u0003בכלי טהור, אבל\u0004 אם חילק את המקוה או הטבילם \u0003בכלי טמא, מיגו דסלקא\u0004 \u0005[מתוך שעולה]\u0006 \u0003טבילה לכוליה גופיה דמנא\u0004 \u0005[לכל גופו של הכלי]\u0006 שאף תוכו נטהר במים הנכנסים דרך פיו, \u0003סלקא להו נמי\u0004 \u0005[עולה להם\u0006 הטבילה \u0005גם כן]\u0006 \u0003לכלים דאית ביה\u0004 \u0005[שיש בו],\u0006 וכיון שהכלים עצמם נחשבים כטובלים אי אפשר לומר שהם חוצצים.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כלים שמילאן כלים והטבילן — הרי אלו טהורין. ואם לא טבל, מים המעורבים — עד שיהיו מעורבין כשפופרת הנוד.\u0004 קטע אחרון זה שבמשנה אינו ברור כלל, ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 מה פירוש המילים \u0003ואם לא טבל?\u0004 ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003ואם אינו צריך להטבילו,\u0004 כלומר, שהכלי החיצון שמטבילים בו היה כלי טהור, \u0003ו\u0004כן \u0003מים המעורבין\u0004 המחוברים למקוה על ידי נקב שיעורם לטהר \u0003עד שיהו מעורבין כשפופרת הנוד.\u0004","ומעירים: \u0003והא\u0004 \u0005[וזו]\u0006 המחלוקת של \u0003רבא ו\u0004של \u0003ר' אילא תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סל וגרגותני שמילאן כלים והטבילן — בין לקדש בין לתרומה טהורין. אבא שאול אומר: לתרומה, אבל לא לקדש.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ל\u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 לא יהיו טהורים, שאם אבא שאול אינו מחלק בין סל לשאר כלים, וטעמו משום חציצה — יש לחשוש לכך גם לענין תרומה! ומשיבים: בענין תרומה \u0003למאן קאמרינן\u0004 \u0005[ל\u0006דעת \u0005מי אנחנו אומרים]\u0006 שאין לטבול כלי בתוך כלי — ל\u0003חברים,\u0004 שהם הנזהרים בטהרת תרומה, והם הבאים לשאול בענין זה — ה\u0003חברים מידע ידעי\u0004 \u0005[יודעים]\u0006 את ההלכה, והם נזהרים שלא לטבול בכלי שיש בו חשש חציצה (או פתח צר מדי).","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 ב\u0003קודש נמי\u0004 \u0005[גם כן]\u0006 יש לומר כי הבאים לשאול על טהרת הקודש חברים הם, והם ידעו לעשות כדין! ומשיבים: בקודש יש לחשוש שמא \u0003חזי ליה\u0004 \u0005[יראה אותו]\u0006 \u0003עם הארץ ואזיל מטביל\u0004 \u0005[וילך ויטביל]\u0006 ולא יזהר שלא תהא חציצה.","ומקשים: אם כן, ב\u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 יש לחשוש שמא \u0003חזי ליה\u0004 \u0005[יראה אותו]\u0006 \u0003עם הארץ\u0004 מטביל כך \u0003ואזיל מטביל\u0004 \u0005[וילך ויטביל]!\u0006 ומשיבים: \u0003לא מקבלינן מינייהו\u0004 \u0005[אין אנחנו מקבלים מהם],\u0006 מעמי הארץ תרומה ודברים שנעשו בטהרת תרומה, ואין סומכים על טהרתם לתרומה, ולכן אין מקום לחשש.","ושואלים: אם כן, \u0003קודש נמי\u0004 \u0005[גם כן]\u0006 \u0003לא נקביל מינייהו\u0004 \u0005[נקבל מהם]\u0006 ולא נצטרך לחשוש שמא עשו שלא כדין! ומשיבים: \u0003הויא ליה\u0004 \u0005[תהיה לו]\u0006 \u0003איבה\u0004 לעם הארץ אם לא יקבלו ממנו, ותיווצר מחלוקת בתוך עם ישראל.","ושואלים: אם כן, ב\u0003תרומה נמי הויא ליה\u0004 \u0005[גם כן תהיה לו]\u0006 \u0003איבה\u0004 כשאין מקבלים ממנו! ומשיבים: \u0003לא איכפת,\u0004 לא חשוב \u0003ליה\u0004 \u0005[לו]\u0006 לעם הארץ בתרומה, שאם לא יקבלנה ממנו החבר \u0003דאזיל יהיב ליה\u0004 \u0005[הולך\u0006 ו\u0005נותן אותה]\u0006 \u0003לכהן עם הארץ חבריה\u0004 \u0005[חבירו]\u0006 שאף הוא אינו מקפיד בזה. אבל בקודש, כיון שהדבר נעשה במקום אחד עבור כל ישראל, יש לעשות באופן שלא תיווצר איבה.","ומעירים: \u0003ומאן תנא דחייש\u0004 \u0005[ומי הוא התנא שחושש]\u0006 \u0003לאיבה\u0004 זו — \u0003ר' יוסי היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 \u0003בברייתא\u0004\u0005],\u0006 \u0003אמר ר' יוסי: מפני מה הכל נאמנין על טהרת יין ושמן כל ימות השנה\u0004 לגבי קדשים, ואין בודקים אם אכן היין והשמן היו טהורים לקודש — כדי שלא לעשות פירוד בעם ישראל, \u0003כדי שלא יהא כל אחד ואחד הולך ובונה במה לעצמו, ושורף פרה אדומה לעצמו.\u0004 שאם יבואו לגזור בקדשים, יבוא כל אדם לומר שמא זה של חבירו איננו טהור דיו, ויגיעו עד לעשיית מקדש נפרד.","\u0003אמר רב פפא: כמאן מקבלינן האידנא סהדותא\u0004 \u0005[כ\u0006דעת \u0005מי אנחנו מקבלים כעת,\u0006 בימינו, \u0005עדות]\u0006 \u0003מעם הארץ\u0004 אף שיש חכמים החוששים שעם הארץ, כיון שאינו מדקדק בהלכה, שמא אף אינו נאמן בדיבורו — \u0003כמאן\u0004 \u0005[כמי]\u0006 \u0003כר' יוסי.\u0004","ושואלים: מדוע הותר להטביל כלי בתוך כלי לתרומה, \u0003וניחוש\u0004 \u0005[ונחשוש]\u0006 \u0003לשאלה,\u0004 שיש לחשוש שמא יראה זאת עם הארץ ויעשה כמו כן ויבוא חבר וישאל ממנו כלי של תרומה, וכיון שיתכן שהכלי לא נטבל כהלכה נמצא שהוא משתמש בדברים שאינם טהורים, והלא מצאנו שחכמים מתירים לשאול כלים מעם הארץ.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו במשנה]:\u0006 \u0003כלי חרס\u0004 סגור שהיה מוקף צמיד פתיל, והיו דברים אחרים בתוכו, והיה באוהל המת, או שהיה מת בבית וטהרות בעלייה וארובה פתוחה בין הבית והעלייה והניחו כלי חרס בפתח הארובה — כלי זה \u0003מציל על הכל,\u0004 שכל מה שבתוך הכלי או בעלייה איננו נטמא (ככתוב בתורה, במדבר יט, טו), אלו \u0003דברי בית הלל. בית שמאי אומרים: אינו מציל אלא על אוכלים ועל המשקים ועל כלי חרס,\u0004 אבל לא על כלי מתכת ועץ שבתוכו.","\u0003אמרו להם בית הלל לבית שמאי: מפני מה?\u0004 מה הטעם לחלוקה זו? שהרי כלי חרס טהור וסגור חוצץ בפני טומאת המת! \u0003אמרו בית שמאי: מפני שהוא,\u0004 כלי החרס הסגור עצמו, \u0003טמא על גבי עם הארץ,\u0004 שהרי עם הארץ נגע בו, וגזרו חכמים טומאה במגע עם הארץ, שמן הסתם לא נטהר כהלכה, \u0003ו\u0004כלל הוא כי \u0003אין כלי טמא חוצץ\u0004 בפני הטומאה. \u0003אמרו להם בית הלל: והלא טיהרתם אוכלין ומשקין שבתוכו,\u0004 ולא חששתם לכך! \u0003אמרו להם בית שמאי: כשטיהרנו אוכלין ומשקין שבתוכו\u0004"],["\u0003ל\u0004עם הארץ \u0003עצמו טהרנו,\u0004 שהוא יאכלם, אבל לא חברים.","\u0003אבל\u0004 האם \u0003נטהר את הכלי, שטהרתו לך ולו,\u0004 שהרי אף אתה החבר שואל ממנו, ומשתמש בו.","באותו ענין \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר ר' יהושע: בושני\u0004 (מתבייש אני) \u0003מדבריכם, בית שמאי!\u0004 על סברה מוזרה זו שלכם; וכי \u0003אפשר\u0004 ש\u0003אשה\u0004 תהא עומדת בעלייה ו\u0003לשה\u0004 בצק \u0003בעריבה,\u0004 שיהיו לדעתכם ה\u0003אשה ו\u0004ה\u0003עריבה טמאין\u0004 טומאת \u0003שבעה\u0004 (משום שכלי החרס חוצץ) \u0003ו\u0004ה\u0003בצק\u0004 שבתוך העריבה \u0003טהור,\u0004 שהרי אוכלין אף לבית שמאי טהורים? וכן \u0003לוגין\u0004 (כלי משקה) ה\u0003מלא משקין,\u0004 וכי יהיה ה\u0003לוגין טמא טומאת שבעה, ומשקין טהורין?!\u0004","לאחר שאמר דברים אלה \u0003נטפל\u0004 (ניגש) \u0003לו תלמיד אחד מתלמידי בית שמאי, אמר לו: אומר לך טעמן של בית שמאי. אמר לו: אמור. אמר לו: כלי טמא חוצץ, או אינו חוצץ? אמר לו\u0004 ר' יהושע: יודעים אנו ש\u0003אינו חוצץ.\u0004 אמר לו אותו תלמיד מבית שמאי: \u0003כלי של עם הארץ טמא או טהור? אמר לו: טמא.\u0004 אמר לו אותו תלמיד \u0003ואם אתה אומר לו\u0004 לעם הארץ שהכלי \u0003טמא, כלום משגיח עליך? ולא עוד אלא שאם אתה אומר לו \"טמא\" אומר לך \"שלי טהור ושלך טמא\".\u0004","\u0003וזהו טעמן של בית שמאי,\u0004 שמאכלים ומשקים בכלי חרס אינם טמאים, שאם של עם הארץ הם — הוא ישתמש בהם ולא ישברם ולא יבערם, וחברים לא ישאלום ממנו. אבל כלים שאפשר לטהר בטבילה (\"כלי שטף\"), גזרו עליהם, שגם אם ישאלם חבר — יטבילם.","כיון ששמע שיש לבית שמאי טעם הגון, \u0003מיד הלך ר' יהושע ונשתטח על קברי בית שמאי, אמר: נעניתי\u0004 (חטאתי) \u0003לכם עצמות בית שמאי! ומה סתומות שלכם כך,\u0004 שדברים בלתי מובנים יש להם הסבר, \u0003מפורשות על אחת כמה וכמה. אמרו: כל ימיו הושחרו שיניו מפני תעניותיו,\u0004 שהיה מתענה לכפר על מה שאמר דברי זלזול על בית שמאי.","\u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 באותה משנה שאין מטהרים כלי ש\u0003\"\u0004טהרתו \u0003לך ולו\", אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003שאלינן מינייהו\u0004 \u0005[שואלים אנחנו\u0006 כלים \u0005מהם\u0006 מעמי הארץ\u0005]\u0006 ואם כן, יש לשאול מפני מה אין חוששים שישאלו כלים מעמי הארץ כשאין הם מטבילים אותם כראוי! ומשיבים: \u0003כי שיילינן מינייהו מטבלינן להו\u0004 \u0005[כאשר שואלים אנו מהם\u0006 כלים \u0005מטבילים אנו אותם].\u0006","ושואלים: \u0003אי הכי, ניהדרו להו\u0004 \u0005[אם כך, ישיבו להם]\u0006 \u0003בית הלל לבית שמאי: כי שאלינן מנייהו מטבלינן להו\u0004 \u0005[כאשר שואלים אנו מהם מטבילים אנו אותם],\u0006 ולכן מטהרים הם את הכלי שטהרתו לך ולו! ועונים: באותה מחלוקת הרי מדובר בטומאת המת, \u0003וטמא מת בעי\u0004 \u0005[צריך]\u0006 \u0003הזאה\u0004 ביום ה\u0003שלישי ו\u0004ביום ה\u0003שביעי\u0004 לטהרתו, \u0003ומנא לשבעה יומי לא מושלי אינשי\u0004 \u0005[וכלי לשבעה ימים אין אנשים משאילים],\u0006 ולכן, תקנה זו של טבילה מועילה רק לטהר מטומאות אחרות, אבל לא מטומאת המת.","ושואלים לגוף הדבר: \u0003ו\u0004האם על ה\u0003טבילה לא מהימני\u0004 \u0005[נאמנים]\u0006 עמי הארץ? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נאמנין עמי הארץ על טהרת טבילת טמא מת!\u0004","\u0003אמר אביי: לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ששנינו שנאמנים על הטבילה, הרי זה בטבילה \u0003בגופו\u0004 של אדם, \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שאינן נאמנים, הרי זה \u0003בכליו. רבא אמר: אידי ואידי\u0004 \u0005[זה וזה]\u0006 נאמר \u0003בכליו, ולא קשיא\u0004 \u0005[ואינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שנאמן, הרי זה כש\u0003אמר\u0004 עם הארץ: \u0003\"מעולם לא הטבלתי כלי בתוך כלי\",\u0004 ובזה אפשר להאמין לו. \u0003והא\u0004 \u0005[וזה]\u0006 שאינו נאמן, הרי זה כש\u0003אמר: \"הטבלתי, אבל לא הטבלתי בכלי שאין בפיו כשפופרת הנוד\".\u0004 שלענין זה, שיש פרטים דקים, אי אפשר לסמוך על עם הארץ.","\u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו]\u0006 ברייתא מעין זה: \u0003נאמן עם הארץ לומר\u0004 על \u0003פירות\u0004 ש\u0003לא הוכשרו\u0004 לקבל טומאה, כלומר, שלא נרטבו כלל, \u0003אבל אינו נאמן לומר\u0004 שה\u0003פירות הוכשרו\u0004 לקבל טומאה, \u0003אבל לא נטמאו.\u0004 הרי שבעובדה ברורה ופשוטה — סומכים על נאמנות עם הארץ, אבל לא בדברים שיש צורך בהם בידיעה מרובה ובהקפדה יתירה.","ושואלים לשיטת אביי: \u0003ו\u0004על \u0003גופו\u0004 של עם הארץ \u0003מי מהימן\u0004 \u0005[האם נאמן]\u0006 הוא לומר שאכן טבל? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003חבר שבא להזות — מזין עליו מיד,\u0004 שסומכים עליו שכבר ספר שלושה ימים; אבל \u0003עם הארץ שבא להזות — אין מזין עליו עד שיעשה\u0004 וימנה \u0003בפנינו שלישי ושביעי,\u0004 הרי שאין סומכים על עם הארץ בטומאת גופו!","\u0003אלא אמר אביי:\u0004 יש לחזור מאותו הסבר ולומר הסבר אחר ולומר כך: \u0003מתוך חומר שהחמרת עליו בתחילתו\u0004 שאין מניחים לו להיטהר מטומאת המת אלא כשבדקו אותו יפה ודאגו שיהיו טבילה וטהרה כראוי, \u0003הקלת עליו בסופו\u0004 שיהא נאמן על טהרת טומאת מת.","שנינו במשנה שיש \u0003אחורים ותוך\u0004 לתרומה, אבל לא לקדשים. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אחורים ותוך?\u0004","ועונים: \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כלי שנטמא אחוריו\u0004 (צידו האחורי, ולא מבפנים) \u0003במשקין\u0004 טמאים, שטומאה זו היא רק גזירה מדברי חכמים שיהיו משקים מטמאים כלי — \u0003אחוריו\u0004 בלבד \u0003טמאין,\u0004 אבל שאר החלקים שבו, כגון \u0003תוכו, אוגנו\u0004 (מקום שפת הכלי הכפולה), \u0003אזנו\u0004 שמחזיקים בו את הכלי, \u0003וידיו\u0004 (וידיותיו) — \u0003טהורין.\u0004 אבל אם \u0003נטמא תוכו — כולו טמא.\u0004 ודין זה אמור לגבי תרומה אבל בקודש — אם נטמא חלק בו — הכול טמא.","\u0003ו\u0004עוד שנינו במשנה כי יש \u0003בית הצביטה\u0004 לכלי של תרומה ולא לשל קודש. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בית הצביטה\"? אמר רב יהודה אמר שמואל: מקום שצובטו\u0004 \u0005[שמחזיקים אותו\u0006 בו\u0005],\u0006 כעין בית אחיזה לכלי. \u0003וכן הוא אומר: \"ויצבט לה קלי\"\u0004 (רות ב, יד), כלומר, נתן לה מעט קלי, משמע ש\"צביטה\" היא לשון אחיזה. \u0003ר' אסי אמר\u0004 בשם \u0003ר' יוחנן: מקום שנקיי הדעת\u0004 (איסטניסים) \u0003צובעין\u0004 (טובלים בו). שהיו עושים בצד הכלי בית קיבול קטן לתבלין, ובו היו מטבילים את המאכל. והוא כעין כלי הסמוך לכלי אחר.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב ביבי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן\u0004 ברייתא זו: \u0003כל הכלים אין להם\u0004 חילוק זה של \u0003אחורים ותוך, אחד קדשי המקדש ואחד קדשי הגבול,\u0004 אלא משנטמא אחד מהם, כל הכלי טמא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003קדשי הגבול מאי נינהו\u0004 \u0005[מה הם] —\u0006 הרי זה הכינוי המקובל עבור \u0003תרומה,\u0004 אם כן יש סתירה לכך מהמשנה; \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אחורים ותוך ובית הצביטה לתרומה!\u0004","ומשיבים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \"קדשי הגבול\" שאמרת אינם כמשמעם בכל מקום, אלא הכוונה \u0003לחולין שנעשו על טהרת הקדש קאמרת\u0004 \u0005[אמרת]\u0006 וקראו להם \"קדשי הגבול\", שהרי נוהגים מנהג טהרה זה גם מחוץ לבית המקדש.","וכיון שדנו בזה אמר רב נחמן: \u0003אדכרתן מילתא\u0004 \u0005[הזכרתני דבר]\u0006 בנושא זה ש\u0003אמר רבה בר אבוה: אחת עשרה מעלות שנו כאן; שש ראשונות — בין לקדש, בין לחולין שנעשו על טהרת הקדש, אחרונות — לקדש, אבל לא לחולין שנעשו על טהרת הקדש.\u0004 משמע שבהלכות אלה דנים בדמיון ובהבדל בין טהרת קודש עצמה לבין חולין על טהרת הקודש.","שנינו במשנה: \u0003הנושא את המדרס\u0004 בידו אחת \u0003נושא\u0004 עמו בידו האחרת \u0003את התרומה\u0004 ואינה נטמאת בכך, ובלבד שלא יגעו זה בזה, \u0003אבל לא את הקדש.\u0004 ושואלים: \u0003קודש מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 ישא, שהרי אם נזהר שלא לנגוע במדרס מדוע לא ישא את הקודש? משיבים: \u0003משום מעשה שהיה.\u0004 ש\u0003אמר רב יהודה אמר שמואל: מעשה באחד שהיה מעביר חבית של יין קודש ממקום למקום,\u0004"],["\u0003ונפסקה רצועה של סנדלו\u0004 שהיתה טמאה במדרס הזה, \u0003ונטלה והניחה\u0004 (את הרצועה) \u0003על פי\u0004 ה\u0003חבית, ונפלה\u0004 הרצועה \u0003לאויר\u0004 (לחלל) \u0003החבית, ונטמאת\u0004 החבית כולה. \u0003באותה שעה אמרו\u0004 וגזרו לעתיד: \u0003הנושא את המדרס — נושא את התרומה, אבל לא את הקדש.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היה המעשה, וגזרו משום מעשה זה, \u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 יגזרו בה שמא תארע בה תקלה דומה ותטמא אף היא! ומשיבים: \u0003הא מני\u0004 \u0005[זו כ\u0006שיטת \u0005מי]\u0006 — כשיטת \u0003ר' חנניה בן עקביא היא,\u0004 ש\u0003אמר\u0004 בנושא דומה: \u0003לא אסרו אלא בירדן, ובספינה, וכמעשה שהיה.\u0004 שלדעתו, כל מקום שגזרו חכמים על דבר מסויים כתוצאה ממעשה שהיה, לא הרחיבו את הגזירה לעניינים דומים, אלא דווקא באותו אופן עצמו.","ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 אותו ענין? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא ישא אדם מי חטאת ואפר חטאת\u0004 (פרה אדומה) \u0003ויעבירם בירדן ובספינה, ו\u0004כן \u0003לא יעמוד בצד זה\u0004 של נהר \u0003ויזרקם לצד אחר, ולא ישיטם\u0004 את מי החטאת ואפר החטאת \u0003על פני המים\u0004 כלל \u0003ולא ירכב על גבי בהמה ולא על גבי חבירו\u0004 כשאפר חטאת בידו, \u0003אלא אם כן היו רגליו\u0004 שלו \u0003נוגעות בקרקע. אבל מעבירן על גבי הגשר ואינו חושש\u0004 מפני הטומאה. ואומרים: \u0003אחד הירדן ואחד שאר הנהרות\u0004 לגזירה זו. \u0003ר' חנניה בן עקביא אומר: לא אסרו אלא בירדן ו\u0004דווקא בהעברה \u0003בספינה, ו\u0004בדיוק באופן \u0003כמעשה שהיה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 אותו \u0003מעשה שהיה?\u0004 ומשיבים, \u0003אמר רב יהודה אמר רב: מעשה באדם אחד שהיה מעביר מי חטאת ואפר חטאת בירדן ובספינה ונמצא כזית מת תחוב בקרקעיתה של ספינה\u0004 והאהילו עליו מי החטאת ונטמאו. \u0003באותה שעה אמרו: לא ישא אדם מי חטאת ואפר חטאת ויעבירם בירדן בספינה.\u0004 וכן כאן המעשה היה בקודש ולא בתרומה, ולכן לא גזרו בתרומה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אמנם ברורה לנו כבר הלכה זו כשמדובר — בדומה למעשה שהיה — בגרימת טומאה על ידי דבר טמא כגון \u0003סנדל טמא,\u0004 אך הבעיה היא \u0003סנדל טהור מהו\u0004 כלומר: אם נשא דבר טהור האם מותר לשאתו עם הקודש? וכן, ברור לנו כאשר מעשה זה היה ב\u0003חבית פתוחה,\u0004 אבל אם היתה זו \u0003חבית סתומה מהו?\u0004 ועוד: אם \u0003עבר ונשא מהו?\u0004 האם גוזרים טומאה מפני שעבר על גזירת חכמים, או לא?","\u0003ר' אילא אמר: אם עבר ונשא — טמא. ר' זירא אמר:\u0004 אם \u0003עבר ונשא — טהור.\u0004","שנינו במשנה: \u0003כלים הנגמרים בטהרה\u0004 צריכים טבילה לקודש, אבל לא לתרומה. ושואלים: \u0003דגמרינהו\u0004 \u0005[שגמר אותם]\u0006 את מלאכת הכלים הללו \u0003מאן\u0004 \u0005[מי]?\u0006 \u0003אילימא דגמרינהו\u0004 \u0005[אם תאמר שגמר אותם]\u0006 \u0003חבר,\u0004 אם כן — \u0003למה להו\u0004 \u0005[להם]\u0006 \u0003טבילה?\u0004 הלא מקפיד הוא בדיני טהרה!","\u0003אלא דגמרינהו\u0004 \u0005[שגמר אותם]\u0006 \u0003עם הארץ\u0004 — וכי אלה \u0003נגמרין בטהרה קרי להו\u0004 \u0005[קורא להם]?\u0006 והרי עצם מגעו של עם הארץ מטמא! \u0003אמר רבה בר שילא אמר רב מתנה אמר שמואל: לעולם\u0004 תפרש \u0003דגמרינהו\u0004 \u0005[שגמר אותם]\u0006 \u0003חבר,\u0004 אלא שגזרו טומאה לקודש \u0003משום\u0004 חשש של \u0003צינורא\u0004 (טיפת רוק) של \u0003עם הארץ\u0004 שאולי ניתזה עליהם ושמא הוא זב וטימאה אותם הטיפה.","ושואלים: \u0003דנפל אימת\u0004 \u0005[מתי נפלה,\u0006 ניתזה טיפה זו\u0005]?\u0006 \u0003אילימא מקמי דליגמריה\u0004 \u0005[אם תאמר לפני שגמר אותו,\u0006 את הכלי\u0005], —\u0006 \u0003הא לאו מנא\u0004 \u0005[הרי לא כלי]\u0006 \u0003הוא,\u0004 ואינו מקבל אז טומאה כלל. \u0003אלא\u0004 ודאי ניתזה עליו \u0003בתר דגמריה\u0004 \u0005[לאחר שגמרו]\u0006 — הלא \u0003מיזהר זהיר בהו\u0004 \u0005[נזהר\u0006 הוא \u0005בהם]\u0006 ואין לחשוש שנטמאו! ומשיבים: \u0003לעולם\u0004 תפרש שמשנתנו מדברת \u0003מקמיה דגמריה\u0004 \u0005[לפני שגמרו],\u0006 \u0003ודלמא בעידנא דגמריה\u0004 \u0005[ושמא בזמן שגמרו,\u0006 את הכלי\u0005]\u0006 \u0003עדיין לחה היא\u0004 אותה טיפת רוק, ולכן היא מטמאה את הכלי הגמור, ושמא האומן לא שם לב שעדיין מצוי רוק על הכלי.","ומעירים: \u0003טבילה — אין\u0004 \u0005[כן]\u0006 צריך הכלי, אבל \u0003הערב שמש\u0004 לאחר טבילה \u0003לא,\u0004 ונחשב טהור מיד.","ואם כן \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' אליעזר\u0004 היא. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שפופרת\u0004 שעשאה מקנה, \u0003שחתכה\u0004 כדי להשתמש בה \u0003לחטאת\u0004 למי אפר פרה אדומה, \u0003ר' אליעזר אומר: יטבול מיד\u0004 לפני שמתחיל להשתמש בה. \u0003ר' יהושע אומר: יטמא\u0004 אותה טומאה ודאית \u0003ואחר כך יטבול. והוינן בה\u0004 \u0005[והיינו עסוקים ב\u0006שאלה זו\u0005]:\u0006 ש\u0003חתכה\u0004 \u0005[שחתך אותה]\u0006 את השפופרת \u0003מאן\u0004 \u0005[מי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003חתכה חבר — למה לי טבילה?\u0004 הלא טהורה היא! \u0003ואלא\u0004 תאמר ש\u0003חתכה עם הארץ,\u0004 וכי \u0003בהא לימא\u0004 \u0005[בזו יאמר]\u0006 \u0003ר' יהושע יטמא ויטבול? הא\u0004 הריהו \u0003טמא וקאי\u0004 \u0005[ועומד]\u0006 משום מגע עם הארץ!","\u0003ואמר רבה בר שילא אמר רב מתנה אמר שמואל: לעולם\u0004 תפרש ש\u0003חתכה חבר, ומשום\u0004 חשש \u0003צינורא\u0004 \u0005[טיפת רוק]\u0006 של \u0003עם הארץ\u0004 שאולי נתזה עליה. ושואלים: טיפת רוק זו \u0003דנפל אימת\u0004 \u0005[שנפלה מתי]?\u0006 \u0003אילימא מקמי דליחתכה\u0004 \u0005[אם תאמר\u0006 שנפלה \u0005לפני שחתך אותה] —\u0006 \u0003הא לאו מנא\u0004 \u0005[הרי לא כלי]\u0006 \u0003הוא\u0004 אלא חומר גלם בלבד שאינו מקבל טומאה, \u0003ואלא\u0004 תאמר שנפלה \u0003בתר\u0004 \u0005[לאחר]\u0006 ש\u0003חתכה — הלא מיזהר זהיר\u0004 \u0005[זהיר]\u0006 הוא \u0003בה!\u0004 ומשיבים: \u0003לעולם\u0004 תפרש שניתזה \u0003מקמי דליחתכה\u0004 \u0005[לפני שחתך אותה],\u0006 ויש לחשוש \u0003דלמא בעידנא\u0004 \u0005[שמא בזמן]\u0006 ש\u0003חתכה עדיין\u0004 טיפת הרוק \u0003לחה היא\u0004 ואז נטמא הכלי.","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יהושע — היינו דאיכא היכירא\u0004 \u0005[הוא שיש\u0006 בכך \u0005היכר]\u0006 \u0003לצדוקין\u0004 שהיו עושים מעשה זה כדי להראות שאין אנו חוששים לדעותיהם.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מטמאין היו את הכהן השורף את הפרה\u0004 האדומה, \u0003להוציא מלבן של צדוקין. שהיו\u0004 הצדוקים \u0003אומרים: במעורבי שמש היתה נעשית,\u0004 שהעוסקים בפרה אדומה חייבים להיות טהורים לגמרי, ומי שטבל ולא שקעה עליו השמש עדיין יש בו מקצת טומאה. וחכמים טימאו בכוונה את העוסקים, כדי להפגין נגד דעת הצדוקים. וזו הסיבה למה שהורה ר' יהושע שצריך לטמא את השפופרת לפני הטבילה.","\u0003אלא לר' אליעזר, אי אמרת בשלמא בעלמא בעינן\u0004 \u0005[נניח אם אתה אומר שבכלל צריך]\u0006 \u0003הערב שמש,\u0004 אם כן \u0003היינו דאיכא היכירא\u0004 \u0005[הוא שיש היכר]\u0006 \u0003לצדוקין,\u0004 שהרי כרגיל לא היתה שפופרת זו נחשבת טהורה לגמרי, ובכל זאת משתמשים בה למי חטאת. \u0003אלא אי אמרת בעלמא לא בעינן\u0004 \u0005[אלא אם אומר אתה שבכלל איננו צריכים]\u0006 \u0003הערב שמש\u0004 וטבילה בלבד דיה להוציא מחשש טומאת מגע עם הארץ — \u0003מאי היכירא איכא\u0004 \u0005[מה היכר]\u0006 \u0003לצדוקין\u0004 \u0005[יש\u0006 כאן\u0005]?\u0006 אלא ודאי סבור ר' אליעזר שצריך הערב שמש, להיטהר מטומאת עם הארץ ונמצא כי משנתנו אינה כשיטתו!","\u0003אמר רב:\u0004 אכן ככלל לשיטת ר' אליעזר אין צורך בהערב שמש לכלים הנגמרים בטהרה, ובכל אופן יש היכר כלפי הצדוקים,"],["לפי ש\u0003עשאוה,\u0004 נהגו בה, בשפופרת זו \u0003כטמא שרץ,\u0004 כאילו נטמאת ממש בשרץ שמטמאה גם אחרים, אבל אינה צריכה הערב שמש, וכבר בכך יש היכר לצדוקים.","ומקשים: \u0003אלא מעתה\u0004 אם כטומאת השרץ היא, \u0003לא תטמא אדם,\u0004 שהרי דבר הנטמא בשרץ שהוא ראשון לטומאה אינו מטמא אדם, ואם כן \u0003אלמה תניא\u0004 \u0005[מדוע שנויה\u0006 ברייתא\u0005]:\u0006 שפופרת זו מי ש\u0003חותכה ומטבילה טעון\u0004 בעצמו \u0003טבילה,\u0004 משמע שהיא מטמאה אדם! \u0003ואלא\u0004 תאמר כי \u0003עשאוה כטמא מת\u0004 המטמא גם אדם, \u0003אי הכי תיבעי\u0004 \u0005[אם כך תזדקק]\u0006 גם שפופרת זו \u0003להזאת\u0004 מי חטאת בימים \u0003שלישי ושביעי\u0004 לטהרתו, ככל דבר שנטמא בטומאת מת,","\u0003אלמה תניא\u0004 \u0005[מדוע שנויה\u0006 ברייתא\u0005]:\u0006 מי שהיה \u0003חותכה ומטבילה — טעון טבילה,\u0004 ונדייק: \u0003טבילה — אין\u0004 \u0005[כן],\u0006 אולם \u0003הזאת שלישי ושביעי — לא!\u0004 ו\u0003אלא\u0004 תאמר כי \u0003עשאוה כטמא מת בשביעי שלו\u0004 לאחר ההזייה, שעדיין מטמא, אבל אינו טעון הזאה נוספת,","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעולם לא חידשו דבר בפרה.\u0004 כלומר, אף שהוסיפו בפרה אדומה הרבה מאד חומרות, בכל זאת לא חידשו בה הלכות שאינן קיימות כלל במקום אחר, וכאן אמרנו שנטמא בה כטמא מת בשביעי שלו, והרי זה סוג טומאה שאינו מצוי בשום מקום!","\u0003אמר אביי:\u0004 לא לענין זה אמרו שלא חידשו אלא \u0003שלא אמרו\u0004 שיהא \u0003קורדום מטמא מושב,\u0004 ובזה שמרו על עיקרי ההלכה בדיני טומאה. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 נאמר בזב: \u0003\"והישב על הכלי\u0004 אשר ישב עליו הזב יכבס בגדיו ורחץ במים וטמא עד הערב\u0003\"\u0004 (ויקרא טו, ו). \u0003יכול כפה\u0004 (הפך) כלי של \u0003סאה וישב עליה,\u0004 או של \u0003תרקב\u0004 (חצי סאה) \u0003וישב עליה יהא\u0004 הכלי \u0003טמא\u0004 משום מושב הזב —","\u0003תלמוד לומר: \"והישב על הכלי אשר ישב עליו... יטמא\"\u0004 (ויקרא טו, ו), כוונתו — שזה \u0003מי\u0004 \u0005[מה],\u0006 כלומר, כלי \u0003שמיוחד לישיבה\u0004 שרגילים לשבת עליו (\"אשר ישב עליו\"), \u0003יצא\u0004 כלי \u0003זה, שאומרים לו\u0004 ליושב עליו: \u0003עמוד ונעשה מלאכתנו.\u0004 וכשם שאינו נטמא משום מושב הזב, אלא במגעו בלבד, כך גם בדיני פרה אדומה לא שינו, ולא גזרו שאף כלי שאינו של ישיבה (כגון קרדום), יטמא בפרה.","שנינו במשנה: \u0003הכלי מצרף מה שבתוכו לקדש אבל לא לתרומה.\u0004 שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 מה מקורם במקרא? \u0003אמר ר' חנין:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כף אחת עשרה זהב מלאה קטרת\"\u0004 (במדבר ז, יד), ללמדנו ש\u0003הכתוב עשאו לכל מה שבכף — אחת,\u0004 שאף שהדברים המצויים בה אינם מחוברים זה לזה, הם נחשבים כיחידה אחת.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב כהנא,\u0004 והרי שנינו: \u0003הוסיף ר' עקיבא\u0004 את \u0003הסלת, והקטרת, והלבונה, והגחלים, שאם נגע טבול יום במקצתו — פסל את כולו,\u0004 לפי שהכלי מצרפם. ואף שאינם כולם דברי אוכל — משום חיבת הקודש גזרו בהם טומאה.","\u0003והא דרבנן\u0004 \u0005[ו\u0006הלכה \u0005זו מדברי סופרים]\u0006 \u0003היא,\u0004 ואינה כלל מן התורה. \u0003ממאי\u0004 \u0005[ממה]\u0006 אנחנו יודעים שהיא מדברי סופרים, \u0003מדקתני רישא\u0004 \u0005[ממה ששנוי\u0006 ב\u0005ראשה]\u0006 של אותה משנה: \u0003העיד ר' שמעון בן בתירא על אפר חטאת ש\u0004אם \u0003נגע הטמא במקצתו — שטימא את כולו\u0004 וכיון שאפר פרה אינו דבר אוכל ואינו קדשי מזבח אין הכלי מצרפן מן התורה, \u0003וקתני\u0004 \u0005[ושנה\u0006 שם\u0005]:\u0006 \u0003הוסיף ר' עקיבא,\u0004 משמע שאף זו שאמר ר' עקיבא היא כמו בהלכה הקודמת — מעלה מדברי חכמים. ואינה מן התורה!","\u0003אמר ריש לקיש משום\u0004 (בשם) \u0003בר קפרא:\u0004"],["\u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 עדותו של ר' עקיבא לעצם ההלכה שכלי מצרף, שהיא מן התורה, \u0003אלא לשירי מנחה\u0004 (המנחה הנשארת לאחר שהקטירו את קומצה ולבונתה, ונאכלת לכהן) שבהם הצירוף הוא רק מדברי סופרים. כי \u0003דאורייתא\u0004 \u0005[מ\u0006דין \u0005תורה]\u0006 כל דבר ה\u0003צריך לכלי,\u0004 כלומר, דבר הצריך להיות בכלי לשם קידושו וכיוצא בזה — \u0003הכלי מצרפו\u0004 לקבל טומאה, למרות שאין כל החלקים נוגעים זה בזה, אבל דבר \u0003שאין צריך לכלי — אין כלי מצרפו.\u0004","ושיירי מנחה, כיון שאינם צריכים עוד לכלי, שכן לאחר קמיצה הם ניתנים לכהן, ואינם צריכים עוד לכלי שיקדשם, אינם מצטרפים מדין תורה, \u0003ואתו רבנן\u0004 \u0005[ובאו חכמים]\u0006 \u0003וגזרו דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003אינו צריך לכלי —\u0004 בכל זאת ה\u0003כלי מצרפו.\u0004","ומקשים: \u0003תינח\u0004 \u0005[נניח]\u0006 תירצת ביחס ל\u0003סלת\u0004 של שיירי מנחות, אבל \u0003קטורת ולבונה מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 עליהן? שהרי בוודאי הן צריכות לכלי, ואם דין צירוף הוא מן התורה לשם מה הוסיף אותן ר' עקיבא? \u0003אמר רב נחמן אמר רבה בר אבוה: כגון שצברן על גבי קרטבלא\u0004 \u0005[טבלת עור]\u0006 ולא בכלי ממש, כי \u0003דאורייתא\u0004 \u0005[מ\u0006דין \u0005תורה]\u0006 כלי ש\u0003יש לו תוך — מצרף, אין לו תוך,\u0004 אלא הוא שטוח — \u0003אינו מצרף, ואתו רבנן\u0004 \u0005[ובאו חכמים]\u0006 \u0003ותיקנו דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003אין לו תוך — מצרף.\u0004","ומעירים \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו של \u0003ר' חנין\u0004 האומרת כי צירוף לענין טומאה הוא מן התורה, על דעת \u0003ר' חייא בר אבא.\u0004 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מעדותו של ר' עקיבא נשנית משנה זו\u0004 שלנו, שמשנתנו שהכלי מצרף מה שבתוכו היא כשיטת ר' עקיבא, ואם כן סבור הוא שאין לדבר מקור בתורה, אלא היא גזירת חכמים בלבד.","שנינו במשנה ש\u0003הרביעי בקדש פסול. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: מנין לרביעי בקדש שהוא פסול — ודין\u0004 (קל וחומר) \u0003הוא; ומה מחוסר כפורים,\u0004 כלומר, טמא שחייב להביא קרבן כדי שיוכל לבוא למקדש ולאכול קדשים, \u0003שמותר ב\u0004אכילת \u0003תרומה,\u0004 בכל זאת \u0003פסול בקדש\u0004 כמפורש בתורה, \u0003שלישי\u0004 לטומאה \u0003שפסול בתרומה — אינו דין שיעשה רביעי לקדש? ולמדנו שלישי לקדש מן התורה\u0004 ממקור אחר \u0003ורביעי בקל וחומר.\u0004","ומסבירים: \u0003שלישי לקדש מן התורה מנין? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והבשר אשר יגע בכל טמא לא יאכל\"\u0004 (ויקרא ז, יט) \u0003מי לא עסקינן\u0004 \u0005[האם אין אנחנו עוסקים]\u0006 באותו כתוב במקרה ש\u0003נגע\u0004 אפילו \u0003בשני\u0004 לטומאה, שאף הוא קרוי טמא, \u0003וקאמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 \u0003\"לא יאכל\"\u0004 משום שנטמא. ו\u0003רביעי\u0004 לקודש נלמד \u0003מקל וחומר — הא דאמרן\u0004 \u0005[זה שאמרנו],\u0006 הקל וחומר של ר' יוסי.","שנינו במשנה: \u0003ובתרומה, אם נטמאת\u0004 ידו אחת — אין ידו האחרת טמאה בטומאת ידים, אבל בקודש נטמאות שתיהן. \u0003אמר רב שיזבי:\u0004 מה שאמרנו שאם נטמא ביד אחת נטמאת גם השניה — \u0003בחיבורין שנו,\u0004 כאשר ידו האחת נוגעת בדבר טמא, וידו השניה נוגעת ביד שנטמאה. \u0003אבל שלא בחיבורין — לא.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003יד נגובה\u0004 (יבשה, שאין עליה משקה) \u0003מטמא חבירתה לטמא לקדש, אבל לא לתרומה,\u0004 אלו \u0003דברי רבי. ר' יוסי בר' יהודה אומר:\u0004 היד איננה מטמאה ממש ואינה יכולה אלא \u0003לפסול, אבל לא לטמא\u0004 אחרים.","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שמדובר אף \u0003שלא בחיבורין — היינו רבותיה\u0004 \u0005[זוהי הרבותא,\u0006 החידוש\u0005]\u0006 שביד \u0003נגובה,\u0004 שאף על פי שיד נגובה שאין עליה משקה אינה מטמאה, מכל מקום גזרו בה וטימאוה לקודש, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003בחיבורין — אין\u0004 \u0005[כן],\u0006 שגזרו בה שמא נגעה הטמאה בקודש, ו\u0003שלא בחיבורין\u0004 — \u0003לא,\u0004 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 ה\u0003רבותא\u0004 \u0005[החידוש]\u0006 ביד","\u0003נגובה? איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 שחלקו אמוראים בענין כעין זה, \u0003אמר ריש לקיש: לא שנו\u0004 שיד אחת מטמאה את השניה \u0003אלא ידו\u0004 של אותו אדם."],["\u0003אבל\u0004 את \u0003יד חבירו לא\u0004 תטמא יד טמאה. \u0003ור' יוחנן אמר: אחד ידו ואחד יד חבירו,\u0004 ודווקא כשנגע \u0003באותה היד\u0004 שנגעה בטומאה, ועוד: ידו הטמאה יכולה רק \u0003לפסול, אבל לא לטמא\u0004 אחרים.","ומעירים: \u0003ממאי\u0004 \u0005[ממה\u0006 מהיכן\u0005]\u0006 למד דבר זה — \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנינו\u0006 ב\u0005סוף,\u0006 בהמשך\u0005]\u0006 המשנה: \u0003שהיד מטמאה\u0004 את \u0003חבירתה לקדש, אבל לא לתרומה.\u0004 ויש לשאול: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי\u0004 לומר שנית? \u0003הא תנא ליה רישא\u0004 \u0005[הרי שנה אותה בתחילה]\u0006 שהיד מטמאה את חבירתה לקודש! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שבא הדבר \u0003לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 שגם את \u0003יד חבירו\u0004 מטמאה, ולא רק ידו שלו.","ומעירים: \u0003ואף ריש לקיש הדר ביה\u0004 \u0005[חזר בו]\u0006 ואמר כר' יוחנן. ש\u0003אמר ר' יונה אמר ר' אמי אמר ריש לקיש: אחד ידו ואחד יד חבירו,\u0004 ודווקא בשנגע \u0003באותה היד\u0004 שנטמאה, ואינה גורמת אלא \u0003לפסול אבל לא לטמא.\u0004","ומעירים: \u0003ו\u0004בענין זה של \u0003לפסול אבל לא לטמא — תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הפוסל בתרומה\u0004 כל דבר שהוא בדרגת שני לטומאה, שמגעו פוסל את התרומה — \u0003מטמא ידים להיות\u0004 אף הן \u0003שניות\u0004 לטומאה. \u0003ויד\u0004 שהיא שניה לטומאה \u0003מטמא חבירתה,\u0004 אלו \u0003דברי ר' יהושע. וחכמים אומרים: ידים\u0004 עצמן \u0003שניות הן, ואין שני עושה שני בחולין.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 ראוי שנדייק מן הלשון כך: \u0003שני הוא דלא עביד\u0004 \u0005[שאינו עושה]\u0006 שיהיה שני כמותו לטמא אחרים, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שלישי עביד\u0004 \u0005[\u0006הוא \u0005עושה],\u0006 שהיד הנוגעת נעשית טמאה בדרגת פסול בלבד. ולפי זה לדעת ר' יהושע היד מטמאה אחרים ואינה פסולה בלבד.","ראיה זו דוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 לדעת חכמים \u0003לא שני עביד\u0004 \u0005[עושה]\u0006 \u0003ולא שלישי\u0004 עושה טומאה כלשהי בנוגע בה, שלדעתם יד שנטמאה אינה מטמאה ואינה פוסלת כלל יד אחרת, ושלא כמשנתנו. ואילו השיטה שבמשנה כדעת ר' יהושע היא, שיד מטמאה ממש.","\u0003אלא\u0004 מחלוקת זו היא \u0003כי הני תנאי\u0004 \u0005[כמו תנאים אלה]\u0006 שנחלקו בדבר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יד נגובה מטמא את חבירתה לטמא בקדש, אבל לא לתרומה,\u0004 אלו \u0003דברי רבי, ר' יוסי בר' יהודה אומר: אותה יד לפסול, אבל לא לטמא.\u0004 הרי שנחלקו תנאים אלה באותו ענין ממש.","שנינו במשנה: \u0003אוכלין אוכלים\u0004 (מאכלים) \u0003נגובין\u0004 (יבשים) שלא הוכשרו לקבל טומאה \u0003בידים מסואבות\u0004 (טמאות שני לטומאה) בתרומה, שהרי לא הוכשרו לקבל טומאה, אבל לא בקודש. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' חנינא בן אנטיגנוס: וכי יש נגובה\u0004 לענין \u0003קדש?\u0004 שהרי ההבדל בין יד נגובה ויד רטובה מתבסס על כך, שהרטיבות מכשירה את הדבר לקבל טומאה, אבל בקודש אין צורך בהכשר הזה, \u0003והלא חיבת הקדש\u0004 עצמה \u0003מכשרתן\u0004 לקבל טומאה, אף דברים שלא נרטבו כלל.","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 ההלכה במשנה אלא \u0003כגון\u0004 שהיו ידיו טמאות אבל \u0003שתחב לו חבירו לתוך פיו, או שתחב הוא לעצמו בכוש\u0004 (פלך) \u0003ובכרכר\u0004 (מחזיק החוט בנול) שהם פשוטי כלי עץ (שאין להם בית קיבול) שאינם מקבלים טומאה ואין האוכל נוגע כלל בידיו במאכל הקודש, \u0003וביקש\u0004 (ורוצה) \u0003לאכול צנון ובצל של חולין עמהם\u0004 שאינן נטמאים מחמת ידיו.","במקרה כזה \u0003לקדש גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 שמא ישכח ויגע בידו הטמאה במאכל הקודש שבפיו, אבל \u0003לתרומה לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים].\u0006","שנינו במשנה ש\u0003האונן\u0004 (לאחר גמר אנינותו) \u0003ומחוסר כפורים\u0004 לאחר שהביא קרבן כפרתו צריכים טבילה לצורך אכילת קודש אבל לא לאכילת תרומה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005] —\u0006 \u0003כיון\u0004 ש\u0003עד האידנא הוו אסירי\u0004 \u0005[עכשיו היו אסורים]\u0006 באכילת קדשים ושמא לא נזהרו כראוי מן הטומאה, לכך \u0003אצרכינהו רבנן\u0004 \u0005[הצריכו אותם חכמים]\u0006 \u0003טבילה\u0004 כהכנה לאכילת קדשים.","עד כאן שנינו מעלות וחומרות שיש בקדשים על התרומה. אולם יש גם \u0003חומר בתרומה\u0004 מבקודש, \u0003שביהודה נאמנין\u0004 הכל (אף עמי הארץ) \u0003על טהרת יין ושמן\u0004 של קדשים \u0003כל ימות השנה, ובשעת הגיתות והבדים\u0004 כאשר דורכים את הענבים יינות ואת הזיתים בגת ובבית הבד לעשיית יין ושמן — נאמנים \u0003אף על\u0004 טהרת \u0003התרומה,\u0004 לפי שבזמן זה הכול מטהרים את כליהם.","\u0003עברו הגיתות והבדים, והביאו לו\u0004 עמי הארץ \u0003חבית של יין של תרומה — לא יקבלנה ממנו\u0004 שמא נטמאו, שהרי בזמן אחר אין נאמנים על כך. \u0003אבל מניחה\u0004 הנותן \u0003לגת הבאה,\u0004 וכיון שבשעת הגת התירו — יכול לתת לו גם את החבית הזו, למרות שלפני כן אסור היה לו לקחת אותה. \u0003ואם אמר לו\u0004 הנותן \u0003הפרשתי לתוכה\u0004 של חבית זו של תרומה גם \u0003רביעית קדש — נאמן,\u0004 שכן אף עמי הארצות נאמנים על טהרה לענין הקדשים ולכן נאמן אף על התרומה שהקדשים מעורבים בה.","\u0003כדי יין וכדי שמן\u0004"],["\u0003המדומעות\u0004 (המעורבות) — \u0003נאמנין עליהם בשעת הגיתות והבדים, ו\u0004כן \u0003קודם לגיתות שבעים יום\u0004 (שאז מתחילים כבר להכין ולטהר לקראת הגיתות והבדים).","שנינו במשנה כי ביהודה נאמנים עמי הארצות על טהרת היין והשמן. ושואלים: \u0003ביהודה — אין\u0004 \u0005[כן]\u0006 נאמנים, \u0003ובגליל — לא, מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל בין המקומות?","\u0003אמר ריש לקיש: מפני שרצועה\u0004 (חבל ארץ) \u0003של כותים\u0004 (שומרונים) \u0003מפסקת ביניהן\u0004 בין יהודה לגליל, וכיון שיש הפסק של ארץ העמים באמצע, וחכמים גזרו שארץ העמים מטמאה, נמצא שאי אפשר להביא קדשים מן הגליל בטהרה ולכן לא נזהרו שם בטהרת הקודש אף החברים. וביהודה ששם רוצים שהיין והשמן ישמשו אף לקודש — נזהרים בטהרתם.","ומקשים: \u0003וניתיב\u0004 \u0005[ונושיב,\u0006 נכניס\u0005]\u0006 את היין והשמן מן הגליל \u0003בשידה\u0004 (ארגז) \u0003תיבה ומגדל\u0004 (ארון) סגורים שיש להם דין אוהל, ואין תוכם מקבל טומאה. ונעבירם מהגליל בטהרה? ומשיבים: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא] —\u0006 שיטת \u0003רבי היא,\u0004 ש\u0003אמר: אהל זרוק,\u0004 כלומר, אוהל המיטלטל ממקום למקום — \u0003לאו שמיה\u0004 \u0005[אין שמו],\u0006 אינו נידון כ\u0003אהל,\u0004 ולכן, אם מטלטלים אוהל — אף תוכו ועל גביו נטמא, ולכן נטמא גם באויר ארץ העמים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנכנס לארץ העמים בשידה תיבה ומגדל, רבי מטמא, ור' יוסי בר' יהודה מטהר.\u0004","ומקשים עוד: \u0003ולייתוה\u0004 \u0005[ושיביאו אותם],\u0006 את הדברים, למקדש \u0003בכלי חרס המוקף\u0004 במכסה \u0003צמיד פתיל,\u0004 שאיננו מקבל טומאה גם באוהל המת, כאמור: \"וכל כלי פתוח אשר אין צמיד פתיל עליו טמא הוא\" (במדבר יט, טז)! \u0003אמר ר' אליעזר, שונין\u0004 אנו הלכה: \u0003אין הקדש ניצול בצמיד פתיל.\u0004 שדברי קודש המצויים באהל המת, אף שהם בתוך כלי צמיד פתיל — נטמאים.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין חטאת,\u0004 מי אפר פרה אדומה, \u0003ניצלת בצמיד פתיל. מאי לאו\u0004 \u0005[האם לא]\u0006 נוכל לדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003קדש ניצול\u0004 על ידי כך, שגזרו רק במי חטאת! ודוחים: \u0003לא,\u0004 אלא כך יש לדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מים שאינן מקודשים,\u0004 שעדיין לא ניתן אפר הפרה עליהם — אף שרוצים להשתמש בהם אחר כך לקידוש מי חטאת \u0003ניצולין בצמיד פתיל.\u0004","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא: חברייא מדכן בגלילא\u0004 \u0005[החברים\u0006 היו \u0005מטהרים בגליל],\u0006 שהיו מטהרים יינם ושמנם בטהרת הקודש לצורך ניסוכם על גבי המזבח, משמע שיש דרך כלשהי להעבירם למקדש! ומשיבים: לא היו מעבירים אותם אלא \u0003מניחין\u0004 אותם, \u0003ולכשיבא אליהו\u0004 את הדרך מהגליל ליהודה \u0003ויטהרנה,\u0004 אזי יביאום.","שנינו במשנה: \u0003ובשעת הגיתות נאמנין\u0004 עמי הארצות \u0003אף על התרומה. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: עם הארץ \u0003הגומר\u0004 לדרוך את \u0003זיתיו\u0004 בבית הבד — \u0003ישייר קופה\u0004 (סל) \u0003אחת\u0004 של זיתים שלא נדרכו ולא נטמאו \u0003ויתננה לעני כהן\u0004 כתרומה, ואותו כהן יעשה ממנה שמן בטהרה. משמע שאפילו בזמן הגתות, שעוסקים במיצוי השמן בבית הבד, אין עמי הארץ נאמנים!","\u0003אמר רב נחמן: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו כי עמי הארצות נאמנים, הרי זה \u0003בחרפי\u0004 \u0005[במוקדמים],\u0006 בזמן הגיתות, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאינם נאמנים, הרי זה \u0003באפלי\u0004 \u0005[במאוחרים]\u0006 שכבר עבר זמן הגיתות אצל רוב האנשים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה: כגון מאי\u0004 \u0005[מה]\u0006 הם הקרויים מאוחרים? אמר לו: \u0003כאותן של בית אביך\u0004 שהיו דורכים במאוחר.","\u0003רב יוסף אמר:\u0004 אפשר לישב את הסתירה בדרך אחרת, זו ששנינו שאינם נאמנים \u0003בגלילא\u0004 \u0005[בגליל]\u0006 \u0003שנו\u0004 אותה, שהרי אמרנו שנאמנים רק ביהודה ולא בגליל. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי: עבר הירדן והגליל — הרי הן כיהודה,\u0004 ש\u0003נאמנין על היין בשעת היין ועל השמן בשעת השמן, אבל לא על היין בשעת השמן ולא על השמן בשעת היין.\u0004 שאף על פי שאנו דנים אותם כטהורים לענין אחד — לא התירו להם לענין אחר. ומכל מקום ראינו שגם בני הגליל הם כיהודה לענין זה.","\u0003אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 \u0003כדשנין מעיקרא\u0004 \u0005[כמו שתירצנו מתחילה],\u0006 ששם מדובר לאחר זמן הגת.","שנינו במשנה שאם \u0003עברו הגיתות והבדים והביאו לו חבית של יין\u0004 — \u0003לא יקבלנה הימנו, אבל מניחה לגת הבאה. בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב ששת: עבר\u0004 הכהן החבר \u0003וקיבלה, מהו שיניחנה\u0004 הוא \u0003לגת הבאה,\u0004 וכיון שיינות ושמנים של עמי הארץ יהיו מותרים אז, יוכל להשתמש גם בחבית זו? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה],\u0006 כלומר, יש בידינו פתרון לשאלה זו מן המשנה:"],["\u0003חבר ועם הארץ שירשו את אביהם\u0004 שהיה \u0003עם הארץ, יכול\u0004 החבר \u0003לומר לו\u0004 לאחיו עם הארץ: \u0003טול אתה חטין שבמקום פלוני\u0004 שהוא יודע שהוכשרו לקבל טומאה, \u0003ואני חטין שבמקום פלוני.\u0004","וכן: \u0003טול אתה\u0004 את ה\u0003יין שבמקום פלוני ואני\u0004 את ה\u0003יין שבמקום פלוני.\u0004 שבורר לחלקו את הדברים הטהורים, שהרי מבחינה חיצונית אינם שונים זה מזה כלל, ויכול לברור לעצמו חלק מסויים מהם. שכל שהם ממין אחד יש לומר \"כי \"יש ברירה\" ומשקיבל כל אחד מהם את חלקו, הוברר הדבר למפרע שהיה זה חלקו מלכתחילה.","\u0003אבל לא יאמר לו: טול אתה לח ואני יבש, טול אתה חטין ואני שעורים.\u0004 שמכיון שכל נכסי אביהם נפלו להם בירושה כאחת, יש לשניהם חלק שווה בכל הדברים, בלח כמו ביבש, וכל שהוא מכמה מינים שונים, אין אומרים ש\"יש ברירה\", ואין די במה שקיבל חלק מסויים כדי לומר שזה היה חלקו מלכתחילה, ומתוך שיתכן שדווקא הדבר הטמא נפל בחלקו של האח החבר, לכך מאחר שיודע בחלק זה שהוא טמא אסור לו לתיתו לאחיו, אף על פי שהאח עם הארץ, כדי שלא לעבור על \"ולפני עור לא תתן מכשול\" (ויקרא יט, יד).","\u0003ותני עלה\u0004 \u0005[ושנה עליה],\u0006 הוסיף כביאור: אם ירש האח החבר ירושה כזו, \u0003אותו חבר שורף\u0004 את \u0003הלח\u0004 אם היתה זו תרומה, שודאי נטמאה, ותרומה טמאה שורפים. \u0003ו\u0004אם הגיע לחלקו יבש — \u0003מניח את היבש\u0004 ומשתמש בו, שמן הסתם לא קיבל טומאה.","ויש לברר: \u0003אמאי\u0004 \u0005[מדוע]\u0006 שורף? \u0003יניחנה לגת הבאה!\u0004 ואז ייחשב הדבר כטהור, אלא ודאי הדבר מוכיח שאין זה מועיל כאשר החפץ הוא כבר ברשותו של החבר. ואם כן נפתרה על ידי כך הבעיה ששאלו מרב ששת. את ההוכחה הזו דוחים: מדובר פה \u0003בדבר שאין לו גת,\u0004 כלומר, במשקים אחרים שאין מביאים מהם לנסכים, שאין להם דין גת לענין טהרה. ומקשים: אם אפשר לסמוך על פתרון כזה, הרי יש עוד אפשרות: \u0003ויניחנו לרגל,\u0004 שהרי אמרנו שברגל נחשבת טומאת עם הארץ כטהרה! ומשיבים: שמדובר כאן \u0003בדבר שאינו משתמר לרגל,\u0004 שיתקלקל ממילא עד הרגל. ואם כן לא נפתרה הבעיה.","שנינו במשנה: \u0003ואם אמר\u0004 עם הארץ \u0003הפרשתי לתוכה רביעית קדש נאמן. תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה אחרת: \u0003מודין בית שמאי ובית הלל שבודקין לעושי פסח ואין בודקין לאוכלי תרומה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003בודקין? אמר רב יהודה אמר שמואל: מנפח אדם בית הפרס והולך.\u0004 כלומר, כשצריך אדם לעבור במקום שיש בו ספק טומאת מת, כגון שדה שנחרש בו קבר וחושש לעבור בכל אותו שדה שמא פזורות שם עצמות קטנות של המת, ואם נוגע בהם — נטמא, אמרו חכמים שיכול לנשוף (\"לנפח\") בזהירות את העפר לפני שהוא צועד, ואם נשף ולא מצא שם עצם — יכול לעבור. והוא שאמרו \"בודקים\", והתירו זאת לאוכלי פסח אבל לא לאכילת תרומה.","\u0003ור' חייא בר אבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא אמר:\u0004 ש\"בודקין\" משמעו \u0003בית הפרס ש\u0004כבר \u0003נדש\u0004 ברגלי העוברים ושיש בו שביל — \u0003טהור לעושי פסח.\u0004 וסומכים שאין כבר שם עצמות. כי \u0003לא העמידו\u0004 חכמים \u0003דבריהן\u0004 שגזרו טומאה על בית הפרס \u0003במקום כרת,\u0004 שהרי מי שאינו עושה פסח בזמנו עובר באיסור כרת, ולכן הקילו עליו לסמוך על בדיקה זו ולא הצריכוהו להמתין ולהזות שלישי ושביעי ולטבול, שהרי אם ימתין, יעבור זמן הפסח ויתחייב כרת.","אבל \u0003לאוכלי תרומה העמידו דבריהן במקום מיתה\u0004 שיש איסור מיתה אם אוכל תרומה טמאה, ומאחר וזמן אכילתה אינו קבוע לזמן מסויים, עליו להמתין ולהזות שלישי ושביעי ולטבול, ורק לאחר מכן יאכל מהם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003בדק לפסחו\u0004 כגון כשעבר בבית הפרס, \u0003מהו\u0004 דינו לענין \u0003שיאכל בתרומתו\u0004 על סמך בדיקה זו? \u0003עולא אמר: בדק לפסחו — מותר לאכול בתרומתו,\u0004 שאם אנחנו חושבים אותו לטהור לענין קודש אי אפשר לחשוב אותו לטמא לענין תרומה. \u0003רבה בר עולא אמר: בדק לפסחו\u0004 — \u0003אסור לאכול בתרומתו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא סבא\u0004 \u0005[זקן אחד]\u0006 לרבה בר עולא: \u0003לא תפלוג עליה\u0004 \u0005[אל תחלוק עליו]\u0006 על \u0003עולא, דתנן כוותיה\u0004 \u0005[ששנינו\u0006 במשנה \u0005כמותו].\u0006 ששנינו במשנתנו: \u0003ואם אמר \"הפרשתי לתוכה רביעית קדש\" — נאמן, אלמא, מדמהימן\u0004 \u0005[מכאן, מאחר שנאמן]\u0006 על ה\u0003קדש מהימן נמי\u0004 \u0005[נאמן גם כן]\u0006 על ה\u0003תרומה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מדמהימן\u0004 \u0005[מאחר שנאמן]\u0006 ונחשב טהור על ה\u0003פסח, מהימן נמי\u0004 \u0005[נאמן גם כן]\u0006 על ה\u0003תרומה.\u0004","שנינו במשנה: \u0003כדי יין וכדי שמן\u0004 המדומעות נאמנים עליהם עמי הארצות בשעת הגיתות \u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003אין נאמנין לא על הקנקנים ולא על התרומה.\u0004 ושואלים: \u0003קנקנים דמאי\u0004 \u0005[של מה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003קנקנים\u0004 של \u0003קדש — מיגו דמהימן\u0004 \u0005[מתוך שנאמן]\u0006 על ה\u0003קדש\u0004 שבתוכם, בהכרח שהוא \u0003מהימן נמי\u0004 \u0005[נאמן גם כן]\u0006 על ה\u0003קנקנים! אלא\u0004 תאמר שהכוונה ל\u0003קנקנים\u0004 של \u0003תרומה\u0004 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי על ה\u0003תרומה\u0004 עצמה הוא \u0003לא מהימן\u0004 \u0005[נאמן],\u0006 ואיך אם כן תאמר על ה\u0003קנקנים\u0004 יהיה \u0003מהימן\u0004 \u0005[נאמן]?\u0006","\u0003אלא\u0004 הכוונה היא \u0003ב\u0004קנקנים \u0003ריקנים\u0004 שהיה בהם \u0003קדש, ובשאר ימות השנה,\u0004 כלומר, בכל ימות השנה, ובזה אינו נאמן על שמירתם, \u0003וב\u0004קנקנים \u0003מלאין\u0004 ב\u0003תרומה ובשעת הגיתות\u0004 שנאמנים על התרומה עצמה ולא על הכלים.","ושואלים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003כדי יין וכדי שמן המדומעות,\u0004 נאמנים עמי הארצות על שמירתם בשעת הגיתות וקודם לגיתות שבעים יום. ומבררים: \u0003מאי לאו\u0004 \u0005[האם לא\u0006 הכוונה\u0005]\u0006 \u0003מדומעות,\u0004 שהיתה בהם תערובת \u0003תרומה.\u0004 ונאמר שהם נאמנים על הכדים, וקשה מכאן על התוספתא האומרת שאינם נאמנים על הקנקנים! ומשיבים: \u0003אמרי דבי\u0004 \u0005[אומרים\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא:\u0004 לא, הכוונה היא \u0003מדומעות\u0004 ב\u0003קדש,\u0004 שיש בהם משהו של קדשים בפנים.","ושואלים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 בכלל דין \u0003דימוע לקדש?\u0004 האם הביטוי דימוע שייך לענין קודש? \u0003אמרי דבי\u0004 \u0005[אומרים\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אלעאי:\u0004 הכוונה היא \u0003במטהר\u0004 (שומר בטהרה) \u0003את טבלו\u0004 (שעדין לא הופרשו ממנו תרומות ומעשרות) משום שכוונתו \u0003ליטול ממנו נסכים\u0004 והרי שיש כאן קודש תרומה וחולין כאחת, וכיון שנאמן על טהרת הקודש נאמן גם על התרומה.","שנינו במשנה שפרט לזמן הגיתות עצמו, נאמנים עמי הארצות גם \u0003קודם לגיתות שבעים יום. אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 אגב ענין הלכות טהרה כי \u0003דינא\u0004 \u0005[דין]\u0006 \u0003הוא דעילויה אריסא למיטרח אגולפי שבעים יומין מקמי מעצרתא\u0004 \u0005[שעל האריס לטרוח\u0006 ולהשיג \u0005את הקנקנים\u0006 כבר \u0005שבעים יום לפני\u0006 זמן \u0005בית הבד],\u0006 שהרי במשנה נחשב זמן זה כזמן ההכנה לקראת עצירת השמן.","\u0003מן המודיעים ולפנים,\u0004 כלומר, סביב ירושלים כמרחק מהיישוב מודיעים לירושלים (שהוא חמישה עשר מיל), \u0003נאמנין\u0004 הכל \u0003על כלי חרס\u0004 לומר שהם טהורים. לפי שמשם מספקים את כלי חרס לירושלים. ולא גזרו חכמים טומאה בהם. \u0003מן המודיעים ולחוץ — אין נאמנין.\u0004 ומפרטים עד כמה הגבילו גזירה זו, \u0003כיצד? הקדר שהוא מוכר הקדרות, נכנס לפנים מן המודיעים,\u0004 אף על פי ש\u0003הוא הקדר והן הקדרות\u0004 עצמן היו קודם מחוץ למודיעין \u0003והן הלוקחין\u0004 (הקונים) — הרי הוא \u0003נאמן\u0004 לענין טהרה. וכן להיפך: אם \u0003יצא\u0004 מחוץ לתחום מודיעים, אותו אדם עצמו שבתוך התחום החזקנוהו כנאמן — שוב \u0003אינו נאמן.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003מודיעים\u0004 עצמה \u0003פעמים\u0004 נחשבת \u0003כלפנים, פעמים כלחוץ. כיצד?\u0004 אם \u0003קדר יוצא\u0004 מתחום ירושלים \u0003וחבר נכנס\u0004 אל התחום, והם נפגשים במודיעים — דינה \u0003כלפנים\u0004 ומותר לחבר לקנות את כדיו. אבל אם \u0003שניהן נכנסין\u0004"]]};
